WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[82698] = { title = "Haywired and Hostile", description = "I saw many machines nearby, and all of them seem to make dreadful noises. I cannot hear the one that I heard in the vision, though, at least not clearly.\n\nDestroy the excess ones. They are only in the way.\n\nWhile you are quieting the scene, I will hunt and scout.", objectives = "Destroy the haywire excavators.", progress = "You're not who I expected to see here.", completion = "Looks like you're interested in the foreman's office too, huh?\n\nDon't get cranky, we're on the same side here. I just can't get close without being seen. \n\nAnd then there's just one big, clanking wrinkle to this whole mess." }
WordHunterWoW_QuestEN[82699] = { title = "Hey, What's Going On?", description = "Time to do some networking. \n\nThere's a bunch of goblins outside of Opportunity Point, over there in the Abyssal Excavation. I heard some of them grumbling as they started their shift.\n\nLet's see what some friendly words shake loose.\n\nWhile you're out there, check out the used fuel drums. They wouldn't let me look inside the full drums, but they just drop the used ones around the work site.", objectives = "Search for clues by questioning goblins and uncovering evidence in the Abyssal Excavation.", progress = "We've got to stop meeting like this. Assuming we've met before, which, maybe we have.", completion = "Those goblins only know part of the story. What's in there is the full story, or at least, a big piece that's missing." }
WordHunterWoW_QuestEN[82700] = { title = "Built to Blast", description = "We've got an intel problem, but we've also got a clank problem.\n\nIf you look over there, there's a big, haywire mech that's just going crazy. There's no way anyone's going to uncover anything while that's out in the field.\n\nWe should do something about that.", objectives = "Destroy the Haywire MEK IV.", completion = "It would seem that we are all searching for information, but I have some that I think is useful.\n\nAnd it's too late to hide now, they've seen my true form. \n\nLet's see this through to the end." }
WordHunterWoW_QuestEN[82701] = { title = "Bat Versus World", description = "When I scouted, I heard and saw things that I don't understand. \n\nPerhaps if I describe it to you and the goblins, you will know what it means.", objectives = "Experience Orweyna's scouting mission.", completion = "After I escaped from that place, I saw you battling the gigantic machine, and I had to join in the fight.\n\nNow it seems there really is no going back. I am alone here, except for you, and these goblins." }
WordHunterWoW_QuestEN[82702] = { title = "Found Friends", description = "So Gallywix has chosen to show his ugly face here, and it looks like he's got himself organized.\n\nWe should report this to Alleria. See how she wants to handle it.", objectives = "Report to Alleria in Dornogal.", completion = "You've brought me far more than just information. \n\nAlthough I have a feeling that this... Orweyna... will not give up her secrets easily. I should be patient. I am sure that we will find common ground eventually.\n\nIn the meantime, there is someone that she should talk to." }
WordHunterWoW_QuestEN[82706] = { title = "Delves: Worldwide Research", description = "It's been all quiet recently. I've nae heard of any issues. \n\nThis seems like a good opportunity for exploration, eh? I'm at yer disposal! We can go wherever it is ye want tae go!", objectives = "Complete 3 Delves in The War Within.", progress = "Dangerous exploration? Survivin' by the skin of our teeth? Makes this ol' <race> feel alive!", completion = "Got tae see some nice places today. That's always good. Gets the ol' heart pumpin'." }
WordHunterWoW_QuestEN[82707] = { title = "Delves: Earthen Defense", description = "Just the person I was lookin' for!\n\nMerrix mentioned that the earthen have been havin' problems recently, and I thought tae myself, \"Brann, you know who likes solving problems? <name>!\"\n\nWant tae go put on yer delvin' hat?", objectives = "Complete 2 Delves in the Isle of Dorn or The Ringing Deeps.", progress = "Feels good tae be doing good work.", completion = "There is nae anythin' that can stand in the way of Brann and <name>!\n\nHmm, <name> and Brann? Not sure what way sounds best. I'll add it tae the tae do list." }
WordHunterWoW_QuestEN[82708] = { title = "Delves: Nerubian Menace", description = "<name>! Come in, come in!\n\nI've been talkin' tae everyone in Dornogal, and it seems like the nerubians have been kickin' up a fuss all over Khaz Algar. \n\nWhat's say you and I go put on our spider kickin' boots and give them somethin' tae really fuss about?", objectives = "Complete 2 nerubian Delves.", progress = "I better not get webs on my hat again. Took me weeks tae find all the strands from last time!", completion = "That'll teach those nerubians tae not be so feisty, eh?\n\nYou set them up, I knock them down! Or tae other way around. I'm not fussy." }
WordHunterWoW_QuestEN[82709] = { title = "Delves: Percussive Archaeology", description = "I've been investigatin' all of the interesting looking pieces we've found in our travels. Many of them are critical tae Azeroth's history! And those rotters in the delves are just smashin' them up without a care in the world!\n\nLet's put a stop tae it and recover what we can. I bet if we went up against one of the really tough crowds, they'd have loads of fragments for us.", objectives = "Recover 30 Khaz Algar Archeological Fragments from Delves in Khaz Algar.", progress = "I cannae believe that some folks don't care about history. Just makes me sad.", completion = "We may have just got fragments, <name>. But with fragments, ye can rebuild it. Ye can see what it once was.\n\nFragments are better than dust, is all I'm saying." }
WordHunterWoW_QuestEN[82710] = { title = "Delves: Empire-ical Exploration", description = "Champion of the hour, here tae see little ol' me!\n\nI've been talkin' to Faerin, and apparently the critters in the delves of Hallowfall have been actin' up. Or is it actin' down?\n\nDoes nae matter, does it? What's say we go and help them out, eh?", objectives = "Complete 2 Unique Delves in Hallowfall.", completion = "I just dinnae understand why anyone would attack the Arathi. Everyone there is trained tae be on the offensive! \n\nSeems like the daftest folks tae attack." }
WordHunterWoW_QuestEN[82711] = { title = "Delves: Lost and Found", description = "I have a bit o' a personal request, <name>. I lost some of my tools on our adventures. My lucky letter opener, my compass...\n\nAnd ye may have already noticed, but I'm wearing a different hat. This one is a tatty ol' rag compared tae the glorious one I normally have on my head!\n\nCan we go investigate some of the delves and see where I left them?", objectives = "Recover Brann's 3 lost belongings in Delves around Khaz Algar.", progress = "Looking forward tae getting this ugly hat off my head!", completion = "Oh, my hat... I love ye, hat. \n\nAnd the other stuff too, I love them as well. Just not as much as my hat." }
WordHunterWoW_QuestEN[82712] = { title = "Delves: Trouble Up and Down Khaz Algar", description = "I'm hearin' there's trouble all over Khaz Algar right now. Delve critters are getting all feisty. \n\nWe should go handle it! Top tae bottom, show them that gettin' aggressive is not in their best interests!", objectives = "Complete a Delve in the Isle of Dorn and a Delve in Azj-Kahet.", completion = "That's a... remarkably literal interpretation of my earlier comments, <name>. \n\nBut still, we showed them the dangers of gettin' too aggressive--aggression right back at 'em!" }
WordHunterWoW_QuestEN[82739] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths." }
WordHunterWoW_QuestEN[82740] = { title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths." }
WordHunterWoW_QuestEN[82746] = { title = "Delves: Breaking Tough to Loot Stuff", description = "I've been itchin', <name>. \n\nItchin' to teach the delve critters a lesson! We need tae hit them hard. Hit the tough ones, so the weak ones will nae even poke their heads out!\n\nWill ye join me?", objectives = "Complete two Delves of Tier 6 or above.", completion = "Woo! We came, we saw, we kicked 'em in the face!\n\nKhaz Algar is safer now from the predations of evil critters. Good days work, eh?" }
WordHunterWoW_QuestEN[82747] = { title = "Crossroads Plaza", description = "Hello, outlander. Do you want to know about news from outside the city?\n\nThe Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts.\n\nMy friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.", objectives = "Meet Bondaz in Crossroads Plaza.", completion = "...An outlander? You are real! Just like the others that have stopped by. There are so many of you!\n\nI can't believe my eyes. I know everything about the isle, but could not have fathomed this." }
WordHunterWoW_QuestEN[82748] = { title = "Deephaul Ravine", description = "We've received reports of troubles in the earthen depths. Explore the Deephaul Ravine and the resources available, then report to Ruffious.", objectives = "Complete the Deephaul Ravine battleground.", completion = "You made it through the mines! Splendid!" }
WordHunterWoW_QuestEN[82762] = { title = "Keeping a Close Tabard", description = "Wow!\n\nThat's a super nifty tabard! And it's all yours to customize however you want.\n\nKessa should be able to help you bring your designs to life.\n\nGo ahead and pay her a visit to get started!", objectives = "Speak with Kessa in the Victorious Visage.", progress = "Kessa is a very skilled tabard designer!", completion = "I'd be happy to help you design your personal tabard!" }
WordHunterWoW_QuestEN[82768] = { title = "Cloud Fishing", description = "Now that we have the eels, we can try to lure the cloudrooks back to land. \n\nHead over to the neighboring island. Get as close as you can and make an offering to the rooks. \n\nWith luck, they'll cease their circling and come down for a nourishing meal.", objectives = "Offer 7 Electric Eels to Wild Cloudrooks.", progress = "Nothing better than electric eels to sate a tired and hungry cloudrook.", completion = "Now I understand. This is how the rooks bring their own over from the elemental plane. They weren't mourning so much as calling out to their departed kin.\n\nThank you for your help, outlander. You've helped me better understand these beautiful creatures." }
WordHunterWoW_QuestEN[82771] = { title = "Heritage of the Earthen", description = "The time has come to give back to the Archives. \n\nAll earthen wanderers are invited to share their experiences for the preservation of what has come before and the betterment of those who will come after. \n\nThis knowledge and experience of the wider world of Azeroth is a priceless treasure, and the practice of sharing it is key to our earthen heritage.", objectives = "Upload experiences to the Archives in Dornogal.", progress = "Have you uploaded your experiences yet?", completion = "We cannot thank you enough for this gift. Your experiences will be invaluable to the <race> still now awakening in the Ringing Deeps. Please accept this and wear it proudly as you continue to travel amongst the peoples of Azeroth and beyond." }
WordHunterWoW_QuestEN[82773] = { title = "A Functional Favor", description = "I am seeking my mentor, Foreman Arbauch. He is... missing. Under other circumstances, I would send for a search party from Gundargaz, but there is no time.\n\nI suspect he passed through here, but the only lead I have is DelGizmo. He wants the local fog beasts removed. Reluctance. But if he has seen Arbauch, I must learn what he knows.\n\nThe lurkers to the south carry powerful Galvanic Glands. They have enough charge to disperse even the thickest fog. Retrieve some. Compensation assured.", objectives = "Collect 6 Galvanic Glands.", progress = "Haste is appreciated. I must find Arbauch.", completion = "Approval. These seem quite energetic. They will allow you to scare off the fog beasts for DelGizmo." }
WordHunterWoW_QuestEN[82774] = { title = "Antifogmatic", description = "Machine speakers have no love for fog beasts. Where there is fog, rust is sure to follow. Still, I'd prefer not to harm them. Arbauch always said it was bad luck.\n\nTake this device. The glands you collected should provide enough power to disperse the fog without hurting the fog beasts within.\n\nCaution. Fog beasts are skittish, but other creatures may also lurk.", objectives = "Disperse the fog around Camp Murroch.", progress = "Is it done? We have little time to waste.", completion = "Fine work. I hope DelGizmo's information is worth the trouble." }
WordHunterWoW_QuestEN[82775] = { title = "Quickchange Artist", description = "You seem to have the programming of a great actor within you, {name}!\n\nI know it because I have that fire myself--no matter what the rest of these so-called \"actors\" say.\n\nI'm very impressed with how fast you change costumes. I am a master of the quickchange artist's ways myself, you know.\n\nYou're very close to figuring it out. You just need a few pointers from an expert--like me!", objectives = "Receive tips from Wendeline in the Proscenium.", completion = "See, character is as much in the costume as it is you. \n\nPracticing getting in and out of costume fast is just as important as practicing lines.\n\nNow you can switch roles quickly and be a virtuoso of versatility!" }
WordHunterWoW_QuestEN[82776] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[82777] = { title = "Tracking Quest", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[82778] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Nibbling Minnow, Arathor Hammerfish, Queen's Lureback.", completion = "These are some great catches, <name>--I can't wait to see what you'll reel in next week!" }
WordHunterWoW_QuestEN[82781] = { title = "Attention-Getter", description = "My, {name}, it seems you have drawn the attention of a particular audience member.\n\nThis fan letter was mistakenly included in my fan mail. I'm not surprised. Sorting my copious fan mail must be a difficult chore...\n\nHere, take it. It belongs to you, of course.\n\nI'm sure this is very new for you. I have a few pieces of wisdom for greeting eager fans, if you would like to hear it...", objectives = "Receive tips from Elma in the Proscenium.", completion = "We must be careful with fans. We must be gentle with their feelings but also discourage unwanted behaviors.\n\nKind and gracious acknowledgement of their gratitude is key. A simple thank you note in return is optimal. And if you see them here, it is acceptable to nod and wave. We want our audience to be happy, of course.\n\nAnd, in the event they bring flowers... I can graciously take that burden from you." }
WordHunterWoW_QuestEN[82782] = { title = "Authenticity in Dress", description = "You've done very well as an actor on stage, {name}.\n\nBut as an actor in a troupe, there are other directives we must carry out. One directive is to preserve our costumes for use in future plays. Many costumes we use more than once.\n\nI think we can trust you with using and preserving the troupes' costumes, don't you think? It would mean you could practice with us more frequently...", objectives = "Speak with Rabaan in the Proscenium.", completion = "Excellent. I cherish every barrier I can remove between an actor and their directive.\n\nTreat the costumes with care. We will be using them in future plays, remember.\n\nGood luck! And don't forget you're part of the troupe now!" }
WordHunterWoW_QuestEN[82783] = { title = "Chromie's Codex", description = "Hello there! I could really use your help. \n\nYou see, my codex has gotten a bit jumbled in all my travels lately, and I have to give a time tour back to the gates of Ahn'Qiraj in an hour. \n\nI need you to jump in with me to sort out any... inconsistencies. Then it should be right as rain and all the visitors here will have a fun, not-super-dangerous tour!", objectives = "Complete the Codex of Chromie event.", progress = "Whew, that was pretty dicey there for a moment. I thought you might not have made it!", completion = "Thanks so much for the help!\n\nI'm so excited for my first tour. It's MUCH more likely that no one will die or get lost now, thanks to you. Not that it has happened... ever..." }
WordHunterWoW_QuestEN[82784] = { title = "Resonant Performance", description = "{name}, I have learned a lot from watching you perform. You change your nature so easily. In one play, I have seen you change from enemy to friend, from anger to sorrow... It's like watching mercury flow.\n\nWith you on our stage, I feel we complete our plays to the letter of our directives with the highest satisfaction for our audience.\n\nIf you have a moment, I would like to thank you for your support.", objectives = "Speak with Burkhalt in the Proscenium.", completion = "We decided that this was the least we could do to thank you for sharing your experience with us.\n\nI have much more to learn myself. So please, join us for another play." }
WordHunterWoW_QuestEN[82785] = { title = "Ghosts in the Machine", description = "There's a substation directly below us? Perhaps that is where Arbauch went to hide it... Disregard, we must investigate.\n\nWith luck, Arbauch may still be here. The entrance should be to the north, near the pool of water from the burst pipe. Please, come with me. He may need our help.\n\nI will explain everything once he is located.", objectives = "Find Foreman Arbauch.", completion = "It killed him, and we let it loose. Even his memory gem is gone." }
WordHunterWoW_QuestEN[82786] = { title = "Duty of Care", description = "The golem is unstable. I doubt it can travel far. We will track it, but haste failed me once already. Arbauch showed true devotion to the machines--we will follow his example. Repairs must come first.\n\nMachine systems are delicate. We must activate the backup before the failure can cascade. Exterminate any pests you find as well. Even the smallest creature can ruin delicate machinery.\n\nI am damaged. I will send my cogwalker with you to relay instructions.", objectives = "Activate the backup systems along the Cataract River.", progress = "Our primary duty is to mend.", completion = "The backup systems are operational. Now we may track the golem." }
WordHunterWoW_QuestEN[82787] = { title = "Special Assignment: Rise of the Colossals", description = "WQUpon completion of this quest you will gain:", objectives = "Kill Colossal beasts" }
WordHunterWoW_QuestEN[82792] = { title = "All Ore Nothing", description = "Outlander. Your aid is requested. \n\nThe earthen here have said you would be of help. \n\nOur fellow earthen at the Opalcreg have not reported their quota for the past day. There must be something causing a disruption.  \n\nWould you pay Foreman Alvegar a visit?", objectives = "Go to the Opalcreg and seek out Alvegar.", completion = "I'm hiding... lay low. \n\nForeman Germira sent you? She must be worried that we haven't sent over our quota." }
WordHunterWoW_QuestEN[82796] = { title = "Third Mine Blind", description = "I got cut off from the rest of the crew. We did not expect to be attacked by nerubians. Though I can't imagine the rest quitting.\n\nOur duty is too important to give up just yet. \n\nBarging right into the mine could cause the nerubians to frenzy and hurt the others. So, I found a third way to get in earlier. Though undetected will still be tough. \n\nFollow me.", objectives = "Meet Alvegar at the third entrance of the Opalcreg.", completion = "You made it undetected, good. Time to surprise these Nerubians!" }
WordHunterWoW_QuestEN[82797] = { title = "Hit Rock Bottom", description = "A long way down to be sure, but I am certain that you can make it. \n\nIf you doubt yourself, I made some parachutes to help you stick the landing. \n\nOnce you get to the bottom of the cave, look for Cenderragg. She's the most senior of the group and probably has the best idea on how to rescue the team.", objectives = "Get to the bottom of the mine and find Cenderragg.", completion = "Who are you and why are you here?" }
WordHunterWoW_QuestEN[82798] = { title = "An Opal of Mine", description = "I'll be direct with you. We have a goal here and those opals are the center of it. \n\nNo one will leave until we get the job done, the opals are too important. If you could gather enough ore, we could convince them to leave.  \n\nBut be careful, those nerubians are dangerous.", objectives = "Help Cenderragg collect 8 Opal Ore from the Opalcreg.", progress = "Why did the nerubians have to show up? We were almost complete.", completion = "We collected much. I worry that it still won't be enough." }
WordHunterWoW_QuestEN[82799] = { title = "Web Beats Rock", description = "So, Foreman Alvegar sent you? That explains it.\n\nThe situation is not great. This place is crawling with nerubians and they're showing us no mercy. They forced us to mine and took our hard-earned opals. \n\nWhen you disobey, they web you up. \n\nI was barely able to escape them when they came. The others... Well, that's where you come in.\n\nWith you here distracting them, I can go rally the webbed earthen.", objectives = "Rescue 6 earthen workers in the Opalcreg.", completion = "Thank the machine! They're free!" }
WordHunterWoW_QuestEN[82800] = { title = "A Sedimental Moment", description = "Some have started to evacuate, but there's a stubborn few that just won't let go. \n\nCould you say something? \n\nMaybe an outsider's perspective will get them moving.", objectives = "Help Cenderrag inspire the earthen workers in the Opalcreg.", progress = "Why must these few be so stubborn?", completion = "It worked! Thank you. \n\nAny earthen saved is a great moment for us all. No matter how long we have left." }
WordHunterWoW_QuestEN[82801] = { title = "Beetlejeweled", description = "To make sure no other earthen gets harmed we're going to have to eliminate their leader. \n\nYou know the saying, rid yourself of the foreman and the whole line collapses. \n\nEither way, to get to safety we're going to have to go through them.", objectives = "Defeat Kix'arak outside of the Opalcreg Mine.", completion = "You made it back, I was beginning to think all hope was destroyed. \n\nAlvegar filled me in with the issue. I'm just glad all our people are safe, and we got the opal too.\n\nA small win, but a win." }
WordHunterWoW_QuestEN[82809] = { title = "Gryphons of a Feather", description = "Hey there! I notice ye got a stormrook that's lookin' rather unhappy. Let's see what we can do to cheer 'em up.", objectives = "Find a way to cheer up Squally.", progress = "Kwee wah?", completion = "<Squally chirps with delight, hopping around excitedly.>" }
WordHunterWoW_QuestEN[82810] = { title = "Time Found", description = "Yer back!\n\nIf you're up for it, there's more things in the muck to be found. Might have to dig a bit deeper this time.", objectives = "Find 6 lost mementos.", progress = "What'd you find?", completion = "Same as before, I'll have you take some of these to see if we can't find their owners." }
WordHunterWoW_QuestEN[82813] = { title = "Time Borrowed", description = "Ah, now there's my good friend! Me and Mags are still here, looking for memories. Got a moment to spare for help?", objectives = "Find 6 lost mementos.", progress = "What'd you find?", completion = "These definitely have stories to them. See if you can't find their owner again.\n\nAnd thanks. Don't know if we'll find much more." }
WordHunterWoW_QuestEN[82814] = { title = "Decommissioning Darkness", description = "Decommissioning a machine is a rare necessity. It must be done with care and regret.\n\nWe put much of ourselves into our work. To destroy it is to destroy a part of ourselves. In doing so, we admit our failure to protect the Titans' work.  But where stone rebels against stone, we must stand firm.\n\nImperative: Destroy it. Recover Arbauch's memory gem.", objectives = "Destroy the Corrupted Golem and recover Foreman Arbauch's memory gem.", progress = "Regret. This should have been my burden.", completion = "There is no joy in the death of a machine, but I express gratitude. I suspect Arbauch would too. \n\nHis decisions were his own, but none can doubt that he devoted his life to the machines. The Titans would be proud." }
WordHunterWoW_QuestEN[82815] = { title = "Sturdy Locket", description = "What do you have there?", objectives = "What do you have there?", progress = "What do you have there?", completion = "Wait... this locket." }
WordHunterWoW_QuestEN[82817] = { title = "Disturbance Detected: Blackrock Depths", description = "The Timewalkers claim that they detected a time-displaced object in Blackrock Depths.\n\nWhile that fight may have ended in our defeat, the Dark Iron clan knows what's at stake should history change. We could lose the current dwarven alliance and all the good it has brought.\n\nRecover the object and protect our current peace.", objectives = "Recover the Timewarped Ironforge Blueprints from Emperor Thaurissan in Blackrock Depths.", progress = "It brings me no pleasure, asking you tae fight against us. I feel for the bronze dragons and all the work they do tae protect the timeline.", completion = "Strange that I must thank you for ensuring my clan's utter defeat. But from the ashes we rose, soot and all.\n\nThank you, champion." }
WordHunterWoW_QuestEN[82832] = { title = "Wooden Figure", description = "Got a cat problem?", objectives = "Got a cat problem?", progress = "Got a cat problem?", completion = "Ah, this is cute. Couldn't tell you where it came from - it appears to be made by a hobbyist rather than an artisan. I'll put it up on display though." }
WordHunterWoW_QuestEN[82835] = { title = "Calcified Journal", description = "Are you looking for someone?", objectives = "Are you looking for someone?", progress = "Are you looking for someone?", completion = "Ah! I haven't seen this in years..." }
WordHunterWoW_QuestEN[82836] = { title = "Zero Out Xerosh", description = "{name}, the nerubians all seem to be taking orders from that siegelord south of here. If we can defeat her, that may turn the tide of this attack.\n\nWithout a leader organizing the attack, the Arathi may be able to drive back the nerubians, especially if Faerin is able to light this dawntower she spoke of.\n\nBut the longer we delay, the greater damage to the Arathi airships. Go quickly!", objectives = "Defeat Siegelord Xerosh.", progress = "Were you able to defeat the siegelord?", completion = "With the nerubian leader defeated, we should be able to leave the defenses to the Arathi.\n\nYou've saved many lives today, <name>." }
WordHunterWoW_QuestEN[82842] = { title = "Test Quest - Combined First time Rewards (DNT)", description = "This quest should give the following rewards for first / additional completions on the act\n\nDragon Isles Supplies (stupid complex setup): \nFirst Time : 101,025 + 9075  bonus\nAdditional: 101,025\n\nValdrakken Rep (Simple setup with flags):\nFist time: 25 + 75 bonus\nAdditional: 25\n\nMaruuk Centaur (simple setup with modifier only)\nFirst time completion: 25 + 75 bonus\nAdditional Completion: 25 \n\nDragonscale (modifier + combine)\nFirst Time: 25 + 100 bonus\nAdditional: 25\n\n(DNT)", objectives = "Kill 8 Screechflight Witherers and 10 Screechflight Hexclaws." }
WordHunterWoW_QuestEN[82843] = { title = "Something Earthy", description = "Ah, another one of you lot, eh? Well, if you want to eat, you need to help.\n\nPick me a fresh taro, will you?", objectives = "Harvest a nearby taro plant for the chef", progress = "Have you brought the taro?", completion = "Oh. Well... you tried." }
WordHunterWoW_QuestEN[82844] = { title = "Something Not Ruined", description = "Alright, I'll come with you. Show you how to do this properly. If I'm up, we might as well stock up on taro. Can't rely on adventurers to do delicate work, I suppose.", objectives = "Harvest 6 taro with the chef. Properly, this time.", progress = "Is that all of them?", completion = "Much better. This will last for a while. If you want to eat, though, I'll need a little more help." }
WordHunterWoW_QuestEN[82845] = { title = "Ivory Tinderbox", description = "What brought you to the Priory, outsider?", objectives = "What brought you to the Priory, outsider?", progress = "What brought you to the Priory, outsider?", completion = "A lost item?\n\nThis is mine, but I hesitate to say it was lost." }
WordHunterWoW_QuestEN[82846] = { title = "Dented Spearhead", description = "We meet again. How can I help you?", objectives = "We meet again. How can I help you?", progress = "We meet again. How can I help you?", completion = "Ah, I thought I simply misplaced this." }
WordHunterWoW_QuestEN[82847] = { title = "Enough Garlic", description = "Normally, this would do. I'm not so picky. But you're a guest. So we'll need some garlic.\n\nI found some growing on a hill not far off. Shouldn't be there. But it is.\n\nToo bad hydras found it, too.\n\nYou have weapons and such, right?", objectives = "Collect garlic for the chef.", progress = "You think that's enough?", completion = "Ahh, there we go. That is enough garlic." }
WordHunterWoW_QuestEN[82848] = { title = "Sous", description = "Alright, now help me finish this.", objectives = "Help the chef prep a meal. Stand by the chef's table and use meal prep abilities to assist.", progress = "Time to cook!", completion = "Thanks, stranger. It's nice to have some company to pass the time. Good luck on your travels." }
WordHunterWoW_QuestEN[82849] = { title = "Filigreed Cleric", description = "Got a request from the kitchen?", objectives = "Got a request from the kitchen?", progress = "Got a request from the kitchen?", completion = "Well look here. I was wondering where this was." }
WordHunterWoW_QuestEN[82852] = { title = "Special Assignment: Lynx Rescue", description = "WQUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[82894] = { title = "The Price of Hope", description = "{name}, good to see you. I am about to make a trip to the local infirmary. \n\nWould you care to join me?", objectives = "Meet General Steelstrike in the Mereldar Infirmary.", progress = "We lose so many, we need to save those we can.", completion = "Thank you. If you can come back and help Kaeleb another day, it would be much appreciated." }
WordHunterWoW_QuestEN[82895] = { title = "The Weight of Duty", description = "I am now the caretaker of Mourning Rise.\n\nAt last, I feel the weight of this new responsibility on my shoulders. It is a great honor, but one I must prepare myself for.\n\nPlease, help me complete one final task, and then I will be ready.\n\nMeet me back at Fallside Outpost.", objectives = "Meet Urtago at Fallside Outpost to help her take on her new role.", progress = "One more task, and then I shall truly be the caretaker.", completion = "You brought Korgran peace in his final moments, and now you have helped me fill his absence.\n\nYour aid will not be forgotten." }
WordHunterWoW_QuestEN[82916] = { title = "When Fungi Bloom", description = "Greetings! \n\nPerhaps you can help me with some busy work? I have so many orders that I have miscalculated several units of Mycobloom. To be honest, a bit more than several.\n\nWill you be kind and gather the rest for me?", objectives = "Gather 20 Mycobloom for Akdan in Dornogal.", progress = "I don't mean to rush, but I need the mycoblooms as soon as possible. Please.", completion = "Thank you <name>! These are wonderful samples.\n\nHere, take this as my appreciation for your time." }
