WordHunterWoW_QuestEN[82990] = { title = "Undoing the Damage", description = "Apologies. Arbauch was not here for repairs--he stole that golem.\n\nArbauch and I worked alongside it for years in the darkest reaches of the Deeps. The work took its toll on the golem. It became erratic, dangerous even. We planned to decommission it, but when the time came, Arbauch couldn't bear it. He'd become attached. Before it could be destroyed, he took it and fled.\n\nIt must be found, but the damage to this substation is catastrophic. With your help, I will attempt repairs.", objectives = "Defend Danagh while he repairs the substation.", completion = "A foreman and a substation lost. Blast. I was careless." }
WordHunterWoW_QuestEN[82992] = { title = "Stormcharged Goods", description = "Greetings my friend!\n\nI am looking for someone who is willing to run a quick errand. I am running out of goods and I have not heard from my leather supplier for quiet some time. If I can not supply skins and leathers, the leatherworker will not be able to produce apparels.\n\nI will reward you if you can bring me several Stormcharged leathers.", objectives = "Gather 20 Stormcharged Leathers and deliver them to Ginnad in Dornogal.", progress = "Any good news? I still have not heard from my leather supplier.", completion = "You have the leathers? Titans be praised!" }
WordHunterWoW_QuestEN[82993] = { title = "From Shadows", description = "Hello there!\n\nI have heard of fantastic materials that can be thread and put together from some... peculiar materials.\n\nIf you are the type who enjoys travelling through the last sunny parts of Khaz-Algar, will you be kind enough to gather Kaheti Swarm Chitin and Sunless Carapace for me? I will reward you nicely if you can supply me with some samples.", objectives = "Gather 5 Kaheti Swarm Chitin and 5 Sunless Carapace, and deliver them to Ginnad in Dornogal.", progress = "I feel a certain eagerness to get my hands on these materials.", completion = "How peculiar. There is no saying what can be achieved with these materials. Only time would tell, titans willing." }
WordHunterWoW_QuestEN[82994] = { title = "Wax Contribution", description = "", objectives = "" }
WordHunterWoW_QuestEN[82995] = { title = "Nerubian Device", description = "A strange device of Nerubian origins. Aevery Flamestonge at Hillhelm Stead might be intrigued by this.", objectives = "Deliver the Nerubian Device to Aevery Flamestonge at Hillhelm Stead.\n\nProvided item:", completion = "This is incredibly intriguing. \n\nIt's possible that the Nerubians utilize this device to manipulate spiders and other creatures to harass our farms." }
WordHunterWoW_QuestEN[83021] = { title = "LFGDungeons - TWW - Normal Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[83022] = { title = "LFGDungeons - TWW - Normal Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
