WordHunterWoW_QuestEN[83024] = { title = "The Stormrider's Bond", description = "So, you think yourself worthy of a Stormrider's armor?\n\nWe Stormriders were titan-made to fight and to ride stormrooks. Even so, we must prove our competence in battle before we gain clearance to wear Stormrider armor. I see no reason why you should not undergo the same challenges.\n\nGo. Show me you have the power of the storm within you.", objectives = "Collect 50 Storm Spirits by slaying powerful creatures of Khaz Algar.", progress = "Come back only when you've proven yourself worthy.", completion = "Hm. Clearance granted.\n\nThis armor is generally reserved for Stormriders. But for your valor, I give you special clearance. Wear it with pride." }
WordHunterWoW_QuestEN[83025] = { title = "A Sacred Connection", description = "I may have granted you clearance to wear our armor, but to focus the storm's power through it as the greatest Stormriders do...\n\nThe greatest Stormriders in our order do not merely possess the power of the storm. They have mastered it. And this mastery is forged over many battles.\n\nIt is time to prove yourself as one of our best.", objectives = "Collect 500 Storm Spirits by slaying powerful creatures of Khaz Algar.", progress = "Your reward shall be properly equal to your efforts.", completion = "Yes. This is the mastery seen in the greatest Stormriders. Let this armor be proof of that.\n\nWear your armor with pride. It is not an honor to be taken lightly." }
WordHunterWoW_QuestEN[83026] = { title = "LFGDungeons - TWW - Heroic Random - Nth", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[83027] = { title = "LFGDungeons - TWW - Heroic Random - 1st", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[83028] = { title = "Thieving Snufflers", description = "", objectives = "" }
WordHunterWoW_QuestEN[83031] = { title = "The Hardest Part", description = "<Aethas sighs heavily, his voice tinged with sorrow.>\n\nDalaran... once a symbol of unity and arcane mastery, now reduced to rubble and ash. Again.\n\nSo much loss and so much pain. Friends and comrades gone in an instant, their voices silenced by Xal'atath. \n\n<He takes a deep breath, steeling himself against the overwhelming grief.>\n\nBut now is the time for action--not grief. We must regroup with the remaining Kirin Tor.\n\nHowever, the right words do not come easily.", objectives = "Help Aethas Sunreaver send a message to the surviving mages of Kirin Tor in the Tranquil Strand.", progress = "What does one say in times like these?", completion = "We have taken the first step at least.\n\nNow, we wait." }
WordHunterWoW_QuestEN[83040] = { title = "DO NOT USE", description = "", objectives = "" }
WordHunterWoW_QuestEN[83043] = { title = "Carved Crests", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
