WordHunterWoW_QuestEN[83057] = { title = "Setting Boundaries", description = "Vi'azl has undergone a level of torture that I was unaware of. We cannot help Vi with his fear until Vi is actually safe.\n\nWhenever possible, I advocate friendship, recovery, and reconciliation. I ask others to act with compassion and empathy. Everyone deserves a chance to recover. I dedicate my life to this.\n\nBut hearing and seeing what is happening to Vi'azl... I think I've changed my mind. Enough is enough. We must act.", objectives = "Kill the Ascended nerubian who is torturing Vi'azl.", progress = "Nobody deserves this torturous treatment.", completion = "These Ascended nerubians have been mutated beyond empathy or community. It pains me, but I must focus on those that can be saved, like Vi'azl." }
