WordHunterWoW_QuestEN[83081] = { title = "Not Enough Minerals", description = "I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either.\n\nPeacekeeper Hektare will nae let me fight, but maybe she will let you.\n\nI'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal.\n\nOh, but... Brinthe really needed those opals...", objectives = "Collect 6 Earthen Fire Opals from the Opalcreg in the Isle of Dorn.", progress = "I'm sure I can make a poultice for this earthen. Oh, 'tis a shame I cannae get any opals.", completion = "Fire Opals? You found some?\n\nBrinthe'll be so pleased!\n\nThis earthen seems to be feeling better as well. A win-win all around!" }
WordHunterWoW_QuestEN[83082] = { title = "The Opalfront", description = "I'm a city guard, not a soldier! But these people need our help!\n\nThere are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us.\n\nThat one was too small. But you look like a fighter. Help us!", objectives = "Kill nerubian forces at the Opalcreg in the Isle of Dorn.", progress = "We will do what we can to help the miners escape.", completion = "Thank you, outlander. You have given them a fighting chance." }
WordHunterWoW_QuestEN[83083] = { title = "A Place Forgotten", description = "There is... a place behind Dornogal that I cannot go.\n\nAnd I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city.\n\nThis, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will.\n\nThe site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there.\n\nWe will see.", objectives = "Meet with Speaker Brinthe and Dagran behind Dornogal in the Isle of Dorn.", completion = "I cannot describe what this place feels like to me.\n\nIt is... oppressive. I cannot think.\n\nThe urge to turn back is... strong." }
WordHunterWoW_QuestEN[83084] = { title = "The Old Orders", description = "Long ago, there were once plans to build a tunnel through the mountain into Dornogal. \n\nBefore excavation could begin, the surrounding area was suddenly abandoned. \n\nThere is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region.\n\nEvery part of my cognitive matrix is pressing for me to leave. But we must persist. \n\nThe device's signal indicates something lies within the nearby tower.", objectives = "Investigate the abandoned tower behind Dornogal.", progress = "I'm not sure what's afflicting Brinthe, but it's clear she's in pain. I offered to escort her back to the city but she refused.\n\nI will stay with her an' make sure she does nae take a turn for the worse and try an' figure this device out more too.", completion = "Forget what ye found in the tower--did ye see that?! Those looked like titan watchers!\n\nBut... what does it all mean? And who were they?" }
WordHunterWoW_QuestEN[83085] = { title = "DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[83087] = { title = "The Old Guard", description = "Dornic... Galan... I've heard those names at the Proscenium!\n\nBut who was speakin'? They were nae happy with Galan. All those earthen bodies...\n\nRepurposed... like reprogrammed? Tae protect what?\n \nLet's chase the other signal. Looks like it leads up ahead intae the hills.\n\nI'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.", objectives = "Follow the signal and witness a second memory", progress = "I'll stay here with Brinthe. I dunnae want anythin' to happen tae her.", completion = "You saw another memory? And it attacked ye?\n\nThat's awe--I mean, I'm so glad ye are okay.\n\nWhile ye were tracin' the signal, I found more notes. I put 'em together for ye to read. It's more about Dornic and Galan.\n\nBut it looks like we know where Galan ended up at least without 'em--buried under tons o' rock. But what was she guardin'?\n\nWhat was so important that she was repurposed tae safeguard it for thousands of years?\n\nArgh! We have more questions than answers. I dunnae like it." }
WordHunterWoW_QuestEN[83088] = { title = "Caustic Collectables", description = "Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now...\n\nIt's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. \n\nI think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him.\n\nThat's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!", objectives = "Collect 6 Stinging Residue from Acidic Salvage in The Vatworks.", progress = "Have you found enough residue from the oozing salvage?\n\nMake sure to get the really nasty stuff. You know, the stuff that sticks to you but also melts your skin?", completion = "That's it! That's the stuff!\n\nMaybe Enkle will listen to me this time..." }
WordHunterWoW_QuestEN[83089] = { title = "Giving Goblins Goggles", description = "My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help.\n\nOur whole crew only listens to him! Which means no one's wearing proper protective equipment.\n\nTake these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.", objectives = "Talk to 5 Slimedivers in The Vatworks.", progress = "Everyone's working along this river here. You can't miss them!\n\nUnless they haven't found the river. But that only happens half the time, so I'm sure it's fine.", completion = "<Kazzandra cheers.>\n\nFinally! Everyone's here, and they're all wearing goggles. Enkle had better listen to me this time!" }
WordHunterWoW_QuestEN[83091] = { title = "Shield Your Eyes", description = "Causticaria? Is he crazy? No one has ever been able to process that monster!\n\nWe have to stop Enkle before he gets himself hurt!\n\nCausticaria lurks down this canal. Grab your goggles and follow me!", objectives = "Defeat Causticaria in The Vatworks.", progress = "Has Causticaria gotten even bigger? The stench is burning my nose hairs from here!", completion = "He's okay! Thank you so much for your help, <name>!" }
WordHunterWoW_QuestEN[83092] = { title = "An Igneous End", description = "When the magma transport pipe failed, our workers rushed down to begin repairs.\n\nThe elementals caught us unawares, rising up and attacking with great gouts of lava.\n\nFortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood.\n\nSmash their stony prisons and free my workers!", objectives = "Free Entombed Earthen from their stone shells near Hallowfall Gate.", progress = "Don't worry about hurting them, just get them free.", completion = "Thank you, topsider. With our crews returned, we can get back to work." }
WordHunterWoW_QuestEN[83096] = { title = "Welcome to Undermine", description = "There ya are! I'm Grimla. Welcome to Undermine. If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me.\n\nI've got a coupon you can use at the Incontinental Hotel. We'll start there.\n\nLet's take a ride in \"Gramps,\" my hot rod! Hop in when you're ready.", objectives = "Go to the Incontinental Hotel with Grimla and learn more about Undermine.", progress = "Did you hear anything good while you were gettin' yourself settled?", completion = "So, that's the Incontinental Hotel. Things go downhill from here." }
WordHunterWoW_QuestEN[83097] = { title = "Cinder and Storm", description = "The wild creatures here have stunning properties. I wonder what might happen if I combine them?\n\nBe on the lookout for Bottled Storm and Burning Cinderbee Setae. I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.", objectives = "Gather 5 Bottled Storm and 5 Burning Cinderbee Setae, and deliver them to Ginnad in Dornogal.", progress = "Who knows what could happen if we combine these materials!", completion = "Wonderful! I can't wait to get to work." }
WordHunterWoW_QuestEN[83098] = { title = "Snap and Crackle", description = "Do you have a moment?\n\nI'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide, I'd be more than happy to compensate you.", objectives = "Gather 5 Honed Bone Shards and 2 Thunderous Hide, and deliver them to Ginnad in Dornogal.", progress = "Together, these materials will make a real statement.", completion = "Just what I was looking for! Can't wait to put them to use." }
WordHunterWoW_QuestEN[83099] = { title = "Mergers and Acquisitions", description = "When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" \n\nBut now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits.\n\nPlease help fix this, {name}.", objectives = "Defeat Goldie Baronbottom and help Wenbrandt reclaim the Cinderbrew Meadery.", progress = "Thinking about those goblins in my meadery... Oh, it makes my head feel molten. And that makes me think of my cinderbrew!", completion = "A heartfelt thank you for what you did at the Cinderbrew Meadery. \n\nDriving away Venture Co. was no small feat, but thanks to you, we've reclaimed our beloved meadery and will resume making cinderbrew the right way--the way we've made it for centuries." }
WordHunterWoW_QuestEN[83100] = { title = "Cracking the Shell", description = "Welcome!\n\nYou wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin. If you find some, bring it to me. I'll see to it you get paid.", objectives = "Gather 20 Gloom Chitin and deliver it to Ginnad in Dornogal.", progress = "Manage to lay your hands on some yet?", completion = "Perfect timing, we were just about to run low." }
WordHunterWoW_QuestEN[83101] = { title = "Reaching for Resources", description = "", objectives = "" }
WordHunterWoW_QuestEN[83102] = { title = "Bismuth is Business", description = "Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth.\n\nAnd we don't have nearly enough! Wherever you go, keep an eye out for Bismuth. Bring me as much as you can. \n\nCompensation is assured.", objectives = "Gather 20 Bismuth and deliver it to Tarib in Dornogal.", progress = "Bismuth is business, and business is booming!", completion = "You're back? Gratitude. You clearly know how to use a pick." }
WordHunterWoW_QuestEN[83103] = { title = "Acquiring Aqirite", description = "You there!\n\nHave you heard of Aqirite? Valuable, versatile, very often surrounded by nerubians.\n\nI need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.", objectives = "Gather 10 Aqirite and deliver it to Tarib in Dornogal.", progress = "Well, have you got it yet?", completion = "Aqirite is always appreciated. I'll get it to where it needs to be." }
WordHunterWoW_QuestEN[83104] = { title = "Identifying Ironclaw", description = "I sent a team to mine some Ironclaw Ore, they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground!\n\nI'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.", objectives = "Gather 10 Ironclaw Ore and deliver it to Tarib in Dornogal.", progress = "Trust me, you can't miss it.", completion = "Appreciation expressed. I knew I could count on you." }
WordHunterWoW_QuestEN[83105] = { title = "Rush-order Requisition", description = "Good to see you, I've got work.\n\nThe blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it.\n\nLooks like you'll need to track down Aqirite and Ironclaw Ore.", objectives = "Gather 5 Aqirite and 5 Ironclaw Ore, and deliver them to Tarib in Dornogal.", progress = "Do you have them? The smiths have been chewing my ear off.", completion = "Excellent work. These ores will be greatly appreciated." }
WordHunterWoW_QuestEN[83106] = { title = "Null Pebble Excavation", description = "Ever seen a Null Stone? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple.\n\nWhile you're at it, pick up any Bismuth you find. You can never have enough Bismuth.", objectives = "Gather 10 Bismuth and 2 Null Stone, and deliver them to Tarib in Dornogal.", progress = "Any luck with those Null Stones?", completion = "Marvelous! Hope you didn't go to too much trouble finding these." }
WordHunterWoW_QuestEN[83108] = { title = "Daily Diagnostics", description = "It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine.\n\nDescribing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines!\n\nSolution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.", objectives = "Take diagnostic readings of 4 machines within the Stonevault.", progress = "There are numerous consoles that assist with the running of the great machines within the Stonevault. Work does not cease, even in the face of this madness.\n\nPlease, get me those readings as soon as you can!", completion = "Thank you for getting me those readings. Hopefully the analysis will show that everything is in order with the great machines. \n\nUntil it has been deemed safe for us to return to the Stonevault I'm stuck here cooling my gears. But at least I know what today's readings are like." }
WordHunterWoW_QuestEN[83109] = { title = "The Grimla Express", description = "Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. \n\nI'm not sure who runs it now, if anyone does.", objectives = "Head to Tailgate Park in Grimla's hot rod.", completion = "They look up to Gazlowe. Maybe you folks showing up will give 'em a little hope." }
WordHunterWoW_QuestEN[83110] = { title = "Deliver Equipment", description = "Deliver safety equipment to Steamwheedle goblins to allow them to perform black blood experiments more safely.", objectives = "Deliver safety equipment to Steamwheedle goblins to allow them to perform black blood experiments more safely." }
WordHunterWoW_QuestEN[83113] = { title = "Recover Tools", description = "Kill black blood slimes and recover tools absorbed by the slimes.", objectives = "Kill black blood slimes and recover tools absorbed by the slimes." }
WordHunterWoW_QuestEN[83114] = { title = "Red Tape", description = "First it was just Black Blood, now ethereals?\n\nI don't know how all this squares, but we need help if we wanna find out.\n\nOrweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.", objectives = "Find Alleria at Slam Central Station.", progress = "We shoulda known. These guys see an outsider unescorted and try to pull a fast one.\n\nSee if you can change their minds.", completion = "Now that Alleria's here, let's get to the bottom of this business--startin' with Noggenfogger." }
WordHunterWoW_QuestEN[83115] = { title = "In the Mix", description = "I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him.\n\nSteamwheedle's headquarters is probably a good place to start lookin' for him.\n\nWe'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.", objectives = "Speak to Marin Noggenfogger at the Vatworks.", progress = "You see how many Darkfuse they've got here?", completion = "<Gazlowe lowers his voice.>\n\nThey've got this place crawlin' with Darkfuse. Noggenfogger's bein' watched. Closely." }
WordHunterWoW_QuestEN[83116] = { title = "Potion Commotion", description = "It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday.\n\nA day when I'm under no forms of duress or coercion whatsoever! N-None at all.\n\n<Cautiously, he glances at the Darkfuse guards, then whispers to you.>\n\nI'll tell you whatever I can if you get rid of them.\n\n<He nods subtly towards his alchemy station.>", objectives = "Collect some Semi-Deluxe Noggenfogger Elixirs, then use them to distract 8 Stationed Labguards.", progress = "I'll keep an eye on Noggenfogger. You get it done.", completion = "Venture and kaja'mite. Two more puzzle pieces.\n\nLet's hope they all fit together eventually." }
WordHunterWoW_QuestEN[83117] = { title = "Chasing a Lead", description = "Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends.\n\nWe knew they was working with Gallywix, we just didn't know how deep they were in with him.\n\nLet's go check out those kaja'mite supply lines. No time to lose.", objectives = "Meet Gazlowe outside the Heaps.", completion = "Lots of Darkfuse, but less than they had back at Steamwheedle. Probably 'cause Venture's more compliant." }
WordHunterWoW_QuestEN[83118] = { title = "Check the Schedule", description = "If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that.\n\nUp ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up.\n\nGrab as many as you can find. We'll check out Venture's headquarters in the meantime.", objectives = "Gather 3 Employee Schedules.", progress = "They should have schedules posted all over the place. Hopefully this isn't a wild flamingo chase.", completion = "<Gazlowe reads over the schedules quickly, his expression souring.>\n\nWell, good news is Noggenfogger wasn't lyin'.\n\nBad news is... this is a LOT of names. All gettin' sent to the Kaja'Coast in Zuldazar." }
WordHunterWoW_QuestEN[83119] = { title = "It's Worth a Shot", description = "Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet.\n\nMaybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work.\n\nVenture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you.\n\nSee if you can get 'em to quit. If they start a fight, do what you gotta do.", objectives = "Attempt to convince 10 Underpaid Workers to quit Venture Co.", completion = "That'll do.\n\nEven one fewer goblin workin' for Gallywix is a win in my book." }
WordHunterWoW_QuestEN[83120] = { title = "Stealing the Keys", description = "If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here.\n\nLead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. \n\nShould be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?", objectives = "Slay Lead Foreman Krome.", progress = "You clear the way for Renzik to get the punch card yet?", completion = "<Gazlowe grimaces as he inspects the foreman's weapon.>\n\nThe battery in this thing is powered by Black Blood.\n\nI don't know how they managed to do that without the thing exploding, or worse. But this situation just got a whole lot more dangerous." }
WordHunterWoW_QuestEN[83121] = { title = "Asset Management", description = "I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward.\n\nWe need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.", objectives = "Slay 6 Venture Supervisors in the Lucky Break Mines.", progress = "It won't stop the kaja'mite supply for good, but at least it'll slow them down.", completion = "Good. The fewer Venture Co. around who are loyal to Gallywix, the better." }
WordHunterWoW_QuestEN[83122] = { title = "Crashing the Market", description = "When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation.\n\nBlow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.", objectives = "Destroy 5 Kaja'mite Stockpiles in the Lucky Break Mines.", progress = "We need to keep that kaja'mite out of circulation.", completion = "When all this is done, Bilgewater will come back here, clean this up, and do it right." }
WordHunterWoW_QuestEN[83123] = { title = "A Miner Mistake", description = "<On the corpse of the Venture Co. employee, you find a crumpled piece of paper stuffed into an envelope. It appears to be a paystub from a kaja'mite depot in the Venture Co. area of Undermine.\n\nBelow the full address of the employer, there is a header stamped in red ink.>\n\nGALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT\n\n<A note from Gallywix is poorly taped to the back of the paystub.>", objectives = "Read the Crumpled Paystub, then bring it back to Gazlowe.", progress = "What do you got there?", completion = "Well, that answers that.\n\nVenture Co. is gettin' paid by one of Gallywix's secret warehouses back in Undermine.\n\nThat means he's hoardin' all of this kaja'mite back there. What could he possibly need that much for?" }
WordHunterWoW_QuestEN[83124] = { title = "B.I.R.D. Watching", description = "I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does.\n\nI don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers.\n\nYou wanna do us the honors, {name}? I'll talk you through it.", objectives = "Control the Hotwired B.I.R.D. to spy on Darkfuse activities on the Kaja'Coast.", progress = "They'll never suspect nothin'.", completion = "There's the last puzzle piece. Gallywix used Black Blood and kaja'mite to make those weapons, and now he's usin' it to repair the Dark Heart." }
WordHunterWoW_QuestEN[83125] = { title = "Price Hike", description = "So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse.\n\nThese stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.", objectives = "Slay Overseer Dritz, then meet up with Gazlowe in Undermine.", completion = "Damn it--Noggenfogger's hurt real bad.\n\nFirst Darkfuse, now ethereals. What could they possibly want with Steamwheedle?" }
WordHunterWoW_QuestEN[83126] = { title = "Ethereal Invasion", description = "Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming.\n\nNow they're searching every building and killing anyone who stands in their way.\n\nI don't know what they're looking for, but we can't allow them to continue this slaughter.\n\nLet's teach them a lesson.", objectives = "Kill 12 ethereals in the Vatworks.", progress = "We cannot let this chaos continue.", completion = "The ethereals were not expecting to meet resistance here. They were wrong." }
WordHunterWoW_QuestEN[83127] = { title = "Racing the Clock", description = "We were out of time before, but now we're REALLY out of time.\n\nThe ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart.\n\nC'mon!", objectives = "Meet Gazlowe outside Gallywix's secret warehouse in the Heaps.", completion = "At least the ethereals took care of most of the Darkfuse. That's... good, probably." }
WordHunterWoW_QuestEN[83128] = { title = "Get Our People Out", description = "While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe.\n\nThey left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.", objectives = "Save any hostages Gallywix is keeping in the warehouse and slay 10 Ethereal Heartseekers.", completion = "The hostages are safe. Gallywix doesn't have leverage on any of the cartels anymore.\n\nTime to finish this." }
WordHunterWoW_QuestEN[83129] = { title = "Nowhere Left to Hide", description = "This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one.\n\nGallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.", objectives = "Destroy the Makeshift Barricade, then follow Gazlowe into the Hoardroom to confront Gallywix.", completion = "<Gazlowe exhales heavily, glowering back at the smoking teleporter.>\n\nThis is over. Let's leave." }
WordHunterWoW_QuestEN[83130] = { title = "Sour Victory", description = "That's it. It's over. We're done.\n\nGallywix lost, but the ethereals got the Dark Heart.\n\nAlleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.", objectives = "Meet Gazlowe at the Scrapshop in Bilgewater Flats.", completion = "<Gazlowe keeps his arms crossed, staring at some spot of nothing in the distance.>" }
WordHunterWoW_QuestEN[83137] = { title = "When Opportunity Explodes", description = "There ya are, {name}! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps.\n\nThere were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.", objectives = "Investigate the blasted hole in Opportunity Point.", completion = "It's... a tollbooth?\n\nYou've gotta be kiddin' me.\n\n<Monte Gazlowe rolls his eyes and laughs softly.>\n\nI guess you can make money off of anythin'!" }
WordHunterWoW_QuestEN[83138] = { title = "End of the Day", description = "Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands.\n\nWhich means we can leave. Nothin' left for us to do here.\n\nFinish up whatever business you've got in Undermine. I need to get out of this damn place.", objectives = "Speak to Renzik.", completion = "<Gazlowe wipes something ashen from his cheek, hand trembling as he stares down at it.>" }
WordHunterWoW_QuestEN[83139] = { title = "Mixed Messages", description = "Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.", objectives = "Pay the toll at the tollbooth, then gather information from the northern goblin camp.", progress = "See what these goblins know about the area!", completion = "Maybe whoever wanted that wall blown up also wants our attention here. We gotta dig deeper." }
WordHunterWoW_QuestEN[83140] = { title = "Hostile Work Environment", description = "Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out.\n\nI'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.", objectives = "Kill Darkfuse to keep the heat off Gazlowe and Renzik.", progress = "Give us some time!", completion = "All eyeballs were on you, that was great. And you brought us a new resource, this Zirdo fella? Good thinking." }
WordHunterWoW_QuestEN[83141] = { title = "Miner Investigations", description = "What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood.\n\nWe must get a closer look. Together we will gain insight into their operation.", objectives = "Examine suspicious canisters and crates with Orwenya.", completion = "My visions suggest there is more to the south. We should move on soon. \n\nDoes this goblin you discovered have more information?" }
WordHunterWoW_QuestEN[83142] = { title = "Order of Magnitude", description = "<This document requires anyone with information about who opened the western wall to bring the information to their supervisor. \n\nIt details the reward: a promotion to working inside Undermine. It also includes a promise of the favor and \"appreciation\" of Gallywix.\n\nGazlowe will want to know about this.>", objectives = "Give the Bounty from Gallywix to Gazlowe.", progress = "What'd you find?", completion = "Gallywix is controllin' the Darkfuse directly, and wants to know who worked against him. We could have an ally out here. That's a big clue, <name>." }
WordHunterWoW_QuestEN[83143] = { title = "Good Honest Work", description = "You're new here, right? I can tell by your questions. But don't worry, Zirdo's your best pal!\n\nI'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!", objectives = "Follow Zirdo on his \"tour.\"", progress = "I lack words.", completion = "I lack words." }
WordHunterWoW_QuestEN[83144] = { title = "Bloodletting", description = "The land aches underfoot. These pipes carry Black Blood north in a massive volume!\n\nI've never seen the land become infected this rapidly. Clear away the rot--perhaps we can save it yet.\n\nI'll go after the structures. Point out weak spots as you find them and I will focus our assault!", objectives = "Kill Black Blood creatures and signal Orweyna to attack weak points in the pipeline.", progress = "The horrors these goblins have brought forth are truly a blight on this land.", completion = "I mistrust any of the goblins responsible for this pipeline.\n\nBe cautious, <name>." }
WordHunterWoW_QuestEN[83145] = { title = "Paranoia Prevention", description = "What information is Gallywix after here in Gutterville? Let's see if some of these goblins will give us a hint. \n\nLet's start with any Bilgewater goblins we can find.", objectives = "Investigate Gutterville's spy problem.", progress = "This seems like it's more about keeping people quiet than actually learning anything.", completion = "I hope Renzik catches up with Zirdo before he can blab, but we shouldn't count on it." }
WordHunterWoW_QuestEN[83146] = { title = "Pamsy's Prized Pump", description = "I got a team of engineers. All of them got families. They keep having horrible accidents and infections from the Black Blood. I just couldn't stand another death. I opened the wall. I wanted it to bring us some hope.\n\nYou show up and want to stop the Black Blood. It doesn't do anythin' good to stop these pipes up here. We gotta get to the pump station.\n\nSo, my crew and the pumps? They're all at the same station. But we should hurry.", objectives = "Go to the pump station and meet Pamsy.", completion = "I can't believe it. Zirdo must have told Overseer Gozzic about me. This is a clear message to stop..." }
WordHunterWoW_QuestEN[83147] = { title = "Bloody Business", description = "The horrors of the Black Blood here cannot be underestimated. The strength of it in this place is causing my visions to feel distant, like odd whispers.\n\nKill the manifestations of this rot, before they grow stronger.", objectives = "Kill blood horrors for Orweyna.", progress = "I cannot ignore this blight on the land.", completion = "It will take much more to staunch these wounds. We must not tire." }
WordHunterWoW_QuestEN[83148] = { title = "X-Treme Chill", description = "Pamsy and I came up with an idea. Since we can't access the controls, and we can't blow it up, what if we freeze the pump station?\n\nStay with me!\n\nPamsy mentioned that a lot of the machines up north are overheating lately, because all the coolant is being used down south. And it's even harder to get, because the blood slimes eat it. What if we found all of that coolant supply and dumped it into the pump station? \n\nWe put the whole operation on ice, and it'd take ages to fix!", objectives = "Kill Chillgut Slimes to collect Chillburst Canisters.", progress = "Get enough to freeze this station solid!", completion = "Great, that's a good haul!" }
WordHunterWoW_QuestEN[83149] = { title = "Avenge Them", description = "I followed Zirdo's trail south. I found a nasty piece o' work named Gozzic Cogcrane pushin' workers around and talking about \"another lesson.\" Zirdo must have snitched to this Gozzic guy, but I need to confirm it. I think this Gozzic will have the proof on him.\n\nGozzic could've given the orders, but lookin' at that bloody shredder and the marks on Pamsy's crew, I'm sure he got involved personally. You should do the same. Kill Gozzic and check him for any sign Zirdo got word to him.", objectives = "Kill the Darkfuse that killed Pamsy's engineers.", progress = "These engineers deserved better.", completion = "You found proof? I knew it. Not as good as getting Zirdo himself, but we'll catch up with him in the end." }
WordHunterWoW_QuestEN[83150] = { title = "Expanding the Plan", description = "Here's the plan. If we just freeze the outside, it'll all melt in a bit and go back to normal. But we got Orweyna. She can target cracks and leaks in the pipes so the coolant can get inside and really muck things up.  \n\nSince you gathered all the canisters, I think you should get the honor of freezing the pipe solid.\n\nPamsy has a rocketboard, and you'll be able to dispense icy justice down upon the station's key areas. Follow Orweyna!", objectives = "Ride the rocketboard and shoot the pipeline with ice.", progress = "Hop onto the rocketboard and shoot away!", completion = "Nice ice work! Ha!" }
WordHunterWoW_QuestEN[83151] = { title = "Down Undermine", description = "We've done what we could here. It's time to get a look at Undermine.\n\nPamsy's got a contact, a Venture goblin named Grimla. We can start there when we arrive.\n\nLet's get Gazlowe and get going. Undermine's not the kinda problem you solve with a knife. We need someone like Gazlowe on board for this. You know, the builder and leader type.", objectives = "Talk with Gazlowe, then go to Undermine using the rocket drill.", completion = "I hope Renzik and Pamsy know what they're doin' with Grimla here." }
WordHunterWoW_QuestEN[83152] = { title = "Magmanagement", description = "As if the pipe going down wasn't enough, a horde of magmatic elementals burst out when it failed.\n\nWe can't risk sending anyone else down to attempt repairs while the area is overrun, but that magma is vital to powering the whole Deeps.\n\nIf you are capable, clear them out so we can get that magma flowing again.", objectives = "Kill Risen Magma and Slag Bubbles near Hallowfall Gate.", progress = "Is it done?", completion = "Commendable job. We could do with a little less excitement in our work." }
WordHunterWoW_QuestEN[83153] = { title = "Sampling Steam", description = "The effects of the magmatic buildup are clear to see, but what we still do not understand is the root cause.\n\nIn order to determine it, and prevent it in the future, I need samples of the volcanic gases you can see bursting from the ground.\n\nFresh samples. Very fresh.\n\nYou're going to have to stand in them as they erupt in order to gather what I need.", objectives = "Stand in gas vents near Hallowfall Gate as they erupt to gather samples.", progress = "Do you have the samples?", completion = "Hopefully these samples will reveal what went wrong. Your assistance is appreciated." }
WordHunterWoW_QuestEN[83154] = { title = "Knicknack's Knickknacks", description = "Not fair! Not fair! Knicknack collect many shiny things over long life. But now stupid wax for brains Candleclaws push out Knicknack and family. Shiny things all left behind!\n\nHere, goblin friend helped made list of all my treasures inside Darkflame Cleft. You go take back!", objectives = "Retrieve Knicknack's treasures from Darkflame Cleft.", progress = "Treasures all very important. Very valuable. You no take for you! Bring back to me!", completion = "You did it! You did it! My treasures! Take that, stupid Candleclaws." }
WordHunterWoW_QuestEN[83155] = { title = "Tired of Tripping", description = "All that's between us and the juiciest excavation site I've ever seen is a couple of moles and a leggy deer. Sorry, getting ahead of myself.\n\nSee these shredders? State of the art in the field of maiming and killing. And they keep getting stuck in holes!\n\nListen, I'm as ecologically conscientious as the next goblin, but these moles have got to go. I'm gonna need you to give these hardheads a hard time. And if you see any of my crew, help 'em out, wontcha?", objectives = "\"Remove\" 15 Hardhead moles.", progress = "You deal with 'em yet? I'm not hauling another shredder out of the mud.", completion = "You sure sent 'em scurrying! There's only one teensy thing left between us and all those beautiful resources." }
WordHunterWoW_QuestEN[83159] = { title = "A Little Off the Top", description = "Ever seen a deepstrider before? This one sure ain't happy to see us. Made quick work of the shredders that made it past the moles. Real shame, those pilots are gonna have to work overtime to pay off the damages.\n\nNow if someone were to take care of it and bring back something as proof, well, I'm sure there'd be a nice payday.", objectives = "Slay Alhainr and collect its skull.", progress = "What did you do?!", completion = "This is bad, real bad! You'd think killin' something would make it less dangerous. We're getting stomped!" }
WordHunterWoW_QuestEN[83160] = { title = "Cinderbrew Reserve", description = "Trade may have been restricted, but I'll calcify before I let my Cinderbrew Reserve fall into the hands of these stripped screws or go up when some elemental looks at it funny.\n\nThe inspectors are watching me, stranger, so I can't go fetch it myself, but they won't be paying any special attention to you.\n\nI left it behind the desk in my old office, down below.\n\nJust don't get too close to an enforcer or they'll confiscate any cinderbrew you're carrying and I'll be left with nothing to drink.", objectives = "Bring the Cinderbrew Reserve to Cogwin at the Hallowfall Gate.", progress = "Do you have it?", completion = "Ah, now this is a brew worth waiting for. Thank you, <name>." }
WordHunterWoW_QuestEN[83162] = { title = "Put it Back, Put it Back!", description = "It's going to ruin everything! Who wants to visit a resort with a thirty-foot tall ghost-deer? Ok, no need to panic. It's probably just a little miffed you took its skull.\n\nFirst, you gotta get rid of some of these slimes. Then, get that skull out of here. The farther the better.\n\nOh man, they're gonna get ectoplasm in the hot pools!", objectives = "Stomp slimes and take Alhainr's Skull away from town.", progress = "Hurry up, before this whole place is wrecked!", completion = "Whew, that was close. This whole thing has really taught me to value the beauty of nature.\n\n<The goblin breaks into laughter.>\n\nReally had you going there, huh? Still, think I'll leave Abyssal Excavation alone for awhile." }
WordHunterWoW_QuestEN[83163] = { title = "Split Venture", description = "We're headed to my home turf next, Venturewood. It's next to the Heaps.\n\nThe Venture Company is mostly on board for Gallywix. That means a lot of the top brass are as dirty as him. Watch your step.\n\nBut there are some good folks there too. Like Pamsy and her crew. The little guy at Venture gets it rough. Everyone thinks of Venture Co. as just the baddies, so no one looks after them. But I gotta try right?\n\nHop in the hot rod, I'll show you what I mean.", objectives = "Ride the hot rod to the Venturewood and assist friendly Venture Co. goblins.", progress = "Seems like there's no respect for the little guys.", completion = "You did good for those goblins. Nikki brings the chaos--and not in the fun way." }
WordHunterWoW_QuestEN[83164] = { title = "City of Threads: Splice the Splicer", description = "\"Ascension\" is no true evolution. It is defilement. It is doom. And Ansurek further etches that doom in stone with each passing day.\n\nIf we bring down the Transformatory, then we can potentially rid Azj-Kahet of these abominations for good.\n\nIzo the Grand Splicer is Ansurek's chosen overseer of the Ascension process. Cut that wretch's head from her body, and perhaps these mutations will cease.", objectives = "Enter the City of Threads and defeat Izo the Grand Splicer.", progress = "Have you dealt with the Transformatory, <name>?", completion = "You've dealt a blow that Ansurek will never recover from, <name>.\n\nTake this and be well." }
WordHunterWoW_QuestEN[83165] = { title = "Badly Behaved Bot", description = "Go ahead, laugh. I would be as well if I didn't have such pressing business. My bot's foot clipped a nearby rock, spilled me out and then righted herself. Without me in the cockpit! \n\nI'm grounded while she floats there quite cheerfully. Can you believe it? \n\nListen, if you are heading up to Shadowvein Point, will you let Kagfritha know that I'll be late for my shift? I need to wait for this hunk of metal to run out of fuel and dip low enough for me to get back in the driver's seat.", objectives = "Speak with Kagfritha in Shadowvein Point.", completion = "Sinruna got tossed again, did she? I keep telling her she's flying too low. Maybe this'll knock some sense into her." }
WordHunterWoW_QuestEN[83166] = { title = "Ara-Kara, the City of Echoes: Harvest's End", description = "You've seen it yourself, haven't you? The \"Black Blood,\" as we call it.\n\nWe will not stand idle any longer. Not while Ansurek mutilates, drills, and exsanguinates our precious land for the last, fetid dribbles of the old gods' death rattle. \n\nSeek out the old city beneath us--Ara-Kara, The City of Echoes. You will receive a handsome bounty should you slay the crony in charge of the excavation. Her people call her Ki'katal, the Harvester.", objectives = "Enter the Ara-Kara, The City of Echoes and defeat Ki'katal the Harvester.", progress = "Have you been to Ara-Kara yet?", completion = "Ki'katal is dead? Excellent.\n\nYou have our thanks, <name>. In both praise, and material value." }
WordHunterWoW_QuestEN[83167] = { title = "Eyes from Above", description = "That was rough, with Nikki. And worse, those Darkfuse spy-copters saw everything. Feels like we can't get away from all the spies, don't it?\n\nThe last thing Venture needs is Gallywix thinking these workers ain't loyal 'cause they got caught on footage during one of Nikki's tantrums. We don't want a repeat of what happened to my last crew. \n\nGo take the footage from the spy-copters. They usually lurk around the workshops, or follow Venture workers around.", objectives = "Kill 8 Spy-Copters to steal their footage.", progress = "There is nothing better than breaking bad machines for a good cause.", completion = "The less dirt on us Gallywix has, the better." }
WordHunterWoW_QuestEN[83168] = { title = "A Trail of Black Blood", description = "While you have been getting familiar with the state of Undermine, I have been tracking our prey. The presence of Black Blood is everywhere, hidden behind noisy distractions.\n\nBut this city cannot fool me. I discovered a Black Blood shipment at a place called Hovel Hill, but there were machines guarding it. We should go together.", objectives = "Investigate Hovel Hill for Black Blood shipments.", progress = "Tracking the shipments should show us who's using 'em. Check out any labels or letters layin' around!\n\nI think I stunned all of the defenses, they'll leave us be.", completion = "Baron Revilgaz is shipping Black Blood around the city? And he's paranoid about Ethereals?!\n\nI got questions, and he's got answers." }
WordHunterWoW_QuestEN[83169] = { title = "Long Way from Booty Bay", description = "There is no doubt about it. These shipments have Blackwater Cartel written all over them... literally. The Black Blood comes in here and then Blackwater takes it somewhere in the city by couriers.\n\nSo if we want to find out where, we go right to the top--Baron Revilgaz. Grimla mentioned Revilgaz has a temporary set up nearby, here in Hovel Hill. Let's go pay him a visit.\n\nThe ethereal thing will have to wait.", objectives = "Locate Baron Revilgaz at Hovel Hill.", progress = "I have a bad feeling about all this, but let's talk to Revilgaz.", completion = "I am sure we can come to an understanding." }
WordHunterWoW_QuestEN[83170] = { title = "Not Again!", description = "The Darkfuse are moving into Hovel Hill. It's the same thing they did at Blackwater Marina. Once they move in, they start pushing the locals around. Sometimes they just make 'em go away. It ain't right. I want to fight back, but my hands are tied.\n\nIf an outsider showed up and started making trouble, that'd be a different story.", objectives = "Make trouble with the Darkfuse in Hovel Hill for Revilgaz.", progress = "Fairness is a loose concept in Undermine, but the Darkfuse push it too far.", completion = "If I had a few more like you I wouldn't have lost my... the marina." }
WordHunterWoW_QuestEN[83171] = { title = "Eye Sores for Sore Eyes", description = "They call them recruitment posters, but that ain't all they're for. They're there to remind everyone the Darkfuse are in charge and can do whatever they want. If me or one of the locals rip 'em down, it goes bad for us. \n\nBut the Darkfuse hate you anyway. \n\nIf you torched all the posters, I would owe you one.", objectives = "Burn 8 Darkfuse Recruitment Posters on and around Revilgaz's house.", progress = "I'm sick of seeing those recruitment posters. Burn them.", completion = "It may not keep Darkfuse out, but at least Hovel Hill is a little nicer without that Darkfuse garbage on the walls. \n\nLike I said, I owe ya one." }
WordHunterWoW_QuestEN[83172] = { title = "Black Blood Baton Pass", description = "Blackwater is just one step on the journey, and they like to keep this stuff moving. Revilgaz has his people take it from the station, hide it for a bit, then deliver it to the drop sites. The drop sites change, but the current one is a depot in the Heaps.\n\nWe're gonna check it out and find out where the Black Blood goes from there.\n \nHe says it's guarded, so look for us out near the edge.", objectives = "Meet with Renzik and Gazlowe at the next Black Blood depot in the Heaps.", completion = "That's a lot of guards. We're on to something." }
WordHunterWoW_QuestEN[83173] = { title = "Clearing Out the Depot", description = "The Heaps are crawling with guards. We've got an opportunity to disrupt the Black Blood operation in Undermine and we should take it.\n\nWe can't stop all the Black Blood from getting around the city, but we can clear out some guards and smash some shipments. Mess them up enough to disrupt things. Every little bit helps.", objectives = "Clear the depot area in the Heaps.", progress = "Every guards or shipment lost costs them time and money. And Gallywix hates losing both.", completion = "That should slow the Black Blood business. Hopefully anyone expecting a shipment will have a real bad day." }
WordHunterWoW_QuestEN[83174] = { title = "Our Good Pal", description = "Our old pal Zirdo's back. It looks like he's been promoted to Overseer of the Heaps, keeping track of the Black Blood shipments.\n\nWe owe him some payback for sellin' us out in Gutterville. He got a lot of good goblins killed to get on Gallywix's good side. Give the little snitch what he deserves.", objectives = "Kill Zirdo.", completion = "I ain't forgot what he did to Pamsy's crew in Gutterville... This was for them too." }
WordHunterWoW_QuestEN[83175] = { title = "Another Piece of the Puzzle", description = "<The ledger has longwinded ramblings about Zirdo's achievements, but also contains various deliveries of Black Blood across Undermine. Multiple entries in the ledger stick out as odd:\n\n- One thousand units for Secret Project, Deliver to Secret Project Site.\n- Twenty units for Developmental Ammunition, Deliver via Courier.\n\nTransfers approved by Noggenfogger of Steamwheedle.>", objectives = "Discuss the contents of Zirdo's Ledger with Gazlowe in the Heaps.", progress = "Noggenfogger knows better than to get mixed up with Gallywix.", completion = "This is all too much." }
WordHunterWoW_QuestEN[83176] = { title = "Just a Hunch", description = "It's time to sort out what to do next. This Noggenfogger business has Gazlowe on edge and we gotta move quickly to find out what's going on. \n\nSomething's got me on edge too. We should get outta the Heaps fast. But let's make sure Gazlowe's on board.", objectives = "Check in with Renzik about Gazlowe, and then meet Gazlowe outside of the Heaps.", completion = "Grimla says Orweyna and Alleria haven't shown up." }
WordHunterWoW_QuestEN[83177] = { title = "Socialized Medicine", description = "It has come to my attention that the most downtrodden residents of the Burrows have fallen prey to some sort of malady.\n\nTake this potion and dose the sick. This will strengthen the citizens and curtail further outbreak.", objectives = "Dose Downtrodden Residents with Nizrek's potion.", progress = "Have you aided the residents of the Burrows?", completion = "I will not allow their suffering." }
WordHunterWoW_QuestEN[83178] = { title = "Rules and Consequences", description = "I fear I have grown too brazen in my offerings of succor as of late. I seem to have attracted some untoward eyes.\n\nBe on guard. A veiled threat looms.", objectives = "Defeat the Assassin.", progress = "Have you handled the interloper?", completion = "Thank you for your aid. I am a great mind, but my acuity for combat is less impressive.\n\nStill, if Ansurek's assassins have found me...\n\nNo. I cannot stop now. I have too much yet to do." }
WordHunterWoW_QuestEN[83181] = { title = "Best Friends, Same Ends", description = "I saw the shipwright leave the cave and head down to the beach. She was accompanied by a formidable looking nerubian.\n\nThe shipwright is the mastermind behind this entire operation. She knows precisely how the lumber is to be cut and what lumber is needed for their airships.\n\nThe nerubians know this and likely assigned one of their best to protect her.\n\nIf we can eliminate the shipwright, we can bring all of their carefully laid plans to ruin.", objectives = "Eliminate Shipwright Isaebela and Shadowspinner Azarak at Silkwood Grotto.", progress = "Is it done <name>?", completion = "With the nerubian leader destroyed, their remaining forces will be in disarray.\n\nWithout the shipwright's knowledge and leadership, their entire operation will be crippled. \n\nLet us hope it also drives a wedge between these hopefully former friends." }
WordHunterWoW_QuestEN[83182] = { title = "A Bloody Inheritance", description = "When the kobyss killed my parents, they stole some of their most cherished things. \n\nNot me, obviously. Cherished items. \n\nWhile we are murdering kobyss, let's find them.", objectives = "Retrieve Alyza's parents' items in the Hungering Pool in Hallowfall.", progress = "Stupid kobyss. I hate them.", completion = "Well done. Far more useful than those other adults who told me not to do this.\n\n\"But Alyza, the kobyss are dangerous. You'll die.\" Stupid adults, thinking they know best.\n\nAre you ready to kill the big one? I'm ready to kill the big one." }
WordHunterWoW_QuestEN[83194] = { title = "Under Fire", description = "I'm only standing here because of Renzik. He didn't even think about it--he just...", objectives = "Be there for Monte Gazlowe.", progress = "We're not finished here.", completion = "<Gazlowe wears an expression you've never seen before. His face is etched with anger, yet he speaks with a deadly calm.>\n\nThere's no more denying it--it's Gallywix, or it's us. We can't put up with him, not for a day longer. He needs to be stopped. No more compromises, no more patience." }
WordHunterWoW_QuestEN[83195] = { title = "Rally the People", description = "No one's been stepped on harder by Gallywix than the Bilgewater Cartel. Plenty already want to rise up, but that ain't enough. We gotta show them what Gallywix has done and convince them that now is the time.\n\nLet's start with a headline. C'mon, pitch me. A big shot like you carries our message better than anyone else.", objectives = "Pick a headline with Dirk Greasedealer and then spread the word of revolution in Tailgate Park.", progress = "Now is the time to rise up. Tell 'em, <name>.", completion = "There's change in the air. I can feel it." }
WordHunterWoW_QuestEN[83196] = { title = "Disperse!", description = "Gallywix can't hide the truth, but he can beat us down until folks have no choice but to accept it. We ain't lettin' that happen again.\n\nYou see someone hurting a Bilgewater goblin, return the favor.", objectives = "Kill 20 Darkfuse at Tailgate Park.", progress = "The people have to know the streets are safe. It's on us to make them so.", completion = "The time for talking this out is long past. If they're with Gallywix, that's on them." }
WordHunterWoW_QuestEN[83197] = { title = "Who Owns the Streets?", description = "Her! Nikki the Fixer, Venture Company's top enforcer. Renzik's blood is on her hands.\n\nI can't worry if she's got another bullet. We gotta go after her. You with me, {name}?", objectives = "Confront Renzik's killer, Nikki the Fixer.", completion = "You made it just in time to join the boarding party." }
WordHunterWoW_QuestEN[83198] = { title = "Backyard Navy", description = "Gallywix and his crew have been meddling in our business for too long. Look at what they're doing to my marina! So comfortable with their holdings that they're doing donuts on jetskis!\n\nIt's time we introduce them to a little high seas firepower.\n\nTake this cannon and blow those Darkfuse vessels skimming our waters sky-high. After that, do me a favor and check up on the big guy, won't ya?", objectives = "Destroy the Darkfuse Joyriders in the Blackwater Marina.", progress = "Did my Captain send you? He knew I'd need help...", completion = "Hrrk. The roar of cannonfire and the scent of black powder. You'd make a fine cannoneer." }
WordHunterWoW_QuestEN[83199] = { title = "Been Savin' This One", description = "Listen {name}, Sprinkle's been cooking something for a long time that I'm finally ready to cash in. A little alchemist's secret ingredient. Citrus! Delivers twice the kick of Noggenfogger's Restorative Elixirs at half the speed. Strengthens your bones, grows your muscles, does your taxes. The whole nine yards!\n\nProblem is, I've got nothing of the sort on hand. These resort types may have what you need. We've been saving this recipe for a heavy hitter. Make sure Seahorn's alright before cooking it up, yeah?", objectives = "Collect Limes from the Resort Staff at the Blackwater Marina.", progress = "Ngh. Did they get me with that Black Blood?", completion = "Limes? What's all this then? We're at war with far worse than scurvy!" }
WordHunterWoW_QuestEN[83200] = { title = "A Vast, Ye Swabs", description = "Urgh. I've been locked up for so long. In my anger, I got reckless.\n\nWhatever Noggenfogger gave ya, I promise not to squander. Get me back in the fight and we'll bring the full swell of Blackwater's might down on these invaders.", objectives = "Brew the Noggenfogger Deluxe with Lime and feed it to Fleet Master Seahorn.", completion = "I'm feeling brand new, thanks to you.\n\nThey've transformed our marina into an overpriced resort in the front with a Black Blood smuggling operation in the back. \n\nLet's get even." }
WordHunterWoW_QuestEN[83201] = { title = "Expedited Delivery", description = "Blackwater can take the marina from here. But the people aren't safe with Black Blood that's already out there.\n\nThose flying transports must be taking the Black Blood somewhere under Venture Co. control. Commandeer one, and you might find Grimla. She was headed in that direction when we split up, shouting that a friend of hers was on the way.", objectives = "Hitch a ride on a Malfunctioning Cratemover.", completion = "Just the two people I wanted to see. We're up to our eyes in Black Blood over here." }
WordHunterWoW_QuestEN[83202] = { title = "Punching Up", description = "The time for talking out our differences is over. I'm done second-guessing who is still standing with Gallywix.\n\nSome of Nikki's people are keeping these new weapons in production. So, we take them out. It makes cleaning up Venture Co. after all this is done way simpler too. \n\nJust be careful. Nikki won't stick her neck out for her lieutenants, but she'll take the chance to rig a fight against you.", objectives = "Defeat the three Venture Co. loyalist lieutenants.", completion = "Had to be done. We're not finished yet." }
WordHunterWoW_QuestEN[83203] = { title = "Weapons Hot", description = "The destructive impulses of those who harvest Azeroth for their own profit never cease to horrify me. But these weapons are like nothing that has come before.\n\nAll containers of Black Blood must be overturned and destroyed. Weapons fueled by it crushed and dismantled. Those who wield it against others, put down. The people of this city, and this world, won't be safe until we do.", objectives = "Destroy Black Blood crates and weapons in the Heaps.", completion = "You've done well. But now, we must strike at the heart of where their weapons are assembled." }
WordHunterWoW_QuestEN[83204] = { title = "The Thingamajig", description = "Nikki's tech is powered by Black Blood. I know that because I worked on half of it. That also means I have an idea on how we might knock her out of the sky for long enough to take her out. \n\nNo time for pre-production. We gotta build.\n\nRemember our flashy little hoverboard adventure? Ice is nice, eh? I'm thinkin' of a similar principle--the trash heap oughta have all the salvage we'll need to build this hypothetical thingamajig.", objectives = "Recover parts for Pamsy in the Heaps.", progress = "You got time to yap, then you've got time to smash!", completion = "There's only one engineer I know who'll have the smarts to build what we need in time to take down Nikki..." }
WordHunterWoW_QuestEN[83205] = { title = "Production Halted", description = "<Orweyna rubs her palms with dirt, then cracks her knuckles.>\n\nNow, we teach those who toy with Black Blood nature's wrath. I am eager to call upon the roots twisting through Azeroth.\n\nJoin me. Unleash nature's fury as we did before. Let us destroy their prized stockpiles of Black Blood.", objectives = "Destroy the Black Blood stockpiles in the Heaps.", progress = "I would not have guessed Orweyna was that much of a natural at dodging rockets.", completion = "Of course the spill became a giant monster. Well, at least you dealt with it. The less Black Blood they've got to fuel their weapons with, the better." }
WordHunterWoW_QuestEN[83206] = { title = "We Own the Streets", description = "The trade princes ain't exactly been fair to the goblins here, so this can't be just another cartel war. The crowd needs to know they ain't fighting for Bilgewater or Steamwheedle. \n\nThey're fightin' for Undermine. \n\nWe need someone who ain't a cartel big shot to help rile 'em up and keep 'em safe. Do whatever it takes to get them to the Gallagio and show these goblins this is their city.", objectives = "Rally the people of Undermine against Gallywix.", completion = "Gallywix doesn't own these streets. We do. After this, he'll never forget it." }
WordHunterWoW_QuestEN[83207] = { title = "My Top Gal", description = "We've got Gallywix backed against the wall. Seeing Undermine and its people he's kept under his thumb finally rising up.\n\nHe thinks this \"Fixer\" of his will keep him safe. Let's show Gallywix, Nikki, and everyone else that things are different this time.\n\n<Gazlowe looks over the thingamajig he's just finished jury-rigging.>\n\nWatch this.", objectives = "Defeat Nikki the Fixer.", completion = "Take it all in. We won. Gallywix can squirm away for now, but we took our city from him. \n\nToday, Undermine belongs to us." }
WordHunterWoW_QuestEN[83229] = { title = "Special Assignment: When the Deeps Stir", description = "", objectives = "" }
WordHunterWoW_QuestEN[83240] = { title = "The Theater Troupe", description = "Since you're an honorary member of the theater troupe, {name}, what do you think about playing a part in our plays?\n\nNo big parts--I don't want to upset the rest of the troupe by taking away their limelight. You know how they are.\n\nAre you available, say, once a week?", objectives = "Participate in the Theater Troupe event.", progress = "The show must go on! And on. And on. We've been renewed for a permanent showing. For the earthen that means... well, it means we're all employed for a long time.", completion = "Marbleous! You're the perfect addition to our theater troupe, <name>.\n\nPlease come and help us again in our next showing!" }
WordHunterWoW_QuestEN[83247] = { title = "Suspicious Minds", description = "For many years, the only non-Arathi we ever saw in Hallowfall were trying to kill us. Nerubians, shadow creatures, beasts. So, forgive me if I view your sudden arrival with suspicion.\n\nHowever, my better half would urge me to be more welcoming... and I want to try to be better. For her.\n\nSome of the salamanthers in Rumshackle have been bothering us. Kill them and bring me proof.", objectives = "Find 9 Salamanther Hearts in Rumshackle.", progress = "Others may be satisfied with just your word that you have done what I'd ask. \n\nI am not.", completion = "You have helped.\n\nPerhaps she is right, and perhaps I should follow the example set by Dunelle.\n\nThank you." }
WordHunterWoW_QuestEN[83271] = { title = "There's Always Another Secret", description = "After me da' did whatever he did, the titans' machines are back online--even the ones here in Dornogal.\n\nDagran was havin' enough fun with Brinthe askin' her a thousand questions, but now he's helpin' her sort through the Archive.\n\nAn' now he wants your help. He was too excited to tell me why, but he wanted ye to meet him in the Archive.", objectives = "Check in on Dagran Thaurissan II and Brinthe in the Archive in Dornogal.", completion = "Fascinating. This is clearly a chamber meant for a Keeper. But for what? \n\nWe need to investigate." }
WordHunterWoW_QuestEN[83274] = { title = "An Original Path Through Time", description = "Old warriors keep spinning tales about how things were so much tougher around Azeroth back in their day.\n\nI bet they would say you're not tough enough to last 10 minutes in their world.\n\nThink you're tough enough to find out? How 'bout you show me.", objectives = "Complete 5 Timewalking dungeons.", progress = "You're not givin' up, are ya?", completion = "You did it, <name>! Way to show those old warriors that Azeroth is still in good hands!" }
WordHunterWoW_QuestEN[83275] = { title = "Gear Enchanting", description = "Hello, outlander!\n\nI've heard of your exploits since your dramatic arrival on our shores. We earthen welcome your aid.\n\nI can teach you how to enchant your gear with resources from my land. To defeat our enemies, every bit of power helps.", objectives = "Complete the item enchantment tutorial by enchanting any ring using the enchantment given from Ellerdin, Enchant Ring - Glimmering Haste.", progress = "The enchantment and ring I gave you are fitting for each other.", completion = "May you be undefeatable as the earth itself. On your way now, outlander!" }
WordHunterWoW_QuestEN[83276] = { title = "Saving Private Spindle", description = "One of my weave-rats has failed to check in for an unusually long time. I sent Spindle to retrieve information we could use against one of Ansurek's favored wretches, but she has not returned from her assignment.\n\nMeesk the Venomtongue is a wretch and a sycophant, but he is dangerous all the same. While I have much trust in my dear Spindle's abilities, I fear what a malefactor such as Meesk would do to one of my little ones should he find them.\n\nFind Spindle. Make sure she is well.", objectives = "Find Spindle in the High Hollows.", progress = "<All of Spindle's eyes widen with both relief and embarrassment at the sight of you.>", completion = "<The little spider looks at you with many pleading eyes. You get the sense that she does not want you to speak of this to anyone.>" }
WordHunterWoW_QuestEN[83277] = { title = "Personal Pilfering", description = "<The little spider looks around the room, each of her eyes narrowing.\n\nYou recall The Weaver telling you to retrieve evidence to blackmail Meesk.\n\nBut it appears as though ransacking Meesk's storage is now personal for Spindle.>", objectives = "Find 3 pieces of Incriminating Evidence in Meesk's Retreat.", progress = "Well, my morsel? Did you find anything of note?", completion = "I see you've returned my Spindle to me. And some rather interesting bits of evidence, to boot.\n\nIt seems that varlet Meesk has leveraged a willingness to slander his betters in order to gain the favor of Ansurek and her ilk. Not only is his power growing by the day, but it does so at the expense of Queen Neferess' legacy.\n\nWell, that simply will not stand. Return to me soon, my little morsel. I need some time to concoct our next course of action." }
WordHunterWoW_QuestEN[83278] = { title = "Hillhelm Family: A Lost Shoe", description = "<A shoe in the style worn by members of the Hillhelm family.  Maybe Aliya Hillhelm can shed some light on it.>", objectives = "Deliver The Lost Shoe to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", completion = "Addysen and I used to tiptoe barefoot through those caves. With light steps, the slumbering fungus would not awake. It wasn't foolproof, and we did lose a lot of shoes escaping from angry Lashrooms.  \n\nThis shoe, however, seems to have once belonged to Gerta?" }
WordHunterWoW_QuestEN[83279] = { title = "Prove One's Mettle", description = "Yes, you helped us out with these pests, but it is not enough. I need more.\n\nOne of the areas near our town has been overrun by shadow. If you are truly not being controlled by your... strange background, you would have no problem destroying the source of this danger, would you?", objectives = "Defeat the Coalesced Iniquity in Rumshackle.", completion = "I have been following the Church of the Sacred Flame since the moment I was born. Doctrine is hard to set aside.\n\nBut I see now that you are here to help. And as long as you use your powers for us, I will reach out a hand of friendship--regardless of where that power came from." }
WordHunterWoW_QuestEN[83282] = { title = "Hillhelm Family: A Clutch of Eggs", description = "<A clutch of chicken eggs, they must have come from a nearby farm.  Maybe Aliya Hillhelm can shed some light on it.>", objectives = "Deliver The Clutch of Eggs to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", completion = "You stumbled upon this in the nearby caves? We have a few adventurous chickens who likely wandered in there.\n\nTracking down all the runaways can be a full-time endeavor." }
WordHunterWoW_QuestEN[83283] = { title = "For Morale", description = "Please excuse my husband's rudeness. When we signed up for our expedition, we expected to be away from our families for a few years at worst. Instead, we settled here as we guard against--well, against the end, against Renilash. Who knows when our watch will end?\n\nI've been stockpiling a cache of wine from our church vineyards to share with everyone when tensions got high. My hiding place, Rumshackle, has been overrun by creatures. Can you get the wine for me?", objectives = "Retrieve 6 barrels of Imperial Brut from Rumshackle.", progress = "Imagine twenty Arathi huddling under the safety of a single light for ten years. Imagine they're waiting for a chance to let their hair down with a good drink with their comrades.\n\nNow imagine how they'll feel once they hear the wine is gone.\n\n...please hurry.", completion = "Oh, thank the Flame.\n\nYou've prevented a small riot from forming. Bless you, bless you, bless you!" }
WordHunterWoW_QuestEN[83285] = { title = "The Ancient Scroll", description = "A haze seems to obscure the details of the scroll at first. As you concentrate on making out the scroll's features, the haze briefly dissipates revealing a pristine scroll made of the finest vellum, with a seal that looks so fresh the wax doesn't even seem set yet. In a blink, the scroll feels dangerously brittle, and the seal so delicate it could crack at any moment. As the haze begins to form again, you see the scroll shimmer through all possible points between these two extremes.", objectives = "Scrolls are fascinating items. They travel far and wide across the lands, yet this one seems to also travel through time.\n\nThe fact that you found this scroll where you did is both an omen and a blessing." }
WordHunterWoW_QuestEN[83286] = { title = "What's Hidden Beneath Dornogal", description = "Strange. The mechanism and console here is receiving power, but I cannot initialize the reboot sequence.\n\nDagran's query may have to wait.\n\nI have been able to ascertain the facility's designation: the \"Vault of Memory.\" This leads me to believe that my original theory was correct. It is connected to the Archive in Dornogal.\n\nPerhaps, since both of you are familiar with this type of titan installation, you may have a better chance bringing it fully online.", objectives = "Restart the central mainframe in the Vault of Memory in Dornogal.", progress = "Take your time. It has been here for millennia. I am sure it is not going anywhere.", completion = "I now have access to the mainframe here in the Vault of Memory. \n\nThere is a lot here but... it is fragmented. It will take time to recompile it.\n\nAnd some data, I'm afraid, may be damaged and need repair." }
WordHunterWoW_QuestEN[83306] = { title = "Where the Wild Things Camp", description = "Some of my people found a few haranir setting up one of their camps to the southwest. They were missing some vital supplies, so my people offered to help out. However, I worry about how they're all getting along over there.\n\nCould you check in on them? Make sure we're being good hosts to the haranir... and that nobody has inadvertently offended anyone. Please.", objectives = "Meet Orweyna at Wildcamp Ul'ar.", completion = "You again. Curious." }
WordHunterWoW_QuestEN[83307] = { title = "<DNT> Golf", description = "", objectives = "" }
WordHunterWoW_QuestEN[83315] = { title = "Preparing for the Unknown", description = "This will be a long process. Longer, I fear, than Dagran can stay here in the Isles.\n\nBut perhaps... \n\nThere are many titan relics I can use as \"keys\" to unlocking information in the mainframe or to repair it. That may make the process go more quickly.\n\nOnly time will tell.\n\nYou have helped us enough, {name}. Go back to Moira and tell her what we have discovered.", objectives = "Return to Moira Thaurissan in Dornogal.", completion = "Well, I know where to find Dagran if I'm missin' him.\n\nIt's good tae see him so happy an' in his element. He's done me proud.\n\nThank ye for helpin' him along the way." }
WordHunterWoW_QuestEN[83321] = { title = "Strange Bats", description = "Hey. Her ladyship has a lead on some really strange bat that was flying around the Wormlands. \n\nThe spies reported it behaving more like a person than a bat. We think we might have a druid out there, but it ain't revealin' itself to the nerubians on purpose.\n\nYou have one of those faces that make people hesitate before punching. Head out there and take a look.", objectives = "Investigate a possible druid sighting.", completion = "You! You are just what I need." }
WordHunterWoW_QuestEN[83322] = { title = "The Dawnbreaker: The Christening", description = "The flagship of the Arathi armada is the Dawnbreaker. She is a marvel of Arathi engineering and faith in the Sacred Flame. Her presence in the Hallowfall sky will help us push back the nerubians when next they dare launch another assault on our lands.\n\nAs someone who has helped us so much in the past, you are cordially invited to the christening ceremony of the Dawnbreaker. If you could make sure it goes off without a hitch, you will have my personal gratitude.", objectives = "Help the christening ceremony in the Dawnbreaker dungeon succeed.", progress = "The Dawnbreaker will cause problems for the nerubians once she is active. It is very important everything goes off without a hitch.", completion = "Well.\n\nThat went as well as could be expected for a ceremony in Hallowfall.\n\nThank you for being here." }
WordHunterWoW_QuestEN[83323] = { title = "<DNT> Gas Coupons", description = "", objectives = "" }
WordHunterWoW_QuestEN[83324] = { title = "A Silken Thread", description = "You looking for work or something? <Linny squints her eyes at you.> If you're just hanging around I've heard some whispers from the capital. An associate of the Weaver is looking into some business in the Silken Ward.\n\nThe new ward is supposed to be a fresh start for citizens of the capital but the Queen's Pale Weavelashers have been treating it like a military camp. This isn't sittin' well with the populace.\n\nMeet with a nerubian named Sum'latha outside the ward. She can fill you in on the details.", objectives = "Meet with Sum'latha at the Silken Ward.", completion = "You must be the help our \"mutual friend\" sent. Welcome to the Silken Ward." }
WordHunterWoW_QuestEN[83325] = { title = "Bountiful Beetles", description = "General Anub'azal has great plans in motion for the swarmery, Rak-Ush. He intends to return it to working order, to support his war campaign.\n\nHowever... I have my reservations about the two he left in charge. \n\nKish'nal seems to have a good head on his shoulders, but Vix'aron? Volatile is an understatement. They may require some... prodding.\n\nSeek out Kish'nal at Rak-Ush and follow up on Anub'azal's orders.", objectives = "Speak with Kish'nal in Rak-Ush.", completion = "Ah, so the general has sent out an observer?" }
WordHunterWoW_QuestEN[83326] = { title = "The Final Candle", description = "You are good candle-taker. \n\nWe have one last job for you, your waxiness! One more job! Then no more sticky business. \n\nBIG candle in basement. Stone-ones use it to keep rats away from their honey juice. We no rats! We kobo--ooolds. \n\n<There's an awkward pause.>\n\nNothing rhymes with kobolds, hm. \n\nGet us big candle!", objectives = "Steal the final candle for the suspicious vent in the Gundargaz Inn.", progress = "Candles! Candles! Candles!", completion = "Whoop! Whoop! The candle! The BIG one! \n\n... you smell smoke?" }
WordHunterWoW_QuestEN[83328] = { title = "The Analysis Interface", description = "This is the Analysis Interface. \n\nIn order to ensure our primary programming remained intact, these consoles were installed with a series of inquiries to assess the memory matrix of the newly awakened. \n\nAlthough Dawn will encourage you to answer in any way that you please--I... well, I hope you'll answer truthfully.\n\nProceed when ready.", objectives = "Complete the Analyzing Sequence in the Analysis Interface.", completion = "Who you were, who you are and who do you want to be? \n\nAll questions every <race> from now on will be allowed to ask.\n\nOur fate and our purpose is ours to choose." }
WordHunterWoW_QuestEN[83329] = { title = "Level 50", description = "", objectives = "" }
WordHunterWoW_QuestEN[83330] = { title = "Level 60", description = "", objectives = "" }
WordHunterWoW_QuestEN[83331] = { title = "Preserve and Pretend", description = "Chive dig for history. You help find? \n\nGot history detector from goblin. Said it finds history underground! You use. Chive dig.", objectives = "Help find places to dig for \"historical objects\" by using the goblin \"history detector\".", completion = "Many thanks, dig-finder. \n\nChive know these have no important history... but they will one day.\n \nChive will keep safe until then. Kobolds make new history. \n\nThen save and protect. Forever." }
WordHunterWoW_QuestEN[83333] = { title = "Gearing Up for Trouble", description = "Greetings friend,\n\nThe machine is once again in disrepair and requires restoration. \nI am in need of your expertise to successfully perform maintenance.\n\nA reward shall be provided for well-executed assistance.", objectives = "Complete 20 waves of the Awakening the Machine event.", progress = "Status report?", completion = "The machine continues in its duties once again.\n\nThank you again for your assistance." }
WordHunterWoW_QuestEN[83334] = { title = "The Wealth of an Empire", description = "", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude." }
WordHunterWoW_QuestEN[83335] = { title = "Wanted: The Boroughbreaker", description = "<This note is nailed into the post with a small chitinous plate.>\n\nFor crimes impeding the Edicts of Dornogal, the Council has deemed a reward be yielded to any who slays the chitinous beast known as Stik'kar.\n\nA sample of Stik'kar's armor is attached. If you are unable to damage it, you are urged to carry on in your duties and leave this task for another.", objectives = "Slay Boroughbreaker Stik'kar in the Isle of Dorn.", completion = "The Council can bicker all they want. The true heroes are those that go out and make the world a safer place. Thank you hero." }
WordHunterWoW_QuestEN[83336] = { title = "The Earthwound", description = "<Etterca grumbles as you approach.>\n\nGround is shaking. 'Tis no good.\n\nTroubles are awakening the elements again. Stirs rot in them. Danger to us all. Bring them to heel and give its heart here.\n\nOnly then the earth can begin to heal. Only then can Etterca do her duties.", objectives = "Acquire the Broken Stoneheart from Roth the Earthwound in the Isle of Dorn.", progress = "<Etterca grumbles and stares at you blankly.>", completion = "Hmmph. Broken heart takes long time to mend. \n\nEtterca hears you, Roth. Earth will mend." }
WordHunterWoW_QuestEN[83337] = { title = "Stormscarred", description = "Take a look around this beautiful town. What do you see? Ranchers 'n' their mosswools. But where  is this rancher's flock? In the guts of a beast, they are. Stormscar they call 'im. \n\nStormscar, whose howl is as the thunder. Whose bite is lightning. Whose belly is full of my life's work. \n\nI came here to buy weapons and all we have is ranching equipment. You look strong. Would you put an end to Stormscar's reign in our pastures?", objectives = "Slay Stormscar in the pastures near Rambleshire in the Isle of Dorn.", progress = "Have you done it yet?", completion = "Thank you, adventurer. My role in this world is to be a rancher. Yours is to slay wolves. We all have our places." }
WordHunterWoW_QuestEN[83338] = { title = "The Mage Slayer", description = "I confess I have come here with reason. There is one entity that may be out there still that cannot be allowed its freedom.\n\nA prisoner from the Violet Hold that we begrudgingly know as the Mage Slayer. I had come to request aid from these people, but they are farmers and ranchers. I hope you are better equipped for a challenge.\n\nSeek out this fiend and put an end to its existence.", objectives = "Slay Mage Slayer Phytethil near Rambleshire in the Isle of Dorn.", completion = "Dalaran may be in ruins, but the Kirin Tor does not grant you release Mage Slayer!\n\nThank you for your assistance, <name>.\n\nAre you sure you defeated all of it?" }
WordHunterWoW_QuestEN[83339] = { title = "The Spirebreaker", description = "We are no strangers to nerubian attacks. The Kirin Tor is well equipped to handle such a threat. Dalaran...\n\nWas equipped. I cannot fend off all of this town's foes, but you might be able to. I spotted an ambush near the road on the way here. An all too familiar tactic of an all too familiar foe. Go spring the trap and slay the  monster that lurks below.", objectives = "Slay Anub'esska on the road near Rambleshire in the Isle of Dorn.", progress = "Are they safe now?", completion = "Thank goodness. With your aid, we may be able to make a difference... this time. \n\nThese people deserve safety." }
WordHunterWoW_QuestEN[83345] = { title = "A Call to Battle", description = "I have heard that your people wage massive battles against one another across huge fields and in crumbling ruins. \n\nSeems like a bit of a waste of time, fighting over flags when there's proper work to be done. However, the field of battle can test the mettle of a warrior. In that, there is value.\n\nBring me news of your victories! I am open to being impressed.", objectives = "Win 4 Battleground matches.", progress = "We Machine Speakers are no strangers to trial by fire. It is good for learning teamwork and testing out strategies.", completion = "You return with news of victories? Perhaps some losses?\n\nEvery loss is a lesson towards improvement. Celebrate your victories as well." }
WordHunterWoW_QuestEN[83347] = { title = "Emissary of War", description = "Are you up for a real challenge? Delve into the darkest places and soar to the highest heights while upping the challenge. \n\nBy pressing ourselves to the extreme we can truly test our skills.", objectives = "Complete 4 dungeons on Mythic difficulty.", progress = "By pressing ourselves to the extreme we can truly test our skills.", completion = "That was no easy task you completed. I am moderately impressed." }
WordHunterWoW_QuestEN[83357] = { title = "The Very Best", description = "The bond between us and our machines is much like the one others have with their pets. You must be in harmony with your companions in order to accomplish great things!\n\nShow me that you can work as a team with your pets. Defeat your enemies with their assistance!", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", progress = "You must be in harmony with your companions in order to accomplish great things!", completion = "You and your pets are a tough team to beat!" }
WordHunterWoW_QuestEN[83358] = { title = "The Arena Calls", description = "Have you proven your mettle in the arena? Win enough battles, and we might even find your tales worthy of storage in the Archives one day.", objectives = "Win 10 Arena Skirmish battles.", progress = "Do not let your guard down in the arena!", completion = "Good job! You are on the right track with your training." }
WordHunterWoW_QuestEN[83359] = { title = "A Shattered Path Through Time", description = "One of your people brought me a strange tale of the cataclysm that tore Azeroth apart. In your lands, this was felt most direly due to the machinations of the wicked creature Deathwing. \n\nTravel through space and time and engage with him and other threats.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", progress = "Only the titans should reshape the world.", completion = "Echoes of the Cataclysm were felt throughout Azeroth. It was a dire time indeed." }
WordHunterWoW_QuestEN[83360] = { title = "A Fel Path Through Time", description = "I have heard tales of an entire Legion of threats that lurks along the paths of space and time. \n\nDefeat them and bring me back news of their demise.", objectives = "Complete 5 Timewalking dungeons.", progress = "Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", completion = "Have you snuffed out the Burning Legion? They deserve nothing less, from what I've heard." }
WordHunterWoW_QuestEN[83362] = { title = "A Shrouded Path Through Time", description = "One of your people brought me tales of Pandaria! I would very much like to fly through those skies one day. \n\nWalk through mist and time and bring back news of your deeds.", objectives = "Complete 5 Timewalking dungeons.", progress = "I wonder what it is like to be covered in fur like a pandaren. I hear there are many floating places to visit in those lands. May they all stay afloat.", completion = "Ah, you return damp with mist-dew. I hear you bring news of your victories in Pandaria." }
WordHunterWoW_QuestEN[83363] = { title = "A Burning Path Through Time", description = "Your people have brought me tales of a Dark Portal wherein lie many enemies and challenges. I would like to hear more of these tales.\n\nTravel through time and space to this outlandish place, vanquish its foes, and bring me news of their demise.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", progress = "Some of my people may see the arrival of the outlanders as an invasion, but I am glad it was you who landed on our shoes, and not the Burning Legion.", completion = "You return in glory and bring me tales of the quenching the fires of the Burning Legion?" }
WordHunterWoW_QuestEN[83364] = { title = "A Savage Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to a past limed with hellfire to defeat those threats once more and bring those lessons forward.", objectives = "Complete 5 Timewalking dungeons.", completion = "You are returned and our reality has not unraveled itself, so I take it you were successful." }
WordHunterWoW_QuestEN[83365] = { title = "A Frozen Path Through Time", description = "Ever since your city fell out of the sky, I have learned more of this world's history and the challenges that heroes like yourself have faced. \n\nLearning from the past is how we ensure our future. Walk through time to the frozen past, defeat those threats once more, and bring those lessons forward.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", progress = "Much has happened in the greater world while we worked in this place. I hear you had a hand in quite a bit of those tales.", completion = "What lessons do you bring from your journeys through time?" }
WordHunterWoW_QuestEN[83366] = { title = "The World Awaits", description = "Perhaps we can turn your tragedy into a mutually beneficial experience for us both. There is much you can do to be of assistance to the earthen. \n\nLend a hand where you can.", objectives = "Complete 10 World Quests in Khaz Algar.", progress = "My people face a wide range of difficulties these days, as do yours. We can make the best of what's befallen us both.", completion = "News has come to me of your deeds among my people. Your name is spoken by earthen far and wide." }
WordHunterWoW_QuestEN[83417] = { title = "Out-laws", description = "We're a traditional goblin family, an' my sweetie's intended's from one too. Young people start work on a contract, an' buy each other out when they get hitched so they can get time off.\n\nI've got the cash for my sweetie to buy her intended's contract out, but it would be... embarrassin' if her intended didn't have the moolah for my perfect peach's contract, ya know?\n\nGo talk to that kid and make sure he's set for the big day. And if he's not? Fix it.", objectives = "Talk to Vrizek and make sure he has the Contract Fee.", progress = "Everything needs to be perfect for my girl's big day. Or else.", completion = "I figured something like that might happen. Good job." }
WordHunterWoW_QuestEN[83418] = { title = "The Perfect Coat", description = "My princess deserves only the very best Azeroth has to offer--and that goes double for her clothes. How else are people supposed'ta know how incredible I think she is?\n\nI got a guy who's hooked me up with an amazin' and rare pelt for my little girl to turn into a fabulous coat. Go meet the guy and bring back the goods. And you better not get anythin' on it.", objectives = "Acquire the fabulously feathered coat material.", progress = "Tick tock!", completion = "Hey, that looks swanky! My precious is gonna look amazin' in those feathers!" }
WordHunterWoW_QuestEN[83419] = { title = "The Perfect Guest List", description = "The perfect weddin' has the perfect guest list!\n\nBut I'm still waiting on some RSVPs. Papa said he'd make sure they showed up, so that means you gotta remind them they'd love to come to my weddin'. It's gonna be the biggest bash this town has ever seen! Why wouldn't they want to come? We're family! Mostly.\n\nAnyway, get everyone on this list to agree to come to my weddin'. Remind them Papa said \"or else.\"", objectives = "Get positive RSVPs from the remaining guests.", progress = "You talk to all my slacker relatives yet? I have to organize the tables.", completion = "Alright! I can finalize my table seating now." }
WordHunterWoW_QuestEN[83420] = { title = "Catering to Perfection", description = "My perfect day needs the perfect food! I've been looking at things on Gobstagram, and Chef Hardslice is my one and only choice for catering. Papa promised I'd have the best, and he's good to his word!\n\nI need you to make sure that everything on my menu makes it to the table for picture perfection. Everyone needs to see how fabulous my wedding is. \n\nAhh! I am so excited! I can't wait to see Chef Hardslice's creations on my table at my wedding!", objectives = "Speak with Chef Hardslice and obtain missing ingredients.", progress = "Isn't Chef Hardslice a genius?", completion = "My food is going to be the envy of everyone!" }
WordHunterWoW_QuestEN[83421] = { title = "The Perfect Wedding", description = "I hired some goons to crash the wedding. Only the best weddings get crashed, right?\n\nBut, I don't want to lose my deposit on this here venue. So, I need you to stop my crashers from getting too crashy, ya know?", objectives = "Stop the wedding crashers from doing too much damage to the venue.", progress = "Stop those goons from doing too much damage, or I'll take my deposit outta your hide!", completion = "Hey! I'll get my deposit back. Good job." }
WordHunterWoW_QuestEN[83432] = { title = "The Rookery", description = "My contacts around Dornogal have told me to keep this a secret, but I trust you mainly because I need someone to do the job.\n\nWe have a problem within the Rookery's walls--a skardyn outbreak.\n\nI need someone to clear the Rookery of skardyn, find the source of the outbreak, and drop the boulder on it.\n\nOnce you complete the mission, come back to me for your reward.\n\nAnd remember... this stays between us.", objectives = "Biergoth wants you to enter The Rookery and put an end to the skardyn threat.", progress = "Back so soon? Good news, I hope?", completion = "Well done. You are officially my favorite hero.\n\nAt least until tomorrow." }
WordHunterWoW_QuestEN[83436] = { title = "Cinderbrew Meadery", description = "Word has come from a contact of mine named Wenbrandt. You may have heard of him. He runs the Cinderbrew Meadery.\n\nHe says that goblins affiliated with an organization calling itself Venture Co. are trying to take over the meadery. We cannot have that. I need you to get into the meadery and remove that threat.\n\nCinderbrew is an earthen product and should be under earthen control. Wenbrandt will teach them this lesson--but until then, I will count on you to finish the job.", objectives = "Biergoth wants you to remove the Venture Co. from the Cinderbrew Meadery.", progress = "Any news are better than no news at all.\n\nDo not keep me waiting. Unlike the mountains, my patience is like that of a landslide.", completion = "Wenbrandt sent me the word. Well done. \n\nHere is your reward." }
WordHunterWoW_QuestEN[83442] = { title = "Tossed and Torqued", description = "All my notes. My plans!\n\n<Snap is shaking with anger.>\n\nI just know it was Mite Sparkcog who tossed my apartment. He's my work rival and probably wanted my newest invention for himself--the Smellersweller 5000!\n\nIt's an attachment for the grills we design. I'd just finished the schematic for our boss when I stepped out for some grub. By the time I got back...\n\nMaybe he didn't find it. Help me look first, then we can deal with Mite.", objectives = "Search Snap Vellumgrease's apartment for the schematic in Undermine.", progress = "The schematic is of a muffler-type part that sticks onto a grill. It's so amazin' that you can't miss it!", completion = "<Snap crumples up the taunting note.>\n\nOh, he is not gonna steal my promotion this time!" }
WordHunterWoW_QuestEN[83443] = { title = "Darkflame Cleft", description = "A new ally of ours, a kobold from the Ringing Deeps named Skitter, has contacted me.\n\nI need you to go to Darkflame Cleft and remove a certain threat--something that Skitter called The Darkness.\n\nHow can a kobold be afraid of the darkness when they spend most of their time underground? It makes no sense to me. But kobolds will be kobolds, and I will not busy myself with understanding.", objectives = "Biergoth wants you to venture into Darkflame Cleft and face The Darkness.", progress = "Let me know if you figure out what this darkness is all about.", completion = "So The Darkness is a kobold entity? And here I thought Skitter was over-exaggerating.\n\nHere is your reward." }
WordHunterWoW_QuestEN[83445] = { title = "Something Smells", description = "Ooh! That Mite makes me so mad! He even took credit for it. An' I was right. He's going to present the Smellersweller to our boss!\n\nIn fact, he's probably presenting it right now!\n\nThat gives me an idea though. We may not have the schematic, but Mite won't know how to operate it. If we can show the boss it's not Mite's design, maybe I'll still get credit!\n\nHow good are you at pressing buttons? Will you help me present the prototype?", objectives = "Speak with Snap Vellumgrease at Cheap Grillz in Hovel Hill.", progress = "We've got to hurry! Mite's had most of an hour to prepare.\n\nAll while I was on a break, that mook!", completion = "That no-good, brainless, fried worm of an engineer!\n\nHe'll pay for this!" }
WordHunterWoW_QuestEN[83446] = { title = "Cease and Desist", description = "Our presentation showed that we were the ones that could actually operate the device! If Sammy weren't so focused on the documentation bein' in Mite's hands... Anyone else could clearly see we had made the thing even if we didn't have the schematics!\n\nBut this ain't over. You saw how Mite overloaded the Smellersweller? We can do that too! Punch a bunch of buttons all at once and we can exploit his half-baked, all-stolen idea!\n\nWe go in, we mess up the prototype, an' we set production back months!", objectives = "Stop the Smellersweller 5000 production at Cheap Grillz in Hovel Hill.", progress = "Mite... might actually have a good point there.", completion = "Oh, uh. Hi, <name>. Thanks for tearing apart those busted prototypes for us. Here's your cut.\n\nAs it turns out, this was all a misunderstandin'. He broke in 'cause he thought I had stolen HIS idea.\n\nAn' actually he has had a good idea for the Smellersweller... Smellifier... whatever." }
WordHunterWoW_QuestEN[83457] = { title = "The Stonevault", description = "I have a job for you from High Speaker Brinthe herself.\n\nThe skardyn corruption is taking over the Stonevault. To contain the panic, High Speaker Brinthe has asked us for help. I told her she could trust us like we trust the bedrock under our feet.\n\nGo to The Stonevault and remove the skardyn corruption. Let me know when the job is done.", objectives = "Biergoth wants you to end the skardyn corruption within The Stonevault.", progress = "Any news I can report to High Speaker Brinthe?", completion = "You are indeed like a bedrock--solid and trustworthy.\n\nI will let High Speaker Brinthe know of your success." }
WordHunterWoW_QuestEN[83458] = { title = "Priory of the Sacred Flame", description = "Good to see you, {name}. I have a job just for you.\n\nSister Etna Blayze of the Arathi is convinced that something is wrong within the Sacred Flame Priory. She did not expand on the matter at hand.\n\nPlease head out to the Priory of the Sacred Flame and join the sister. A stomach pebble tells me she might be right and will need your help.", objectives = "Biergoth wants you to go to the Priory of the Sacred Flame and help Sister Etna Blayze.", progress = "I am not sure if you are still here or already back.", completion = "Sometimes a stomach pebble is all you need to listen to.\n\nHere, a reward for your time and effort." }
WordHunterWoW_QuestEN[83459] = { title = "The Dawnbreaker", description = "I have received word from General Steelstrike of the Arathi. She asked for you to attend a ceremony aboard The Dawnbreaker.\n\nBy attending, she means she needs an extra pair of eyes--maybe two or five. Have you ever secured a ceremony before? It feels like a puddle of sticky mud down in the Forgegrounds.\n\nI'm sorry, but General Steelstrike asked, and I replied with a simple \"yes.\" As the saying goes, not every hill is going to be exciting.", objectives = "Biergoth wants you to go to The Dawnbreaker and help General Steelstrike with securing the ceremony.", progress = "I know ceremonies are not your cup of cinderbrew. They are not mine either, but our job is important.", completion = "I received word that the ceremony was more of a mudslide than a sticky mud puddle.\n\nI am happy that you were there." }
WordHunterWoW_QuestEN[83465] = { title = "Ara-Kara, City of Echoes", description = "Tulumun, an agent of a new contact known as the Vizier, has approached us.\n\nI never expected a nerubian to come to us for help, but what they brought to our attention could threaten us all.\n\nI will need you to descend into Azj-Kahet and infiltrate Ara-Kara, the City of Echoes. If what Tulumun told me is true, we cannot let whatever they have woven down there escape.\n\nPut an end to their operation. Bring back evidence of what you find.", objectives = "Biergoth wants you to stop the operation taking place within Ara-Kara.", progress = "Move quickly. Their operation cannot be allowed to come to fruition.", completion = "Black blood? I am unsure what that is, but if a nerubian calls it vile, I will take their word for it.\n\nHere, take this for your trouble." }
WordHunterWoW_QuestEN[83469] = { title = "City of Threads", description = "Tulumun, our Nerubian ally, contacted us once again. He spoke of a place called the Transformatory where horrific experiments take place.\n\nI will need you to infiltrate the city and then rendezvous with the Vizier himself for the rest of the mission. \n\nEliminate the Vizier's enemies, end the threat, and return to me for your payment.", objectives = "Biergoth wants you to eliminate all threats within the City of Threads.", progress = "Make it quick. I do not wish for you to spend more time than you have to in a nerubian city.", completion = "I do not know if I trust these nerubians--not yet.\n\nTheir capability to devise sinister ploys, and these facilities to support their darkest plans... It leaves a rock at my core." }
WordHunterWoW_QuestEN[83484] = { title = "Oh, Rats!", description = "Okay, scout's honor this ain't a joke. I need help because... \n\nI turned my best friend into a rat.\n\nMy friend Allie is the cook here. She tries her best but she's... no good. She's got a bum sniffer. So, I bought her a potion that would make her smell better!\n\n...I mean, improve her sense of smell. But it turned her into a rat! Then she ran off!\n\nYa gotta find her for me. Dealer had another potion to understand rats. I'm too afraid to drink it though.\n\nCan you use it an' find her?", objectives = "Find Alice Grillspark.", progress = "The rat tilts its head, observing you closely.", completion = "I can't just be a rat forever. I need your help!" }
WordHunterWoW_QuestEN[83485] = { title = "Potent Potables", description = "<sniff> <sniff>\n\nThis potion has the scent of the Vatworks on it. There's a vendor at the northern edge there who sells potions. It must be from him. If you can find him, maybe you can get him to hand over an antidote.\n\nPlease help. You're the only one who can understand me!", objectives = "Help Alice Grillspark.", completion = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. \n\nIf you're here to collect on a debt, you are TRESPASSING and must disregard this note.\n\n-Getry" }
WordHunterWoW_QuestEN[83486] = { title = "Remote Work", description = "If you're reading this, I'm out scavenging for reagents along the Kaja'Coast. \n\nIf you're here to collect on a debt, you are TRESPASSING and must disregard this note.\n\n-Getry", objectives = "Locate Getry Sellswill at the Kaja'Coast in Zandalar.", progress = "The pack has largely escaped damage. A well-worn book is visible from underneath the open flap.", completion = "<There must be Redberries growing somewhere in the area.>" }
WordHunterWoW_QuestEN[83487] = { title = "Occupational Hazard", description = "<You surmise that collecting enough redberries and returning them to Humphrey should allow Alice to turn back into her usual goblin self.>", objectives = "Collect the redberry reagents and return to Humphrey.", progress = "Any luck with that antidote, <name>?", completion = "Thanks again for the antidote. We'll hang onto it for later.\n\nTurns out Alice is a much better cook than she ever was before and wants to keep this success story rolling!" }
WordHunterWoW_QuestEN[83489] = { title = "Gathering All Gladiators!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", objectives = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal.", completion = "Ah, I was beginning to wonder when the eager fighters were going to show up. \n\nHere you go, as promised. Use these when submitting Crafting Orders or when crafting your own equipment. The result will be just as powerful as what Lalandi sells over there, but these are great when you're looking for something customized to your liking. If you need more, you know where to find me.\n\nQuestions? Take them to the Forgegrounds." }
WordHunterWoW_QuestEN[83492] = { title = "Warbands: Warbanding Together", description = "{name}, some adventurers have gotten together to form a warband and could use your help.\n\nFind Blue and her group in Gadgetzan.", objectives = "Meet Blue and her Warband in Gadgetzan.", completion = "Thanks for coming, <name>!" }
WordHunterWoW_QuestEN[83493] = { title = "Warbands: Rift Reader", description = "I bet you're wondering what we're working on, huh? We're going to make our Warband Bank accessible from anywhere!\n\nRivet's calling it a Warband Bank Distance Inhibitor until I can think of something more fun, but we need a little help to get it over the finish line.\n\nIf we're going to make sure we can access our shared stash from multiple locations, we're going to need portals! And we tracked some doozies down out here.\n\nIf you could get us some scans of the local anomalies, it'd be a big help!", objectives = "Scan Transpositional Anomalies near Gadgetzan.", progress = "Did you find them?", completion = "Now that's some sparkly data!" }
WordHunterWoW_QuestEN[83494] = { title = "Warbands: Space Ghosts by the Coast", description = "There are an awful lot of half-teleported things wandering around the desert not too far from here. Really, any at all would be a surprising amount, but there are a bunch of them for some reason!\n\nThey don't seem particularly nice, but I bet we could learn from their predicament to ensure the Warband Bank Distance Inhibitor doesn't teleport our sweet loot into a tree!\n\nSee if you can find anything that might help us figure out what went wrong. It's not like people randomly teleport around, right?", objectives = "Collect Spatial Residue from the Partially Teleported creatures near Gadgetzan.", progress = "Any clues?", completion = "Great job, <name>! I'm not sure what that is, but I bet it'll help!" }
WordHunterWoW_QuestEN[83495] = { title = "Warbands: Twinsposition", description = "We're on a roll! We picked up an even more anomalous anomaly while you were out and tracked it down to just west of town.\n\nWe've got a brand-new Transpositional Signal Recombobulatron already set up out there, but I didn't want to start without you. You've been a big help, after all.\n\nAll you have to do is dial it in and throw the switch! Easy as pie, which I'm told is very easy.\n\nRivet says that the odds of something cataclysmic happening are pretty good, so I know nothing bad can happen!", objectives = "Activate the Transpositional Signal Recombobulatron outside Gadgetzan and deal with the consequences.", progress = "Throw the switch!", completion = "Nice job!\n\nNot what I was expecting, but I have to say evil me was rocking that mustache!" }
WordHunterWoW_QuestEN[83496] = { title = "Warbands: Spacetime is Money", description = "Now that we've got all the transpositional data we could ever hope for, all we need to do is set up a wormhole in a suitable banking establishment and we'll be dropping gear into each other's pockets from the field in no time!\n\nAnd there just happens to be a bank right here in Gadgetzan!\n\nYou can even attune your own portal at the same time so you can access your own Warband Bank from anywhere. It's going to be so convenient!", objectives = "Place the De-Recombobulatron Matrix in the Gadgetzan Bank.", progress = "Did you find the bank?", completion = "A few hiccups, but nothing some good old-fashioned teamwork wasn't up to! Go us!" }
WordHunterWoW_QuestEN[83497] = { title = "A Concerned Friend", description = "Ah, {name}, there you are! Great Kyron was asking after you and your friend Anduin. \n\nI think they want to talk to you about Faerin. Nothing urgent mind you, she probably just needs some good company. But we're all a bit worried about her.\n\nCheck in with Kyron when you have a moment, will you?", objectives = "Meet Great Kyron in Mereldar.", completion = "I hope the journey wasn't long." }
WordHunterWoW_QuestEN[83499] = { title = "Arcane Wasteland", description = "Kirin Tor survivors have been hesitant to return to this area. A great deal of energy was dispelled before and after Dalaran's crash. An invisible yet tangible miasma lingers in the area for those who are sensitive to it.\n\nIt is unclear if the site is hazardous or if other more corporeal dangers still lurk here.\n\nI can protect us, but I expended all my reagents at the Proscenium. Will you aid me in procuring more?", objectives = "Help Aethas Sunreaver gather reagents required for a protective spell in the Tranquil Strand.", progress = "The last few days have been... difficult.", completion = "Yes, these will do. Thank you, <name>.\n\nDespite the shards and elementals roaming there, it seems the ruins are not immediately dangerous. But, if we are to spend any time here, an arcane barrier is wise.\n\nWe don't know the long-term effects of exposure of this kind." }
WordHunterWoW_QuestEN[83500] = { title = "Zekvir, Hand of the Harbinger", description = "We'll have tae watch out for Zekvir as we go exploring into delves. I don't think we're strong enough tae take him on just yet, but we will be!\n\nLet's keep explorin' and gettin' treasure until we're tough enough tae track down his lair and defeat him.", objectives = "Defeat Zekvir, the Hand of the Harbinger within his own delve.", completion = "We did it! We made this place safe for all adventurers. \n\nThis should put Xal'atath in a tough spot, now that she's missing one of her most powerful toadies." }
WordHunterWoW_QuestEN[83502] = { title = "Lessons in Defensive Magic", description = "The spell for the barrier is ready, but I must channel it and define its perimeter. \n\nWhile I channel the spell, take these wards and place them at the edges of our would-be barrier.\n\nWe will empower the spell when you are finished.", objectives = "Help Aethas Sunreaver cast a spell to create a protective arcane dome in the Tranquil Strand.", completion = "<Aethas inhales.> \n\nYes. This will do... for now." }
WordHunterWoW_QuestEN[83503] = { title = "Return to Dornogal", description = "The battle is finally over and I suppose it's time we lick our wounds. \n\nHead back to Dornogal, Champion. \n\nI'll be right there as soon as Khadgar is healthy enough to withstand travel.", objectives = "Return to Dornogal in the Isle of Dorn and report what happened.", completion = "Our battle has been hard fought. But there is still much to come." }
WordHunterWoW_QuestEN[83519] = { title = "But What About the Casino?", description = "Times are a changing. Now that ol' Jastor is kaput, the cartel heads are chomping at the bit to settle the fate of Undermine's crown jewel: the Gallagio.\n\nThere's a court proceeding tomorrow to make a final determination, but luckily the deed is squarely in the hands of someone I trust. \n\nTheir name: Rosebud Gallywix.\n\nI know. I know. But Rosey is a good egg. I'll introduce you to him later on.\n\nFirst, do me a favor. Ask the power players here at the party how they feel about the new owner.", objectives = "Ask about Rosebud Gallywix at the Gallagio's opening party.", progress = "Don't get turned off by the Gallywix name. He had a big family, and they ain't all evil crankshafts.", completion = "This... is bad." }
WordHunterWoW_QuestEN[83521] = { title = "Little Help, Please?", description = "So, uh, I swear this never happens, but this kind fellow here pulled me over for a busted tail light.\n\nI just got that fixed. I swear it!\n\nWould you do me a favor? Keep him and any of his colleagues entertained. My license is in one of these compartments somewhere, I just gotta find it.\n\nShouldn't be more than a minute. Two at most!", objectives = "Deal with the Venture Co. \"Policers\"." }
WordHunterWoW_QuestEN[83522] = { title = "Debting For A Living", description = "First of Rosebud's Chiefs on our list are the genius gaming duo: Kayjay and Fantastic Davey.\n\nNow, I heard from my wife's brother that Venture Co. bought up all the debt those boys got. Happened the minute Rosebud was done in.\n\nDid they murder him? Not a great motive if their debt was sky high, but you never know whose pocket a goblin is in either. \n\nBest we see how comfortable they are here at the ol' Venturewood landfill. If they don't want to sign the new deed, we might have our culprits!", objectives = "Speak with Kayjay and Fantastic Davey about signing the new Gallagio deed.", progress = "You'll find all those in my employ are quite content. I've got the bills from various corporate training seminars to prove it.", completion = "You see? They're happy as Zandalari crustaceans.\n\nBut if you're truly invested in poaching their services, perhaps we can make a deal..." }
WordHunterWoW_QuestEN[83524] = { title = "Gold In Them There Trash", description = "Kayjay and Davey are indeed masters of creating games. They've created a new one for me that's been an absolute hit.\n\nIf you're willing to accept the risk, then I will give you the chance to win their employment, and debt, from me.\n\nGrab a pickaxe, and enter the landfill. When the whistle blows, you'll compete against all my other \"employees.\"\n\nWin by the final bell, and I'll let these two go. Lose, and I'll own you.\n\nIt's called Slot Mining. And it will indebt you to me for life.", objectives = "Compete in Slot Mining at The Heaps.", progress = "<Tarbonara says nothing. He simply snarls through his shiny teeth.>", completion = "You didn't win. Surprise, I guess.\n\nWelcome to Tarbonara's debt circus. The fun never stops..." }
WordHunterWoW_QuestEN[83527] = { title = "Winning is for Losers, Anyway", description = "This is the worst job I've ever had. And I used to work Turtle Toss at Darkmoon Faire.\n\nWe're not imprisoned here physically with shackles, but Tarbonara owns all of our debts. He imprinted the information on Debt Markers, which his goons hold on to in case any of us want to know where we stand.\n\nBut if you get a hold of those markers, we're all free. You'd have to crack some skulls to get them though, so I'll give you points for each of his goons bring down.\n\nYou like collecting points, don'tcha?", objectives = "Collect Debt Markers and free the Indenture Debtors.", completion = "Everybody packed in? Good! This will definitely NOT get us pulled over.\n\nCan't praise you enough for this one, <name>. Really. Truly. The Gallagio is going to have an entire floor of gaming enthusiasts ready to go!" }
WordHunterWoW_QuestEN[83528] = { title = "All Part of the Game", description = "Look. I know we're the ones that incurred our own debts, but Rosebud believed in us! With him, there was a light at the end of the casino floor.\n\nWith him gone... We're just two halves of a gaming genius, working for hire instead of salary.\n\nBut Zoomcart told us there's still a chance we could work the Gallagio. Is that true? If it is, Davey and I are in.\n\nProblem is that Davey and I's Debt Markers are held by the gaming commissioner himself: Kudd Milktooth. And he's deep in Tarby's pocket.", objectives = "Collect Kayjay and Fantastic Davey's Debt Markers from Commissioner Kudd Milktooth.", completion = "How much did you have to pay the get their debt markers?\n\nOh... Well then I guess we won't have to fill out reimbursement forms for you then!" }
WordHunterWoW_QuestEN[83529] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Bismuth Butterling, Whispering Stargazer, Regal Dottyback.", progress = "Any bites, <name>?", completion = "These are some great catches, <name>! I can't wait to see what you catch next week!" }
WordHunterWoW_QuestEN[83530] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Bloody Perch, Roaring Anglerseeker, Spiked Sea Raven.", progress = "Any bites, <name>?", completion = "These are some great catches, <name>! I can't wait to see what you catch next week!" }
WordHunterWoW_QuestEN[83531] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Dilly-Dally Dace, Dornish Pike, Azj-Kahet Slum Shark.", progress = "Any bites, <name>?", completion = "These are some great catches, <name>! I can't wait to see what you catch next week!" }
WordHunterWoW_QuestEN[83532] = { title = "Hallowfall Fishing Derby", description = "Life is always on the edge here, {name}. Nerubians, kobyss, hunger--there's always something ready to kill you.\n\nSo we need to find times to relax, and challenge ourselves at something other than survival. Like fishing.\n\nMy dad always spent Saturdays fishing, when I was growing up. He'd say, \"Take some time for yourself, or you can't be effective for others.\" \n\nSo every Saturday, I challenge people to the Hallowfall Fishing Derby. You have one hour to catch trophy fish. See what you can bring me!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Crystalline Sturgeon, Specular Rainbowfish, Sanguine Dogfish.", progress = "Any bites, <name>?", completion = "These are some great catches, <name>! I can't wait to see what you catch next week!" }
WordHunterWoW_QuestEN[83534] = { title = "Ain't No Warm Up Act", description = "Can't believe Revilgaz scheduled us first! No one shows up for the first band!\n\nWhatever. You the one that oldhair Marty mentioned? He already gave me the lowdown on your plan to keep the Gallagio from going to auction. Seems ridiculous. Which makes it our kinda plan.\n\nLet's make a deal. Our manager dumped us when the casino deal went south, so YOU are gonna fill in for her today. Don't worry, couldn't be worse than any other job you've done.\n\nFirst thing on your list: gather us a crowd.", objectives = "Spread the hype and gather a crowd for the Cellar Gnomes.", progress = "Hope you're making up crazy lies to get these people to see us.\n\nThat's what we'd do.", completion = "Great job, boss. You brought in a crowd, and then some.\n\nSecond thing on our list... You know how to play an instrument right?" }
WordHunterWoW_QuestEN[83535] = { title = "Plunder Party Rockin' Rumble", description = "Here! Take this Mecha-Trianbell!\n\nI don't care that you can't play an instrument because you WILL be playing this one.\n\nWhile we're jamming, members of rival bands will storm the stage to stop us. \n\nNot only will the Trianbell ring out in perfect pitch, it'll also blast anyone not in our band all the way to the cheap seats.", objectives = "Protect the Cellar Gnomes with the Mecha-Trianbell while they play.", completion = "Best gig we've ever played! It was a dang warzone, huh?\n\nYou did good. Get oldhair's new deed, and we'll sign." }
WordHunterWoW_QuestEN[83536] = { title = "Undertide Undertaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[83537] = { title = "Geothermal Gem Treatment", description = "", objectives = "" }
WordHunterWoW_QuestEN[83538] = { title = "Excavation Liberation", description = "", objectives = "" }
WordHunterWoW_QuestEN[83539] = { title = "Feeling Blue", description = "I fear... that it may just be me that remains, {name}. Or that the others are too far away to receive my missive.\n\nIt may be up to us to build an outpost here and see to the cleansing of the crash site.\n\nSo be it. It is just as well...", objectives = "Build the Kirin Tor outpost in the Tranquil Strand.", progress = "It's hard to describe what I feel right now.", completion = "Well done. That bag is quite useful, isn't it? I'm glad I thought to bring it with me.\n\nNow, on to the task at hand..." }
WordHunterWoW_QuestEN[83540] = { title = "Work the Line", description = "Not sure if your schnoz picked up what mine did on the drive over, but there were some delightful smells coming from the street below. \n\nProblem was, the crowds were too thick for me to find Gobdre anywhere.\n\nThat's where Noggy comes in. He's a pretty important fella these days, so I figure he'd have some sorta in for us.\n\nHe's generally an unfeeling scientist-type who doesn't spill secrets. But his pride is also fragile as my wife's Rumble figurines. \n\nGive it a poke and he should spill.", objectives = "Get Marin Noggenfogger to spill the beans on Jojo Gobdre's whereabouts.", progress = "Did you just cut the line?", completion = "Noggenfogger gave you a personal recommendation letter, as well?\n\nHe's duller than I thought if he expects I'd let anyone jump the line." }
WordHunterWoW_QuestEN[83541] = { title = "Review Bombed", description = "Show me you ain't just talk.\n\nI give Diner Cards to each customer. They're supposed to fill it out with their reviews on my menu, and return it here. But I haven't seen any yet. \n\nFishy much? Definitely. And not the kind I like.\n\nGo. Fetch. Get my reviews back. I ain't budging an inch in the Gallagio's direction without them.", objectives = "Retrieve 100 Diner Review Cards.", progress = "How'd they like the Junglevine-soaked Stormray?\n\nBet they said it was bitter. I knew that batch was bitter. Ran outta salt when I was cooking it.", completion = "The lazy diners I can understand.\n\nBut my rivals were taking cards because Tarbonara told them it'd run me off their turf? Really? Couldn't they just... cook better food instead?\n\nDoesn't matter. You're no chef, but I guess you pulled through." }
WordHunterWoW_QuestEN[83542] = { title = "Quick Gills for Gold Now", description = "Ah, crabs... I knew this would happen.\n\nThe diners overwhelmingly scored one dish above all others: pan-seared deepwalker thigh with blood-spiced confit algarian orbinid.\n\nLong name, right? I was hoping that would dissuade the customers from writing it on their cards.\n\nTrouble is that I can't make pan-seared anything without a pan, now can I? And I sold my best pan when the Gallagio deal fell through.\n\nWant me back on board? Then get my pan. Those deepwalker thighs ain't gonna sear themselves.", objectives = "Exchange Gold Fish for Gobdre's Prized Pan.", progress = "Blair and Chub Bass. The scammiest lovebirds you'll ever meet.\n\nBut they did source me some terrific fish.", completion = "You still ain't chef material, but you sure are real good at fetch work." }
WordHunterWoW_QuestEN[83543] = { title = "Adventuring in Khaz Algar", description = "We've got scouts in every corner o' Khaz Algar, an' they all report the same thing: trouble.\n\nSeems we got here just in time, eh?\n\nCheck the scouting map on the table behind ye and lend a hand where ye can.", objectives = "Review the Scouting Map to choose an area within Khaz Algar to support." }
WordHunterWoW_QuestEN[83546] = { title = "Responsibility", description = "Today's the day for shiny shoes, {name}!\n\nWe've got our deed signatures. We've got support from the cartels. And we've got... my kids.\n\nMy wife was supposed to come with us today as well, but she slipped in the shower! Can you believe that? She'll be at the chiropractor all morning. I feel awful for her. Absolutely awful.\n\nWelp! Her loss! Let's pack up what we need and I'll drive us all over to the court room!", objectives = "Pack up and drive to court.", progress = "You look worried. You shouldn't be worried. I'm not worried.", completion = "Wow! Big crowd, huh?" }
WordHunterWoW_QuestEN[83547] = { title = "Welcome to the Neighborhood", description = "<A letter has been left in your mailbox. The handwriting is neat and smoothly flowing.>\n\nWelcome to Borogrove, {name}! I'm Llyssabel Dawnpetal, the local steward. I'll be helping you get better acquainted with the neighborhood.\n\nOnce you've settled in, please come see me at Town Hall.", objectives = "Speak with Llyssabel Dawnpetal at Town Hall." }
WordHunterWoW_QuestEN[83548] = { title = "Isle of Dorn", description = "Survivors from the attack on Dalaran are beset by nerubians led by Queensguard Zirix.\n\nLend your aid to protect whomever remains.", objectives = "Speak with Lady Jaina Proudmoore on the Isle of Dorn.", completion = "We won't let the nerubians take any more of our people." }
WordHunterWoW_QuestEN[83550] = { title = "The Ringing Deeps", description = "Speaker Brinthe has gone to The Ringing Deeps to see how the Machine Speakers have fared while she was away.\n\nShe has asked for adventurers to join her at the bottom of the Coreway.", objectives = "Meet Speaker Brinthe in The Ringing Deeps.", completion = "Thank you for coming. This is more of a mess than I expected." }
WordHunterWoW_QuestEN[83551] = { title = "Hallowfall", description = "Anduin Wrynn hopes to gain the trust and aid of the Arathi in Hallowfall.\n\nHe will need help to win over these potential allies.", objectives = "Speak to Faerin Lothar in Hallowfall.", completion = "If you've come to ask for aid, I'm afraid you've found us in the midst of our own crisis." }
WordHunterWoW_QuestEN[83552] = { title = "Azj-Kahet", description = "An Arathi airship is stranded in Azj-Kahet following a vicious nerubian ambush.\n\nAid the survivors as they withstand the nerubian assault.", objectives = "Speak to Faerin Lothar aboard The Reckoning in Azj-Kahet.", completion = "Just in time, <name>. We were caught off guard, now let's push them back." }
WordHunterWoW_QuestEN[83553] = { title = "Magic-stealing Kobolds", description = "I'm afraid that our \"clean up\" of Dalaran extends far from the shores of the Isle of Dorn.\n\nIn my attempts to find you, I circled this island many times. During my flight, I sensed the magic of many familiar items--items that were formerly housed in Dalaran.\n\nDangerous items.\n\nSomeone or something has taken them who knows where. We must find these objects before innocent bystanders come to harm.\n\nFollow me.", objectives = "Meet with Kalecgos at Mourning Rise in the Isle of Dorn.", completion = "We will begin our search here.\n\nI can feel faint arcane auras emanating from around and beneath this structure.\n\nThe kobolds must have found and brought them to this place." }
WordHunterWoW_QuestEN[83554] = { title = "Trinkets, Curios and Other Powerful Objects", description = "The kobolds here could get up to untold mischief with the items they have stolen.\n\nTake what you can back from them by... whatever means you see fit.\n\nWhile you deal with the kobolds around Mourning Rise's grave sites, I will go underground and search Kriegval's Rest and do the same.\n\nMeet me near Kriegval's Rest when you have secured the Kirin Tor artifacts the kobolds stole.", objectives = "Reclaim stolen Kirin Tor artifacts from the kobolds in the Mourning Rise.", progress = "We must search and reclaim what we can. Even the smallest curio could be meaningful to someone... or dangerous.", completion = "I am shocked to see how much they managed to pilfer in such a short time." }
WordHunterWoW_QuestEN[83555] = { title = "Mysterious Necklace", description = "<The gem pulses with arcane energy, hinting at ancient magic woven into its very core.>", objectives = "Return the necklace to Kalecgos at Mourning Rise in the Isle of Dorn.", completion = "The kobold that had this was dead, did you say?\n\nThat... does not bode well." }
WordHunterWoW_QuestEN[83556] = { title = "Maybe You Shouldn't Touch That", description = "This necklace...\n\nIt is clearly full of powerful magic, but... it is elusive--as if it is hiding its origin from me.\n\nYou take another look. Maybe there's something obvious I'm missing.", objectives = "Investigate the Emerald Necklace in Mourning Rise.", completion = "It was foolish of me to let my guard down. \n\nDo not be alarmed, <name>, but this appears to be a... pocket dimension.\n\nIf the kobolds that met their demise here are any indication, it may be difficult to return to the Isle of Dorn." }
WordHunterWoW_QuestEN[83558] = { title = "Casino Court", description = "I'm all set to make our case. Just one tiny, little, minor thing to let you know about...\n\nThere's a bomb under my desk here.\n\nDon't be alarmed! It ain't the first time this has happened. But there's a lot of people here, and I'd hate to interrupt the proceeding for one little explosive.\n\nTake this X-Plo-Dar 64k. Use it to trace the bomb's signature back to the goblin with the trigger.\n\nMy lawyer's instinct is telling me that the culprit behind this explosive is also Rosebud's killer. Just a hunch.", objectives = "Use the X-Plo-Dar 64k to reveal who's holding the bomb's trigger.", progress = "Have you found the source yet?", completion = "Tarbonara? He's the bomber? ...Really?\n\nOnly reason I'm so surprised is because it felt too obvious!" }
WordHunterWoW_QuestEN[83559] = { title = "Regular Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83560] = { title = "Legendary Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83561] = { title = "Campaign Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83562] = { title = "Calling Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83563] = { title = "Coffee is for Closers", description = "You've got us the hard evidence we needed. All that's left to do is reveal Rosebud's killer to the judge.\n\nI imagine Tarbonara won't go down lightly, so be prepared for one of any number of goblin-like reactions.\n\nYou know what I mean. Explosions or cannons or crying or casino heists or whatever. I'm not worried though, you seem capable.", objectives = "Defeat Tarbonara Fizzlecrank, and ensure Judge Landro notarizes the new Gallagio deed.", progress = "I had a feeling this would be a great case.", completion = "What did I say? I said to be prepared for a goblin-like reaction. And, oh boy, did we get one.\n\nAs you can see, everyone followed Gazlowe into scuffling with Tarbonara's goons. We did pretty good, yeah?\n\nMyself? I'm heading to the Gallagio's entrance. The new deed holders are all up there, and I want to wish them well before you and I are both promoted from lawyers to customers." }
WordHunterWoW_QuestEN[83564] = { title = "Daily Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83565] = { title = "Weekly Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83566] = { title = "Oh, That Casino!", description = "You'd make a good lawyerer, you know that?\n\nHah! Just kidding! The real industry secret is that there's no such thing as a good lawyerer!\n\nWhy don't you join me at the Gallagio's entrance? It'll be a nice send off for the kids who are gonna run this place now.\n\nNot to mention that we should actually hand them the notarized deed!", objectives = "Hand the Gallagio over.", progress = "You teary-eyed because our adventure is over?\n\nOr because you were secretly hoping the place would go to auction, and you'd have a chance to buy it up?\n\nBet it was the latter! Hah!", completion = "Sometimes it feels like there's a never ending stream of problems to solve coming out of the proverbial sewer drain. Doesn't it, <name>?\n\nBut this one... Well, let's just say that this one feels like a personal favor to all of Undermine.\n\nAin't no key to the city, but Marty wanted to pass on one his best lawyerin' outfits to you. Wear it with pride, kid." }
WordHunterWoW_QuestEN[83567] = { title = "Meta Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83568] = { title = "Important Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83569] = { title = "Death and Taxes", description = "He just... exploded...\n\nIf a goblin's gotta go, that's the way. All I can say for poor Rosey. And that I'm gonna miss him. AND that we're gonna find out who did this!\n\nBut the more immediate pickle is this: Who owns the Gallagio now?\n\nIt's time to turn to an expert on legal mumbo jumbo. The State of Undermine assigned a public defender to us for the court case tomorrow, a fella named Zoomcart. He's all we got.\n\nTake what's left of the deed to his office in Hovel Hill, and sort this out.", objectives = "Meet the State of Undermine's assigned Public Defender.", completion = "I assure you, I'm usually drowning in my paperwork far more figuratively than I was a moment ago." }
WordHunterWoW_QuestEN[83570] = { title = "Repeatable Turn-In Quest (DNT)", description = "", objectives = "" }
WordHunterWoW_QuestEN[83587] = { title = "Our Chance to Strike", description = "<The child-like spider presents you with a sealed scroll. The sealed letter bears the markings of the Vizier.>\n\nThe balance of power is shifting in Azj-Kahet. The Queen grows more unstable by the day and I fear we must act before our opportunity to stop her slips from our grasp. \n\nMeet me at the Royal Apothecary when you receive this letter.", objectives = "Meet with the Vizier at the Royal Apothecary.", completion = "I would have rather sent my personal attendant to fetch you but the situation demands the utmost discretion." }
WordHunterWoW_QuestEN[83616] = { title = "The Entrenched", description = "And now the other piece to this coup.\n\nI've been operating under Grand Overspinner Antourix's mandibles for a while now. She's entrenched in Rak-Ahat, and thinks nothing can touch her at the top. She has already refused to submit to Ren'khat.\n\nEven she knows that if Ren'khat has the backing of the throne then it is only a matter of time. Let us expedite her attempts to oust this upstart.\n\nSee how quickly they turn on each other.", objectives = "Offer your services to Grand Overspinner Antourix against Ren'khat.", progress = "An overcrawler? Here? In MY dominion?! Minions! Slay them!\n\nWait! Wait...\n\nYou might be useful...", completion = "Ugh. I don't have time for any of this." }
WordHunterWoW_QuestEN[83627] = { title = "The Beginning of Something Beautiful", description = "<This seems like it would be of interest to a nerubian alchemist. \n\nAscension is their specialty, and this may be key to understanding more about the process.>", objectives = "Take the Vial of Skyrazor Blood to Shalba.", completion = "Hm? What? Well this is fascinating..." }
WordHunterWoW_QuestEN[83628] = { title = "Tense Recovery", description = "Things with these strangers are... tense. We do appreciate being allowed to take cover here in their camp. But they only seem to tolerate us at best. We offered to share our supplies, but that offended them, somehow.\n\nMy sister is gravely wounded. I can see herbs I could use to help her in that tent over there, but that giant snail is blocking the entrance. I can't get to them.\n\nI asked the guard on the hill for aid, but all he did was glare. I don't know what to do! Perhaps he'll listen to you?", objectives = "Speak to the strangers to improve relations with the Arathi.", completion = "You are not unwelcome, stranger. I am the last." }
WordHunterWoW_QuestEN[83629] = { title = "Ancient Respite", description = "This was once a great lake. Over time the roots ruptured its floor, and drained the water away. I have lived here for all of my lifetime and witnessed it all. But now, darker changes have come.\n\nSometimes changes comes with death. Decay is natural.\n\nBut the mites that feed upon my people are not. They spread an odd infestation that makes my bark feel like it crawls from my body.\n\nDestroy these mites, so that I may rest without fear of their mouths upon my sleeping form.", objectives = "Kill 15 Feasting Mites for Goehi.", progress = "The sound of their gnawing fills me with dread.", completion = "It is quiet. Perhaps I will rest, now, with my people." }
WordHunterWoW_QuestEN[83632] = { title = "Rings of Memory", description = "I appreciate what you have done. Do not worry--I am not finished yet.\n\nIf you please, take this root to those who sent you. They can read the history of my life within the rings of wood therein. My life is one of many in the tapestry, but we are all intertwined. \n\nThese strangers you encountered may be reclusive--secretive even--but they understand this tapestry like no other, and guard it with their lives.", objectives = "Bring Goehi's Root to Wild Camp Or'lay.", progress = "Did you find the ancients?", completion = "Goehi sent this root, yet was still alive...\n\nI understand. His story is safe with us." }
WordHunterWoW_QuestEN[83639] = { title = "Open Communications", description = "You understand that others lead lives different to your own. Our ways restrict us. Our traditions are not for the ears of strangers. I have only spoken to you at all due to Orweyna's word. But I can feel On'hiea's disapproval from here.\n\nIt is uncomfortable to have mysteries at times. It is why so many fear the dark. It is unknown.\n\nI know I must seem cryptic. But our ways do not mean we are offended by the Arathi. They are creating tension where it does not exist for us.", objectives = "Speak to Ysabel and clear up the misunderstanding.", progress = "I can't leave my sister like this.", completion = "I can't believe this was just a simple misunderstanding. I shouldn't have made assumptions. \n\nThank you for easing my mind--and for helping my sister." }
WordHunterWoW_QuestEN[83641] = { title = "Trapped Between Life and Death", description = "A pocket dimension. This is old magic.\n\nMalygos used pocket dimensions on occasion when he did not wish to be disturbed.\n\nThey were mainly used by mages as research spaces or for testing dangerous spells. Or if a mage wanted to hide what they were doing...\n\nI wonder who made this one? I suppose it doesn't matter. We need to get out. \n\nThankfully, every pocket dimension has an exit. Though, it is normally well hidden.\n\nLet's find it.", objectives = "Find a way out of the pocket dimension.", completion = "Look! Whatever magic was left in that necklace is gone now. And with it, Kel'Thuzad's mirror image." }
WordHunterWoW_QuestEN[83643] = { title = "Somehow We Survived", description = "What we experienced in Kel'Thuzad's pocket dimension is a timely reminder of what can happen when magic is used without regard to ethics or regulation.\n\nTo me, this underlines the importance of the Kirin Tor.\n\nBut, on the other hand, Kel'Thuzad was Kirin Tor. It is also a reminder of how power corrupts.\n\nNow that we have made sure these artifacts will not cause anyone else to go on an unexpected trip... Let's return to Aethas. \n\nPerhaps now more have responded to his letter.", objectives = "Regroup with Kalecgos at the Tranquil Strand.", completion = "It looks like more mages have arrived!\n\nThis gives me hope.\n\nI am sure Aethas will be relieved." }
WordHunterWoW_QuestEN[83707] = { title = "LFGDungeons - 11.0 The War Within - Raid Finder - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[83708] = { title = "LFGDungeons - 11.0 The War Within - Raid Finder - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[83711] = { title = "Weapons of Conquest", description = "Tales of your prowess have reached even me, hero. If you fight as well as they say you do - then I reckon you would be even better with one of my creations. Write your name in history. Return when you've proven yourself both skilled and honorable.", objectives = "Obtain Conquest in Rated Arenas and Battlegrounds." }
WordHunterWoW_QuestEN[83715] = { title = "Claimed Salvage", description = "", objectives = "" }
WordHunterWoW_QuestEN[83716] = { title = "Beneath the Roots", description = "I am glad to see you are well, {name}. I have recently received word that a number of the Aeroknights have taken shelter in a camp close to where the airship was seized in mid-air. \n\nWould you check on them?", objectives = "Find the camp sheltering the Aeroknights in western Azj'kahet.", completion = "We are doing our best with what we have. The owners of this camp have allowed us sanctuary, but there are no smiles here." }
WordHunterWoW_QuestEN[83718] = { title = "Eggstraction", description = "", objectives = "" }
WordHunterWoW_QuestEN[83719] = { title = "Those Are Chitin Words", description = "Well now, this is certainly an interesting specimen. It seems the original creator who worked on this creature made grave errors in balancing the genetic materials. No wonder the creature you encountered was an abomination. What terrible technique!\n\nWith the right materials however, I may just be able to perfect it. Siesbarg here will be our test-subject. Perhaps his Ascension will finally catch the attention of those in charge of administering promotions!", objectives = "Collect enough Nerubian Chitin for Shalba's experiment.", progress = "Chitin samples will help define the strength of Siesbarg's new form.", completion = "I will put this chitin to great use!" }
WordHunterWoW_QuestEN[83720] = { title = "Venom? More Like Get 'Em", description = "Now that we've acquired enough chitin samples to splice into the perfect armor, we need the perfect venom. Don't look at me like that. Our forms should always be powerful and capable of defending themselves!\n\nI'll begin incorporating the new carapace requirements for Siesbarg's Ascension while you harvest what I need. Do keep in mind though, it must be nerubian venom, specifically. I'm afraid beetles and spiders simply won't do this time around. \n\nAs for where you find it, well that's up to you.", objectives = "Collect enough Nerubian Venom for Shalba's experiment.", progress = "Very good! This is exactly what I was looking for.", completion = "This will do nicely. Onto the final phase of my experiment!" }
WordHunterWoW_QuestEN[83721] = { title = "A Small Ocean's Worth of Blood", description = "Excellent! The end draws near! But although we near completion, we cannot go without the most important part of this genetic equation--the blood. We need a small ocean's worth of nerubian blood. \n\nHowever, to make this new form foolproof, the blood must come from the strongest nerubians to exist. Whether skyrazor or Ascended, it doesn't matter. This will guarantee we have the best genetic material available.\n\nThe kind of material that Siesbarg deserves!", objectives = "Collect enough Nerubian Blood for Shalba's experiment.", progress = "Our experiment nears fruition, overcrawler.", completion = "Brace yourself--you are about to witness perfection!" }
WordHunterWoW_QuestEN[83722] = { title = "Consolation Flies", description = "Well... that's unfortunate.\n\nIt appears my experiment has failed and Siesbarg paid the price. Still, I am optimistic for the future I am destined to acquire. It's only a matter of time until I perfect my process. When I do, perhaps I shall engineer my own Ascension!\n\nWhile his physical form isn't what I intended, it appears Siesbarg's mind is intact. I'm certain he can still be of use. Take him. His new form can provide better service on the field of battle than in my tiny shop.", objectives = "Take Siesbarg off Shalba's hands.", completion = "<After a heavy scoff towards Shalba, Siesbarg enthusiastically stands by your side.>" }
WordHunterWoW_QuestEN[83723] = { title = "A Helping Hand", description = "Kalecgos's hypothesis that Dalaran's debris interferes with long-range teleportation seems correct.\n\nMage portals have appeared along the shore, but no one has stepped through them. There are likely mages trapped within the portals.\n\nOr, something mana hungry--like felhunters--may be being lured here by the release of Dalaran's power.\n\nWe must investigate. Mages of the Kirin Tor may be in danger. The felhunters are an acceptable risk.\n\nLet us not waste any more time.", objectives = "Help mages exit their portals on the Isle of Dorn.", completion = "I'm glad to see the scattered mages of the Kirin Tor answering Aethas's call." }
WordHunterWoW_QuestEN[83737] = { title = "Chromie's Time Trips", description = "", objectives = "" }
WordHunterWoW_QuestEN[83738] = { title = "Notorious with The Weaver", description = "Many many thanks for you from the Weave-mother. \n\nCome back to the Lair. I have good goods for you. \n\nI have webbed up and protected them, so no you worry!", objectives = "Speak with Bobbin in the Weaver's Lair.", completion = "Keep up the good good!\n\nThe Weaver also asks us to give you her \"compliments,\" but I find no \"compliments\" in here.\n\nMaybe I ate them? Apologies!" }
WordHunterWoW_QuestEN[83739] = { title = "Notorious with The General", description = "Word of your deeds has reached many of The General's acolytes!\n\nFind me at the Weaver's Lair. We have prepared a tribute for you!", objectives = "Speak with Aspirant Kiipka in the Weaver's Lair.", completion = "Here! Accept these gifts as a tribute to your strength!\n\nIgitith ik tak'na!" }
WordHunterWoW_QuestEN[83740] = { title = "Notorious with The Vizier", description = "The Vizier has asked me to provide you with additional resources towards your efforts.\n\nCome to the Weaver's Lair. I'll be waiting for you with a parcel.", objectives = "Speak with Tulumun in the Weaver's Lair.", completion = "The Vizier's compliments should be a more than sufficient gift for you...\n\nBut I suppose these goods would simply go to waste if not for his generosity. Take them. Be grateful.\n\nAnd do try to remain alive, overcrawler." }
WordHunterWoW_QuestEN[83742] = { title = "Call to Attention", description = "Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter.\n\nI am not at liberty to say more here. Seek out the General for further briefing.\n\nFor Azj-Kahet.", objectives = "Report to General Anub'azal in Siegehold.Hail, soldier. General Anub'azal requests your presence at Siegehold immediately. He requires your expertise in the investigation of a sensitive matter.\n\nI am not at liberty to say more here. Seek out the General for further briefing.\n\nFor Azj-Kahet." }
WordHunterWoW_QuestEN[83743] = { title = "Arcane Cold War", description = "A few mages have come but... I expected more to act on Aethas's call to action.\n\nBut perhaps that was wishful thinking.\n\nWe need more help despite what you and Kalecgos did at Mourning Rise. Aside from Kel'Thuzad's pendant, the kobolds' plunder was middling-powered artifacts.\n\nMeanwhile, there have been reports of powerful magical objects filtering through Azj-Kahet, meaning the nerubians must have scavenged Dalaran's crash first!\n\nWe must find these artifacts before they are used against us.", objectives = "Travel to Azj-Kahet and meet with Lady Jaina Proudmoore.", completion = "We may have arrived too late, <name>. For all of us." }
WordHunterWoW_QuestEN[83749] = { title = "Delves: The Waterworks", description = "What a trip! Can ye believe how much exists below the depths here? \n\nThe Machine Speakers were telling me of problems they're having over at a place called the Waterworks. Sounds like kobolds are making trouble again. They're also storing some treasure deeper within the place.\n\nWhat do ye say? Let's go on an adventure and help out these folks!", objectives = "Complete the Waterworks delve on any difficulty.", completion = "In and out. No problems at all!\n\nExcept for this trapped chest in front of us." }
WordHunterWoW_QuestEN[83750] = { title = "Wanted: Zuramat the Obliterator", description = "_", objectives = "Find Zuramat the Obliterator and collect his soul stone in Azj'Kahet." }
WordHunterWoW_QuestEN[83752] = { title = "Threats of Zekvir", description = "Someone's watchin' us, {name}. They put this chest here for us to find.\n\nLet me know when you're ready. I'll trigger the trap here to see just what exactly is going on.", objectives = "Speak with Brann Bronzebeard to investigate the strange chest.", completion = "Well, I'm not one tae let a little threat stop me from exploring farther. Looks like I got more investigating tae do. \n\nI'm sure I'll see you again real soon!" }
WordHunterWoW_QuestEN[83753] = { title = "Cannon Karma", description = "This is gettin' serious, {name}! Those pirate goons have a cannon and are threatenin' to blow us outta the sky!\n\nBut this may also be an opportunity.\n\nIf youse get rid of the monkey firin' the cannon, we maybe can get control of it for ourselves for some payback!", objectives = "Bilge Rat attack disrupted and Cannon Master Jin'chu eliminated.", progress = "Ya better be tellin' me dem pirates is all gone!", completion = "Couldn't have done better myself. Youse should have a Kaja'Cola to celebrate." }
WordHunterWoW_QuestEN[83755] = { title = "Delves: Nightfall Sanctum", description = "Good tae see you again! I've run into a bit of a mess since we last met.\n\nSome nerubian called \"Zekvir\" wants the expedition to stop explorin' this land. You know what that means. We've got to explore even more!\n\nThese Order of Night cultists might have information regarding Zekvir. Let's go to Nightfall Sanctum and see what we can find out.", objectives = "Find evidence of Zekvir within the Nightfall Sanctum and complete the delve on any difficulty.", completion = "Hrm... So this Zekvir fellow seems tae be lurking in the dark of a lot of places we're exploring. He might even be capable of empowering folk!\n\nWe'll have tae go deeper tae figure this out. Leave the legwork tae me!" }
WordHunterWoW_QuestEN[83758] = { title = "Delver's Call: Fungal Folly", description = "We've got more reports of fungarians returning to a place we've dubbed \"Fungal Folly.\"\n\nExplore the cave and eliminate any threats you find.", objectives = "Complete the Fungal Folly delve on any difficulty.", progress = "Are you the one who grabbed the task for Fungal Folly?", completion = "Thank you for dealing with the fungarians. One day they won't be such a malfunction in our systems." }
WordHunterWoW_QuestEN[83759] = { title = "Delver's Call: Kriegval's Rest", description = "HELP WANTED\n\nKriegval's Rest has become overrun by kobolds! This once sacred resting place of the earthen must be restored.", objectives = "Complete the Kriegval's Rest delve on any difficulty.", progress = "Are you investigating Kriegval's Rest?", completion = "Kriegval's Rest is a sacred place to our people. Thank you for helping us restore it." }
WordHunterWoW_QuestEN[83761] = { title = "Delves: The Underkeep", description = "Who would've thought I'd be cozying up in a nerubian's lair!\n\nThere's a nasty named Zekvir threatening folks trying to explore the island. I've been asking the Weaver for any information she's got.\n\nSupposedly, there's a place called the Underkeep that might have records on him. Let's check it out and see what we can find!", objectives = "Find information on Zekvir within the Underkeep and complete the delve at any difficulty.", completion = "Zekvir is an agent of Xal'atath! And he's trying to destroy any memories of Azeroth that he finds.\n\nThat makes our job of exploring more crucial than ever, <name>. We won't give up, not even with Xal'atath's toady chasing us!" }
WordHunterWoW_QuestEN[83762] = { title = "Critical Mass", description = "This is exactly what I had feared.\n\nThalen Songweaver's notes on the mana bomb he devised to devastate Theramore were under guard in Dalaran. Few knew of this.\n\nI argued they should be destroyed. But others argued if such a bomb was again created, we would need them to disarm it.\n\nAnd now those notes are both the problem and the solution. \n\nThankfully, I have read these notes, {name}. I will walk you through disarming the mana bomb.", objectives = "Help Lady Jaina Proudmoore disarm the mana bomb in the Breathing Pit.", completion = "My faith in you is never misplaced. Well done." }
WordHunterWoW_QuestEN[83763] = { title = "Preserve the Legacy", description = "The larger threat has been contained, {name}, but I believe there are still other artifacts important to our legacy--good and bad--here in Azj-Kahet.\n\nWhile they are still dangerous, their knowledge may benefit us in the long run. And, we must not allow the nerubians to profit from what they and Xal'atath did to Dalaran.\n\nLeave no dark corners here in the Breathing Pit unexplored, {name}.", objectives = "Collect valuable items from the Breathing Pit.", progress = "We must reclaim what we can of the Kirin Tor's legacy.", completion = "What have you found?\n\nThalen Songweaver's notes. \n\nThe rest will be kept safe, but these notes...\n\nI will see to their destruction myself.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[83764] = { title = "Too Powerful, Too Dangerous", description = "Some of the relics the nerubians now possess were housed in carefully-designed containment vaults on Dalaran. That is how dangerous and powerful they are.\n\nWith those vaults gone, the only course of action we can take is to destroy them.\n\nIn hindsight, it seems a grave mistake to have gathered so many powerful artifacts in one place--even if that place was Dalaran.\n\nI would trust no one else with this task, {name}. Find and destroy those artifacts.", objectives = "Find dangerous artifacts scattered around in the Breathing Pit and destroy them.", completion = "Thank you, <name>.\n\nIn the future, the Kirin Tor must find better ways to study and safeguard magical artifacts." }
WordHunterWoW_QuestEN[83766] = { title = "Delver's Call: Dread Pit", description = "Two things are bad for business. Earnest competition and the Dread Pit caves. We need someone to deal with the latter!\n\nSomething bad is going on here. We lost a bunch of workers in this cave.\n\nWe need you to deal with the threat, so we can keep business booming!", objectives = "Complete the Dread Pit delve on any difficulty.", progress = "Glad I finally found someone to check out the Dread Pit!", completion = "You took care of them spiders in the Dread Pit? Great!\n\nI'll get to work on figuring out a better name for that place. \"Dread Pit\" just ain't catchy enough." }
WordHunterWoW_QuestEN[83767] = { title = "Delver's Call: The Sinkhole", description = "We have reports of large amounts of kobyss gathering towards a lair called the Sinkhole. There are concerns they plan to attack the smaller coast villages when they get the chance.\n\nThere's a hefty reward for anyone who can go into the Sinkhole and stop whatever they're planning!", objectives = "Complete the Sinkhole delve on any difficulty.", progress = "Beware of what lurks within the Sinkhole.", completion = "Thank you for the aid. It's hard to aid everyone in Hallowfall given the current situation.\n\nHopefully, the kobyss will think twice about trying any further attacks." }
WordHunterWoW_QuestEN[83768] = { title = "Delver's Call: The Skittering Breach", description = "Call For Any Who Can Swing a Sword or Sling a Spell!\n\nThe nerubians perform foul rituals in the shadow of our once beautiful Aegis Wall. Word is that a dark temple dedicated to their cursed gods rests beneath the ground. \n\nSomeone must investigate this foul place and put an end to their schemes.", objectives = "Complete the Skittering Breach delve on any difficulty.", progress = "The Skittering Breach is a dangerous place. Be on your guard if you're going in.", completion = "You survived the Skittering Breach? I know many a Lamplighter who was forced to retreat from that foul place.\n\nYou've made this land safer. Thank you." }
WordHunterWoW_QuestEN[83769] = { title = "Delver's Call: Mycomancer Cavern", description = "Spice Help Needed!\n\nFungarians in the Mycomancer Caverns have been raiding spice crates bound for Lorel's Crossing. Someone needs to go into those caverns and push back the fungarian menace! \n\nWill pay well.", objectives = "Complete the Mycomancer Cavern delve on any difficulty.", completion = "I heard the fungarians had been thinned out by someone recently. Thank you!" }
WordHunterWoW_QuestEN[83770] = { title = "Delver's Call: Spiral Weave", description = "A lot of us survivors have heard stories about the Spiral Weave. Seems like it's a place where the nerubians have some heavy military operations going on.\n\nTaking the fight to them would help put a serious dent in the nerubians' war plans.", objectives = "Complete the Spiral Weave delve on any difficulty", progress = "You're going into the heart of a nerubian military base. Be careful.", completion = "You did it! That should give our forces on the surface a bit of a reprieve." }
WordHunterWoW_QuestEN[83771] = { title = "Delver's Call: Tak-Rethan Abyss", description = "WEAVER'S ORDERS\n\nThe Tak-Rethan Abyss continues to be a place of great unrest and trouble.\n\nSomeone must keep the threats in check before they interfere with our plans.", objectives = "Complete the Tak-Rethan Abyss delve on any difficulty.", progress = "Are you investigating those kobyss?", completion = "Fine work. I shall let you know if I require any further kobyss-related purges." }
WordHunterWoW_QuestEN[83773] = { title = "Farewell, City of Magic", description = "Not all the Kirin Tor's issues can be solved in one day.\n\nBut one way we can act is to honor those who have fallen. After speaking with everyone here, we have cobbled together a ceremony to send off those we have lost... and Dalaran.\n\nWe would be honored if you would join us and participate in remembering our fallen comrades in the Kirin Tor.", objectives = "Place mementos brought by Dalaran survivors on the boats in the Tranquil Strand.", progress = "One thing I am sure of is that the Kirin Tor's future is not another floating fortress in the sky.\n\nNo, whatever path the Kirin Tor chooses, it will be firmly rooted here, on Azeroth, among the people it serves.", completion = "I will stay here with all of you and help however I can." }
WordHunterWoW_QuestEN[83775] = { title = "Infinite Growth II", description = "", objectives = "You have grown considerably, but you may be in need of my services. Eternus has approved a dispensation of Bronze for experienced Timerunners. I can empower your equipment, if you require." }
WordHunterWoW_QuestEN[83776] = { title = "Infinite Growth III", description = "", objectives = "It feels mere moments since last we spoke. I have additional Bronze for you. You may do with it what you wish." }
WordHunterWoW_QuestEN[83777] = { title = "Infinite Growth IV", description = "", objectives = "Timerunner! You have come far. Is this the end of your journey in this timeline or just the beginning? I can continue empowering your equipment to greater heights or you may decide to trade your Bronze with the other Infinites within. The choice is yours." }
WordHunterWoW_QuestEN[83793] = { title = "Aid the Jinyu", description = "", objectives = "Our people are restless to flow with the waters. Lend aid to our village, that we may move with the currents.", progress = "Our people are restless to flow with the waters. Lend aid to our village, that we may move with the currents.", completion = "We are grateful for your offerings." }
WordHunterWoW_QuestEN[83794] = { title = "Soggy Celebration Crate", description = "<The crate is pretty wet and smells a bit fishy, but looks to be mostly sealed tight. Alyx would appreciate the supplies returned.>", objectives = "Return the Soggy Celebration Crate to Alyx.", progress = "Oh, I am so busy. But what can I help you with?", completion = "Oh, you found a missing crate! That's great!\n\nWait... why does this smell like fish? Actually, I do not want to know. \n\nI really appreciate you returning these. If you find any more please bring them to me." }
WordHunterWoW_QuestEN[83795] = { title = "Aid the Hozen", description = "", objectives = "You hozen friend, wikket? Give da jingle jings!", progress = "You hozen friend, wikket? Give da jingle jings!", completion = "Woot! You a real nibby wookin, wikket!" }
WordHunterWoW_QuestEN[83825] = { title = "Restoring A Grand Tale", description = "It was terrible! My book was shredded, and the pages flew everywhere! \n\nI saw some caught in the sand devils that went down the tunnel, others caught on adventurers heading out to face the big monsters in Tanaris, and others are scattered around here. Maybe that bird thing of yours could find them?\n\nPlease help me get the pages back so I can restore my book!\n\nOh, and watch out for that shady Cravitz Lorent. He's selling new copies for a hundred gold under the Fashion Frenzy stage. Robbery!", objectives = "Return a Green Hills of Stranglethorn to Raenie Fizzlebog outside the Caverns of Time", progress = "Were you able to find all the pages and repair my book?", completion = "Oh, it looks almost new! You did a great job. I can't thank you enough. \n\nAlyx said to give you this for your help! And if we could keep this between us, that would be great. No need to let my sister Addie know that I almost lost her gift." }
WordHunterWoW_QuestEN[83827] = { title = "Silence the Song", description = "The sirens... they're out there! And I wonder... was it the crystal or these creatures that the Kul Tirans named this isle after?\n\nWhichever it may be, these sirens' call has lured many of our forces to their doom.\n\nOur goblin allies have prepared a device to remove the control they have over our troops.\n\nEliminate these \"sirens\" and dispel the charm that holds our troops captive.", objectives = "Free 7 Charmed Troops and slay Macabea The Sea Banshee.", progress = "Have you eliminated the siren threat?", completion = "Excellently executed, <name>. No soul should succumb to such dreadful creatures again." }
WordHunterWoW_QuestEN[83832] = { title = "Torn Dreams", description = "Hello again! I could really use your help here. \n\nA visitor by the name of Addie Fizzlebog had a book damaged by some time devils that swept through here last night. I am still dealing with all the other problems they caused and was hoping you could help Addie with her issue.", objectives = "Seek out Raenie Fizzlebog outside the Caverns of Time.", completion = "THE Hemet Nesingwary is here signing his Green Hills of Stranglethorn book. I was going to have him sign my copy, but then dust devils tore through the camp and shredded it!\n\nMy sister won't let me leave the camp on my own, and I couldn't stand to tell her that the book she gave me was ruined. I could really use your help!" }
WordHunterWoW_QuestEN[83930] = { title = "Deworming Solution", description = "", objectives = "" }
WordHunterWoW_QuestEN[83931] = { title = "Battered Celebration Crate", description = "<The crate is pretty battered. It looks like at least one wolf chewed on its corner. Alyx would appreciate the supplies returned.>", objectives = "Return the Battered Celebration Crate to Alyx.", progress = "Oh, I am so busy. But what can I help you with?", completion = "Oh, you found another of our missing crates!\n\nIt looks like you got to it just in time. A bit more and whatever animal was trying to get in would have spoiled the supplies. \n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[83932] = { title = "Historical Documents", description = "Imagine having the chance to accompany Sky-Captain Elaena Lancekat on such a great adventure. This is the opportunity of a lifetime!\n\nBut if I'm going to write a book about this journey, I need to gather some historical information about this island.\n\nPerhaps you could collect any notes or documents that you find? Anything might be useful and tell us about the history of this place!", objectives = "Add 12 Notes and Documents found on the isle to the Research Journal.", progress = "What did you find?", completion = "You've gathered so much valuable information. There were so many secrets to be uncovered here! \n\nI can't wait to start writing this book.\n\nBut I need to come up with the perfect title first..." }
WordHunterWoW_QuestEN[83933] = { title = "The Kaja'Coast", description = "Alright, we got the punch card to the Kaja'Coast and a pretty good reason to believe Venture's shmoozin' up to Gallywix a lot more than we thought.\n\nNoggenfogger said we'd find answers at those mines, and that means goin' down to the Kaja'Coast for a look.\n\nLet's go. We'll meet you over at Slam Central.", objectives = "Meet Gazlowe and Renzik at Slam Central Station, then use the Coastside Drill to travel to the Kaja'Coast.", completion = "Darkfuse is watchin' this place.\n\nThey're hidin' somethin' here. Somethin' big." }
WordHunterWoW_QuestEN[84001] = { title = "Cart Blanche", description = "Our mining team is making great progress. All our carts have already been loaded with ore samples and sent back to camp. \n\nThere's a problem though...\n\nNone of the carts made it to camp due to trouble on the tracks!\n\nPlease repair the tracks and collect any lost ore if you can so we can get those samples to camp.", objectives = "Repair 2 Mine Tracks, clear 5 Crashed Mine Carts, and collect 12 Ore Samples.", progress = "Are the mine carts getting through now?", completion = "Excellent work, <name>. I knew you would find a way to solve this problem." }
WordHunterWoW_QuestEN[84020] = { title = "A Mech in Need", description = "This mechsuit has seen better days. Maybe a skilled Machine Speaker could assist you. \n\nI know Speaker Jurlax has been assigning machinists to mechsuit maintenance lately. He probably has some advice for you.", objectives = "Bring the Malfunctioning Mechsuit to Speaker Jurlax in Gundargaz.", completion = "Time and decay have wrought havoc on this machine.\n\nWith a bit of work, we might still be able to recover it." }
WordHunterWoW_QuestEN[84021] = { title = "Machine Without Cogs", description = "Diagnosis: This machine's movement is impaired.\n\nWe must get it moving again. I'm going to need some replacement parts. The gears must keep grinding.", objectives = "Bring an Overclocked Gear-A-Rang Launcher to Speaker Jurlax for parts.", progress = "Did you bring the parts we need?", completion = "Precisely what I need: the right part of the right job. \n\nThis should work." }
WordHunterWoW_QuestEN[84022] = { title = "Uniting Severed Threads", description = "You have done well to ally Anub'azal and Nizrek to our cause.\n\nIt is time that we solidify this triumverate relationship between us all. We will conference via shadecasters. Activate them when you're ready to begin.", objectives = "Join forces with the Weaver, the General, and the Vizier to forge the Severed Threads.", progress = "I wonder how our three potent personalities will work together. Only time will tell, I suppose.", completion = "I expected far more verbal dueling than what occurred. To be so willing to work with one another must mean these times are dark indeed.\n\nWe have a long road ahead of us. I will say plainly that your help has been invaluable. It may end up being the thread that allows my people to survive.\n\nThank you." }
WordHunterWoW_QuestEN[84023] = { title = "Orienting Ourselves", description = "The machine moves without intent.\n\nLet us guide it toward purpose.\n\nDeliver direction unto this device.", objectives = "Bring a Synergistic Brewterializer to Speaker Jurlax for parts.", progress = "Do you bear spatial omniscience?", completion = "This will lead our way." }
WordHunterWoW_QuestEN[84024] = { title = "Clutching Control", description = "The machine breathes without life.\n\nWe must provide ours.\n\nFind a conduit for the will of the divine.", objectives = "Bring a Burin of the Candle King to Speaker Jurlax for parts.", progress = "Do you wield a tool of influence?", completion = "This will channel our predilection." }
WordHunterWoW_QuestEN[84025] = { title = "Repurposed, Restored", description = "", objectives = "The machine is complete anew, its purpose restored.\n\nYou who have staunched its suffering are charged with carrying on this purpose.\n\nMay its metal never yield." }
WordHunterWoW_QuestEN[84084] = { title = "Just a Pinch", description = "Dust is the foundation of the art of enchantment. Where novice enchanters turn up their noses at such a common material, a master understands its versatility.\n\nBring me Storm Dust. No matter our expertise, we must always return to the fundamentals.", objectives = "Collect 20 Storm Dust and deliver it to Nagad in Dornogal.", progress = "Have you collected the requisite dust?", completion = "Gratitude. It is good to see a fellow enchanter who appreciates the basics." }
WordHunterWoW_QuestEN[84085] = { title = "The Power of Potential", description = "As enchanters, we do not merely trade in runes or wands. Our true commodity is potential. We take the power of possibility and infuse it into tangible forms.\n\nFor this, Gleaming Shards are essential. I require several to continue my work.", objectives = "Collect 10 Gleaming Shards and deliver them to Nagad in Dornogal.", progress = "Where dust offers versatility, shards confer potential.", completion = "Acclamation. These will power many useful enchantments." }
WordHunterWoW_QuestEN[84086] = { title = "A Rare Necessity", description = "Occasionally, we are called upon to provide our greatest and most powerful boons. For these, I require a Refulgent Crystal.\n\nTrue, such crystals are rare, but necessary for us to reach the heights of our art. Worry not, it will not be squandered.", objectives = "Collect 1 Refulgent Crystal and deliver it to Nagad in Dornogal.", progress = "Once in hand, I will ensure it is put to worthwhile purpose.", completion = "Beautiful, yes? I'm sure you could sense the potential this might unlock." }
