WordHunterWoW_QuestEN[84140] = { title = "Can-Do Caddy", description = "So, my \"company\" was subcontracted to provide services for the golf course here.\n\nOnly, it turns out the materials we used in our patented, explosive-proof grass has drawn a swarm of coursehares. Which is inconvenient 'cause they're the only type of rodents that can eat the grass.\n\nI need a can-do caddy I can sub-subcontract out the elimination of this threat to my business. So tell me, can you?", objectives = "Eliminate 9 Coursehares.", completion = "Great job! We are gonna be rollin' in the money now. Wait... what was that sound?" }
WordHunterWoW_QuestEN[84141] = { title = "Scam Cans", description = "Look, I run a clean business here... when I'm paid to.\n\nBut, I've gotta swathe of cheatin' no gooders tryin' to plant scam cans in the holes. The things cause the balls of cheaters to get drawn into 'em, cheapenin' the game.\n\nCan't have that. \n\nGet out there, find the scam cans, and get them gone.", objectives = "Extract 4 Scam Cans.", progress = "Yeah, gotta watch out for them explodin' balls. They make for a great sport but hazard pay is a real thing.", completion = "Great work! Honestly, whoever keeps making these is on my short list of people to use a rat polymorph spell on." }
WordHunterWoW_QuestEN[84142] = { title = "The Hole Deal", description = "Okay, well now that's settled, how about you get a free go, eh?\n\nHere at...\n\n<Ripsnoodle pauses to look at notes he digs out of his pocket.> \n\nEmerald Hills Golf Course, we pride ourselves on everyone gettin' a hole-in-one!\n\nEspecially since our boomballs explode after the first swing. So make 'em count.\n\nGo take a few balls out and give the course a whack.", objectives = "Sink 4 Boomballs into the four golf holes.", progress = "The other day I saw this warlock trying to have their imp nudge a ball into the hole. Man that imp was NOT happy when it got resummoned after the explosion.\n\nThe things people sell their soul over...", completion = "That was some impressive puttin'!" }
WordHunterWoW_QuestEN[84143] = { title = "Lost and Busy", description = "Thank the Light, an adventurer!\n\nPlease, you must help me. Event coordination is a harrowing profession in the best of circumstances. I am drowning in crises!\n\nThere was a small tuskarr child in need of assistance, but I have my hands full here. I last saw her headed to Leeroy's Chicken.", objectives = "Find Maru near Leeroy's Chicken.", completion = "Are you here to halp? My brovver lost his sleufing fingy." }
WordHunterWoW_QuestEN[84144] = { title = "Tat Big Meanie", description = "Tat big meanie stole my brovver's sleufing fingy! We need to find who it was and make them give it back!\n\nI fink it was lost past da potty over there.\n\nHere, my unco has this old bird idol that can look for clues! You can borrow it 'cause you look helpy.", objectives = "Use the Idol of Ohn'ahra to search for clues near the outhouses.", progress = "Did you find any clues? We gotta find tat meanie!", completion = "You found it! You're such a good sleuf." }
WordHunterWoW_QuestEN[84214] = { title = "The Job", description = "Want money? Good at smashing stuff? Not afraid of a little morally grey wealth acquisition?\n\nWell then Entrepreneur Inc. has a gig for you!\n\nCome on down to our headquarters in the Heap and speak with Skedgit Cinderbangs for more details.", objectives = "Speak with Skedgit Cinderbangs in The Heap.", completion = "Oh wow! I was expecting a local but you will be perfect for this gig.\n\nSee... this is less of a \"gig\" and more of a \"heist.\"" }
WordHunterWoW_QuestEN[84215] = { title = "The Crew", description = "You are hired!\n\nOkay, this heist I got planned is gonna make us a lot of money, but requires a crew and a bunch of planning.\n\nI'll take care of the planning, you get the crew. \n\nWe need Goldmine. Outside of Venture Co., he's one of the fastest drivers out there. Because he's outside of Venture Co., he can't be traced back to me.\n\nWe also need a face that no bruiser can say no to. We need Handsome Crog.\n\nOh, and I need my cousin Ripsnoodle. He's not the best mage, but he's family... and my boss.", objectives = "Gather the crew.", progress = "Okay, I know some of them may not come willingly. So, we got to tell them we're gonna get lotsa money outta this heist. Like... lots of money.\n\nBecause there is. Lotsa of money. I swear.", completion = "They came? Great!\n\nI knew sending you would win them over! If they saw me, they might have remembered--\n\nWell let's not focus on the past." }
WordHunterWoW_QuestEN[84216] = { title = "The Play", description = "I'm gonna go over the details of the plan.\n\nHowever, here is the too-long-didn't-listen version: \n\nWe meet in front of the Airship Station in Bilgewater's district.\n\nHandsome Crog helps get us past the guards to the airship supply balloon there.\n\nWe steal that balloon and use it to board the airship over the arena where the safe with all that loot is.\n\nReady?", objectives = "Steal an Airship Supply Balloon.", completion = "That was the easy part." }
WordHunterWoW_QuestEN[84217] = { title = "The Highst", description = "Okay, we got this.\n\nMe, you, and loudmouth here are going to hop this service balloon and get up to that airship over the arena.\n\nThat is where they are keeping the loot. Once we get aboard, fighting space will be tight. I got us some uniforms so we'll look like people who work there but try not to start anything.\n\nReady?", objectives = "Reach the Safe.", completion = "Okay, this might not \"look\" like loot but I promise you... well... um....\n\nLook, we get out of this and I swear I will pay you back somehow." }
WordHunterWoW_QuestEN[84218] = { title = "The Getaway", description = "Okay... um... I \"may\" have lied about the loot.\n\nYou can be mad at me all you want but we need to get away now. \n\nGet in the car! We have to gun it!", objectives = "Escape in the Getaway Car.", completion = "Look, I'm sorry if you got your hopes up about the loot. I just...\n\nI couldn't get my granny out of the clutches of those Darkfuse without help. And people don't just DO things for free or because it's a good deed.\n\nSo... um... here. It's all I got and you earned it." }
WordHunterWoW_QuestEN[84220] = { title = "Passage to the Ringing Deeps", description = "", objectives = "You have our thanks for everything you did in the Isle of Dorn.\n\nCouncildward Merrix ordered the restoration of this elevator unit to further support our allies and ensure we are not fully cut off again. \n\nUse it to quickly travel back and forth to the Ringing Deeps." }
WordHunterWoW_QuestEN[84221] = { title = "Paperwork Makes the Mine Go Under", description = "Name is Marty. Marty Zoomcart. Marty Zoomcart, public defender, and agent assigned to the Gallagio's case for State of Undermine.\n\nWhat a mouthful... Just call me Marty.\n\nSo the deed holder, Rosebud Gallywix, is dead? And no one knows whodunnit. And some nobody, you, has the deed? Frankly, it's a common occurrence. Plenty of precedent. Just no time...\n\nHere's the skinny: if we don't attach some new legal owners to the deed, it's getting put up on the auction house like a pair of decade-old pants.", objectives = "Establish a plan to keep the Gallagio out of the auction house.", progress = "I don't usually like to get wrapped up in big business.\n\nBut the Gallagio, you know, it's an important establishment for the people of Undermine.", completion = "We got quite the task ahead of us.\n\nDon't be frightened though. We'll figure this one out, one step at a time." }
WordHunterWoW_QuestEN[84222] = { title = "Secure the Perimeter", description = "A veritable menagerie of dangerous creatures have attacked us since we set up our encampment.\n\nWhile my troops can manage most threats, some of the more powerful creatures may require your expertise.\n\nScour the island and eliminate any powerful entities that might jeopardize our operations here.", objectives = "Eliminate 2 rare enemies on the Siren Isle.", progress = "How goes the hunt? Is our encampment safe for now?", completion = "Fine work, <name>. I could use someone like you in my crew. It's a shame you weren't born Arathi." }
WordHunterWoW_QuestEN[84223] = { title = "Survivor's Guilt", description = "We have all suffered from Xal'atath's deeds, some more than others.\n\nI am glad to be alive, even if I now feel as old as I look.\n\n<Khadgar tries to laugh but coughs instead. He waves off your worry.>\n\nDon't worry about me. But Aethas... \n\nI've heard he went back to Dalaran's crash site. And that he hasn't slept or eaten since we arrived.\n\nHe wants my help, but I haven't been able to bring myself to visit the crash site.\n\nWill you go in my stead?", objectives = "Find Aethas Sunreaver in the Tranquil Strand.", completion = "<Aethas's posture is etched with the exhaustion of sleepless nights and days without food. His tattered clothes hang loosely on his emaciated frame, and his every movement seems fatigued.>\n\nI see. I knew Khadgar was gravely injured but... it did not occur to me that his wounds were more than physical.\n\nI respect his choice not to come here." }
WordHunterWoW_QuestEN[84224] = { title = "To Delves!", description = "There's more tae do in delves, {name}! \n\nMeet me in Dornogal. There's loads to discuss!", objectives = "Meet Brann Bronzebeard within Dornogal.", completion = "Good tae see ye! We've got plenty tae discuss." }
WordHunterWoW_QuestEN[84225] = { title = "Eggstinction", description = "We should really get outta here, but...  \n\nDo you see those eggs over there? If those monsters hatch them all, this place will be swarming with crabs when the storm clears.\n\nUgh, there's just too many to destroy by hand. We're gonna need some help!\n\nSuzie's got a lot of helpful items back at the camp... or maybe my broiler will work? I dunno, champ. Grab somethin' to get rid of those eggs!", objectives = "Eliminate 12 Egg Tenders and 12 Spawning Clutches.", progress = "Did you get rid of the eggs?", completion = "I knew you'd take care of thay creepy mess!" }
WordHunterWoW_QuestEN[84236] = { title = "The Great Detective", description = "Adventurer, thank the Light you are here. We have a missing guest.\n\nThere was a detective who was investigating the case, but I have not heard back. Could you please check in with him?", objectives = "Speak with Detective Jones.", completion = "Yes, of course you can have an autograph.\n\nHm? That's not why you're here?" }
WordHunterWoW_QuestEN[84237] = { title = "The \"Great\" Detective", description = "The missing guest? Yes, some Herrkrop fellow. Not to worry, I've already solved the case.\n\nHe probably just got lost. Relax, {class}. Enjoy the festivities! Our missing guest will show up soon enough.\n\nIf you don't believe me, go... I don't know... solve it yourself. Interrogate someone or other.", objectives = "Solve the mystery of Herrkrop's disappearance.", progress = "Have you any luck in finding our missing guest?", completion = "So that's what happened?\n\n<Alyx sighs.>\n\nThank you for your help. I will work on finding a lead to track down Scrapes.\n\nCheck back in tomorrow, if you would." }
WordHunterWoW_QuestEN[84241] = { title = "Shoreline Stand", description = "This storm will not drive me from my sacred duty. This cave must be defended at all costs!\n\nThis new crystal may still be shrouded in mystery, but we will never understand its secrets or its relation to Beledar if we allow it to fall into the grasp of these wretches who crawl from the ocean's abyss.\n\nStand with me, {name}. Together, we shall defend this shoreline to our final breath.", objectives = "Eliminate 15 Brinebound Wraith and Tide-Champion Korval.", progress = "Is the crystal safe?", completion = "Well fought. Your assistance was most welcome, <name>. The Sacred Flame guided our hand and steel.\n\n\nBut now I have the situation under control. Perhaps a few of the goblins or earthen who yet remain may need your aid?" }
WordHunterWoW_QuestEN[84242] = { title = "Diving into the Heaps", description = "Our first marks are the dynamite duo of gaming: Kayjay and Fantastic Davey.\n\nBeen a few years since I was hustling macaroons in the electro-billiards halls. I wasn't bad, but those two cleaned the house out whenever they showed.\n\nThey don't just win games either. They make them! Real artist-types, you know?\n\nBut with great gaming, comes great debt. And it's usually to Venture Co.\n\nMeet me at the Heaps. If Rosebud's death means they're outta work, I'd bet money Venture scooped 'em up again.", objectives = "Meet Marty Zoomcart at Venturewood in The Heaps.", completion = "<name>! You've got timing like a mechagnome. As in, clockwork." }
WordHunterWoW_QuestEN[84244] = { title = "Blackwater Beach Blast", description = "You've done good work with Jojo. Real good. \n\nI'll stick around, seal the deal, then meet you over at Blackwater Marina for the final signature. \n\nHad my radio turned to WGOB 101.1 FM while dropping off the fifteen landfill-scented individuals earlier. DJ B. B. Rev announced there would be a battle of the bands at the marina today. \n\nWouldn't you know it, Rosebud's Chief Executive of Entertainment is playing! The band you're looking for is the Cellar Gnomes.", objectives = "Meet Marty Zoomcart at Blackwater Marina.", completion = "I tried to speak to Gnome over here, but she's pretty distracted. \n\nYou take a crack and see how things go." }
WordHunterWoW_QuestEN[84246] = { title = "Witnessing Brilliance", description = "The time has finally come and the moment could not be more exhilarating. It's time to get to work.\n\nJoin me outside, let's observe the fruits of our labor.", objectives = "Witness Siesbarg's Ascension.", completion = "Well... that certainly did not go as planned." }
WordHunterWoW_QuestEN[84248] = { title = "A Ritual of Runes", description = "I went to investigate a cave nearby, and I came across some Bloodwake vrykul that were conjuring something... something that activated my threat mitigation protocols.\n\nI calculate that if they complete their ritual, it would be disastrous for the island.\n\n{name}, please assess the cave and stop their ritual before something terrible occurs!", objectives = "Destroy 5 Summoning Runes and eliminate Inhyldir the Cursed.", progress = "Did you disrupt the ritual?", completion = "That was a close call. We must stay alert and watch for other strange activities." }
WordHunterWoW_QuestEN[84249] = { title = "A Vat in the Pan", description = "Our next mark is Jojo Gobdre, in the Vatworks. \n\nShe was a big time chef. The real deal. And running cuisine at the Gallagio woulda meant franchise opportunities. Is there a reason she'd want Rosebud dead?\n\nEither way, we need a lead on where she's cooking these days. Luckily, I got an ol' pal who should have info. He's a little bit of a big shot for Steamwheedle, but we should be able to find him on his rooftop hideaway.\n\nWe'll meet there. Come hungry.", objectives = "Meet Marty Zoomcart in The Vatworks.", completion = "Take a seat if you want, <name>!\n\nHave you met my pal Noggy before? Me and him go way back. We were roommates back in Commerce College. \n\nGot up to some real crazy hijinks--but, uh, nothing worth bringing up now." }
WordHunterWoW_QuestEN[84252] = { title = "Peak Precision", description = "Flying? It ain't for me.\n\nSally Boltwrench wanted me to activate a bunch of survey machines to monitor the wind currents, but it's too rough up there and the heights give me the heebie jeebies. \n\nAn' I get sick every time I try.\n\nUse the Go-Pack to activate the machines for me. I'll owe ya one!", objectives = "Activate 6 Survey Machines using the Experimental Go-Pack to help reach them.", progress = "Did you switch those machines on?", completion = "Thanks for helping out Benny. You can borrow the Go-Pack anytime ya want!" }
WordHunterWoW_QuestEN[84253] = { title = "[depreciated] Blacksmithing Orders Requested", description = "", objectives = "" }
WordHunterWoW_QuestEN[84254] = { title = "Meet and Greet", description = "Greetings, salutations, and happy anniversary!\n\nI am Yllana, the conductor of this symphony of celebration. I trust you are itching for fun and entertainment? Well do not fret, for there is much to do and plenty of time to do it.\n\nI've marked your map with the locations of my gleeful greeters who will tell you all about the activities in store for you. \n\nOnce you've talked to them, return to me for a gift that will maximize your merriment. After all, what's a celebration without presents?", objectives = "Talk to the activity greeters.", progress = "It's easy to get distracted. Have you spoken with the activity greeters I told you about?", completion = "I trust you found that we offer something of interest to you while you celebrate with us.\n\nAs promised, here is your gift.\n\n<Yllana hands you a small festive bag with a notable heft to its contents. Whatever is inside feels expensive.>" }
WordHunterWoW_QuestEN[84260] = { title = "Crafting to Order", description = "Hello, greetings, and welcome to the Crafter's Enclave.\n\nAccording to Market Reeve Vokgret, we are now operating with the Artisan's Consortium to accommodate the needs of both the earthen and the outlanders.\n\nPlease speak to Ardran or Pordaz to view and place crafting orders.", objectives = "Talk to Ardran in the Crafter's Enclave.", progress = "Have you talked to Ardran?", completion = "These work orders are very useful. I am not sure how we did not think of them before the outlanders' arrival." }
WordHunterWoW_QuestEN[84274] = { title = "Crafting Orders: Blacksmithing", description = "So you are a blacksmith? You should have mentioned that earlier!\n\nLet me send you to Darean, a blacksmith of great renown, who has her shop within the Forgegrounds. I will mark it on your map. \n\nDarean has her very own Blacksmith's table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "Find Darean in the Forgegrounds and use her blacksmith's table.", progress = "Please make use of my blacksmith's table if you need it.", completion = "I am pleased that we were able to further our directives together!" }
WordHunterWoW_QuestEN[84278] = { title = "Tracking Quest", description = "Good news! We have a lead. Rexxar has agreed to help us find Scrapes. If anyone can track down that undead murderer, it's him.\n\nRexxar has followed the scent to the Borean Tundra. He left this note for you.", objectives = "Follow the note's coordinates to Rexxar's location in the Borean Tundra.", completion = "Good, you found me. Now the hunt can begin." }
WordHunterWoW_QuestEN[84279] = { title = "Crafting Orders: Jewelcrafting", description = "So you are a jewelcrafter? You should have mentioned that earlier!\n\nLet me send you to Makir, a jewelcrafter of great renown, who has a shop on the southern part of the Forgegrounds. I will mark it on your map. \n\nMakir has his very own jeweler's bench where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "Find Makir in the Forgegrounds and use his jeweler's bench.", progress = "Please make use of my jeweler's bench if you need it.", completion = "Come back soon! There's always more work to be done." }
WordHunterWoW_QuestEN[84280] = { title = "Crafting Orders: Leatherworking", description = "So you are a leatherworker? You should have mentioned that earlier!\n\nLet me send you to Marbb, a leatherworker of great renown, who has her shop on the eastern side of the Forgegrounds. I will mark it on your map. \n\nMarbb has her very own leatherworker's bench where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "Find Marbb in the Forgegrounds and use her leatherworker's bench.", progress = "Welcome! Please make use of my bench if you need it.", completion = "I am glad I could help you, <class>." }
WordHunterWoW_QuestEN[84281] = { title = "Crafting Orders: Tailoring", description = "So you are a tailor? You should have mentioned that earlier!\n\nLet me send you to Kotag, a tailor of great renown, who has their shop on the eastern side of the Forgegrounds. I will mark it on your map. \n\nKotag has their very own tailoring table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "Find Kotag in the Forgegrounds and use their tailoring table.", progress = "Please! Take a \"measure\" of my table.", completion = "Thank you for allowing me to assist you in your directive." }
WordHunterWoW_QuestEN[84285] = { title = "Crafting Orders: Engineering", description = "So... you are an engineer, hmm?\n\nYou should meet Machinist Arhdas in the Forgegrounds. I will mark his location on your map. \n\nArhdas has an engineering table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guilds. If you are lucky, you might come across an order from a renowned person which offers some extra rewards--or so I hear.", objectives = "Find Arhdas in the Forgegrounds and use his engineering table.", progress = "My tools and bench are at your disposal.", completion = "I am pleased to meet another who shares interest in my field of work." }
WordHunterWoW_QuestEN[84286] = { title = "The Finer Things", description = "", objectives = "Fetch me the insignias from our Queen's guests and comrades. These have many uses within the city, and in exchange I will make you even deadlier to our foes within.", progress = "Fetch me the insignias from our Queen's guests and comrades. These have many uses within the city, and in exchange I will make you even deadlier to our foes within.", completion = "Those loyal to me will ensure these make it to our allies outside. Very useful of you." }
WordHunterWoW_QuestEN[84287] = { title = "Crafting Orders: Inscription", description = "So you are an inscriber? I know one of the best inscribers in Dornogal.\n\nYou should look for Brrigan on the southern edge of the Forgegrounds. \n\nBrrigan owns a drafting table where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might come across an order from a renowned person that offers some extra rewards--or so I hear.", objectives = "Find Brrigan in the Forgegrounds and use her drafting table.", progress = "You are more than welcome to use my drafting table. Inscription is a rather new technique for us. There is much we can learn from your work.", completion = "I have learned much from our interaction." }
WordHunterWoW_QuestEN[84288] = { title = "Crafting Orders: Alchemy", description = "So you are an alchemist? I see.\n\nYou should visit Tarig. She's an alchemist like you. \n\nTarig has her alchemist lab bench set up in the southern part of the Forgegrounds. From there, she can help you review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you are lucky, you might receive an order from renowned persons offering extra rewards.", objectives = "Find Tarig in the Forgegrounds and use her alchemist's lab bench.", progress = "I would never miss an opportunity to share my expertise--or my lab bench!", completion = "It is always an honor to meet another alchemist." }
WordHunterWoW_QuestEN[84296] = { title = "The Trail's Gone Cold", description = "I've tracked the scent of Scrapes as far as here, but this cold air smothers our lead. I found a couple scraps of notes. Nothing useful yet, but he seems to have left a paper trail in his hurry.\n\nLook for clues that may indicate where our villain's lair is hidden. I will mark what I found on your map.\n\nTake Spirit's whistle. Call upon us when you are in need of assistance.", objectives = "Find Scrapes' hideout.", progress = "How goes the hunt?", completion = "A shapeshifter? Oh, this is very bad.\n\nWe should warn the detective. I've not seen him recently, though.\n\nCome back tomorrow. I am sure he will be back by then." }
WordHunterWoW_QuestEN[84298] = { title = "HELP WANTED: Kaja'Curiosity", description = "<This listing is new, posted by the Bilgewater Cartel.>\n\nDo you like kaja'mite? Are ya ready to get your intellectual fix under some tropical sun? Want to develop cutting-edge tools that will only explode when we tell them to? Hop on a rocket drill to the Kaja'Coast!\n\nNo prior experience required. Combat capabilities extremely welcome. Contractors are liable for their own safety. Compensation and working hours negotiable on-site. \n\nPlease seek Jazz Mokkitz on the Kaja'Coast for more information.", objectives = "Speak with Jazz Mokkitz on the Kaja'Coast.", progress = "Research takes guts, sure, but I would like to keep mine intact.", completion = "<Jazz dusts himself off, looking exhausted.>\n\nYa wouldn't believe how many times that's happened today--that was the biggest one yet, too.\n\nHope you're ready to get your hands dirty, <name>. We've got work to do!" }
WordHunterWoW_QuestEN[84299] = { title = "Pirate Plunder", description = "We got a good thing here, but these pirates are bad for business! They're stealin' all the special gems, an' they even made off with our Kaja'Cola stash!\n\nGet rid of these pirate losers and recover any of the stuff they took from us!", objectives = "Bilge Rat forces disrupted", progress = "Ya better be tellin' me them pirates is all gone!", completion = "Nice and efficient! I knew I could count on you to keep our profit margins lookin' good." }
WordHunterWoW_QuestEN[84300] = { title = "Refine, Repair, Repeat", description = "<Jazz holds up a well-polished crystal of kaja'mite.>\n\nMost materials aren't ready to use straight outta the ground--kaja'mite included. I've got a few refined crystals to tinker with, but I'll need more.\n\nI rigged up some refiners on the slope, but halfway through the cycle elementals started beatin' on 'em pretty hard. \n\nCould you see if you could get 'em goin' again? You look like you could handle those angry rocks, and my wife likes it when I come home without injuries.", objectives = "Repair 6 broken Kaja'mite Refiners on the Kaja Coast.", completion = "I wasn't sure how those refiners would hold up under stress. I'm glad you fixed 'em!\n\n<Jazz casually flips a small kaja'mite crystal between his fingers.>\n\nDo you think I could patent and license the schematics? The royalties could keep me outta the field if I charge enough." }
WordHunterWoW_QuestEN[84301] = { title = "Mineral Madness", description = "With all these elementals wreakin' havoc, it's impossible to work out here! How are we supposed to gather raw material when they're swingin' at us with the stuff?\n\n<Jazz stops, eyes lighting up.>\n\n{name}, those elementals ARE our raw material. Smashin' 'em up is our best bet--though, you'll have to do that for me. \n\nNow, keep it movin'! Time is money, and I ain't one to waste perfectly good research funding.", objectives = "Clear out aggressive Kaja'mite elementals and collect 12 Raw Kaja'mite Chunks from them.", progress = "Who knew this place was so elementally active? No wonder the Darkfuse needed all hands on deck out here.", completion = "I'm gonna have to get some shamans out here to calm the rest of those rocks down. \n\nI don't blame 'em for being mad and all, but the mountain's already been blown to bits. Not much we can do about that." }
WordHunterWoW_QuestEN[84302] = { title = "Creative Iteration", description = "Alright, {name}, time for this to get serious. You got the crystals, and I've got our parts to work with!\n\nKaja'mite is good for containin' volatile energy. I think we can do better than Darkfuse weaponry, but first, we need a proof of concept.\n\nI've got this old, glitchy, junk shrink ray. The kaja'mite should stabilize it. If it does, we've got a potential breakthrough!\n\nI need an extra set of hands to tinker on this thing. Just follow my instructions and you'll stay in one piece. Probably.", objectives = "Help Jazz tinker with his shrink ray and kaja'mite.", completion = "Well, we're both still intact. The shrink ray isn't destroyed. I'm calling this a wild success!\n\nImagine it, <name>, this shrink ray could help pack supplies more efficiently into vehicles. We could transport more people in the same amount of space as before! I can't wait to tell my wife.\n\n\n\nSorry, I got carried away. Ya did great, <name>." }
WordHunterWoW_QuestEN[84303] = { title = "Experimental Application", description = "<Jazz shoves the shrink ray into your hands.>\n\nOnly thing left to do is test the prototype, {name}. Try using it on the elementals! If it can work on those, it'll work on anything, probably. \n\nDon't expect the effects to last, though. It's only a first iteration! And keep contained to the mines. Just in case we need to bury any problems.  \n\nOh, don't give me that look. I built this originally to make spiders easier for my wife to handle. I promise, there's at least ONE functional failsafe.", objectives = "Test the Kaja'Containment Device on 8 Kaja'mite Crawlers in the Lucky Break Mines.", completion = "I knew it'd be fine! Perfectly safe to handle. \n \n<Jazz coughs.>\n \nI'll name you on whatever patent I file, promise." }
WordHunterWoW_QuestEN[84304] = { title = "A Gem-Splitting Headache", description = "Hey, {name}, I'm not usually one for revenge, but I've got an idea.\n\nThat big guy who tossed us around ran up this way. I'll bet you good money it's in the mines somewhere, and I bet we could get a giant sample off its body. That'd set me up real nice for future tinkering.\n\nBesides, taking it out means it won't come back, and I'd like to finish this gig intact. I've got bills to pay, and kids to feed! \n\nTry the shrink ray on that hunk o' rock. Show it who's boss! For science, of course.", objectives = "Use the prototype to weaken & kill the Raging Kaja'mite Gemsplitter.", progress = "Good to see you in one piece. How'd it go?", completion = "I owe ya, buddy, big time. We're definitely in business if our lil' prototype took that hulking thing down a couple notches!\n\nI'm gonna have to get a bigger team out here to keep tinkering. There's definitely more to kaja'mite than weapons or soft drinks, I'll tell ya what." }
WordHunterWoW_QuestEN[84305] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across Khaz Algar to cover the tab!" }
WordHunterWoW_QuestEN[84306] = { title = "Bar Tab Barrel", description = "", objectives = "Donate to taverns across Khaz Algar to cover the tab!" }
