WordHunterWoW_QuestEN[84334] = { title = "Warn the Detective", description = "Welcome back, {name}.\n\nI saw the detective headed west. Hurry up and warn him before the shapeshifter comes for him too!", objectives = "Warn Detective Jones about the shapeshifter.", completion = "A shapeshifter? Hah! Poppycock!" }
WordHunterWoW_QuestEN[84336] = { title = "Spot the Difference", description = "Look, I'm the real detective. You believe me, right?\n\nI know--ask me anything. The good people here will be able to corroborate my story and we'll prove that I'm me.", objectives = "Solve the case of the shapeshifting demon.", progress = "This is preposterous...", completion = "Thank you so much for solving the case, <name>!\n\nHopefully, this event will be calmer now." }
WordHunterWoW_QuestEN[84352] = { title = "No More Walkin' Here", description = "We gotta do something about how long it's taking to get you around. Luckily, I know just the gal. Go meet Nanny Talullah at the Caddy Shack and see if she'll lend you some wheels.", objectives = "Meet Nanny Talullah on the third floor at the Caddy Shack.", completion = "You need a car? Of course we can get you a car! We have so many cars! Here, I even have some spare keys right here!" }
WordHunterWoW_QuestEN[84363] = { title = "Tweasure Hunt", description = "I know! We could use da stick to look for tweasures!\n\nYou and Enzo go check da other ruins. Find somefing really cool!\n\nI'll meet you back at da parties.", objectives = "Use the Torch of Pyrreth to search for treasure around the ruins of Tanaris.", progress = "Did you find any tweasure?", completion = "Wow, now this is real tweasure!" }
WordHunterWoW_QuestEN[84365] = { title = "Something on the Horizon", description = "Brann's scouts have reported sightings of reinforcements approaching the shores of Khaz Algar.\n\nHe's put out the call for adventurers to join him in Dornogal.", objectives = "Speak to Brann Bronzebeard in Dornogal.", completion = "I've 'eard reports o' reinforcements approaching the isle. Ye know Khaz Algar inside and out--they'll need yer expertise." }
WordHunterWoW_QuestEN[84367] = { title = "A Time to Come Together", description = "We ought tae be getting a whole fleet o' reinforcements soon. Just in time, I hear Alleria and Anduin are back in Dornogal.\n\nIf I know Moira, she'll already be workin' with 'em tae figure out our next move. She knows how tae lead like a gryphon knows how tae fly. Best go find her before she comes looking for ye.", objectives = "Speak to Moira Thaurissan in Dornogal.", completion = "Perfect timing. I've got good news for the first time since we crashed here." }
WordHunterWoW_QuestEN[84370] = { title = "The Key to Success", description = "<A Cipher Key? Elise Starseeker might know what to do with this.>", objectives = "Bring the Archaic Cipher Key to Elise Starseeker in Dornogal.", progress = "This map makes no sense... Champion! Good tidings I hope?", completion = "Astounding! This is what I've been missing. \n\nThe map Finley found is a cipher. But this key, it's incomplete... If you find any more out there, please bring them to me. I will decipher this map, or my name isn't Elise Starseeker." }
WordHunterWoW_QuestEN[84371] = { title = "Lorewalking: The Blade and the High Priest", description = "Xal'atath, the Harbinger of Void, is a cunning and dangerous foe. She has been careful to make her presence known only to a precious few.\n\nWe first learned of her during the Legion's third invasion of Azeroth, but whispers say she has been around since long, long before that. \n\nThis is a story of power, darkness, and deceit. Join me and I will tell you the tale of Xal'atath's mysterious past.", objectives = "Follow Cho's guidance to learn the story of Xal'alath's past.", completion = "Xal'atath was a powerful weapon and a... talkative presence." }
WordHunterWoW_QuestEN[84376] = { title = "Property Devalued", description = "<You come across a wanted poster that has been nailed on top of a for rent sign.>\n\nWANTED: Seeking able-bodied adventurer to work as security for local apartment complex.\n\nMust be capable of not dying.\n\nREWARD: Free room and board in exchange for services rendered.\n\nInterested parties should inquire upstairs at the nearby Barrelbottom Apartments for further details.", objectives = "Visit Barrelbottom Apartments and inquire about a room to rent.", progress = "That Moz is driving me crazy! Maybe you can talk some sense into him.", completion = "I didn't think anyone would actually show up. You here about the free room?\n\nYou didn't say nothin' to Barrelbottom, didja?" }
WordHunterWoW_QuestEN[84378] = { title = "Renter's Insurance", description = "It's bad enough that the old skinflint landlord is letting this place slowly fall apart, but now we got even bigger problems. \n\nRecently, those would-be gangsters up the road, the Underriders, went from petty theft and noise complaints to being a heavily armed menace. They've started trashing the place, and even attackin' us directly!\n\nWhat's worse, anyone who can't afford to move out are evicted for the damage those thugs caused instead.\n\nYou keep us safe, you can crash here free of charge.", objectives = "Kill 12 Underrider biker gang members.", progress = "I can't keep up with all these repairs. Someone needs to do something about those bikers!", completion = "You're back.\n\n <Keara winces from her injuries.>\n\nYour timing coulda been better." }
WordHunterWoW_QuestEN[84379] = { title = "Tenant Trouble", description = "<Gabi waves you over urgently.\n\nThe small goblin wrings her hands together nervously trying to find the words to explain her concern.>\n\nSome goblins aren't moving out--they're being kidnapped. I know it. \n\nMy friends wouldn't have moved. They wouldn't.\n\n<Gabi looks up at you imploringly with misty eyes.>\n\nPlease help, {class}. Please?", objectives = "Rescue 8 Captured Tenants.", completion = "Everyone rescued. Only to be attacked again.\n\nWe can't let this stand, <name>." }
WordHunterWoW_QuestEN[84380] = { title = "Weapons Cash", description = "<Inside the weapons crate you find a crumpled note written to the Underriders.>\n\nGood to see you're putting your new toys to good use. These little squatters are leaving in droves thanks to you guys!\n\nKeep up the good work and there's more where this came from. Just try not to burn the whole place down. Can't rent out an empty lot, haha!\n\nSigned,\nM.B.B.", objectives = "Destroy Underrider equipment throughout the compound.", progress = "Find something?", completion = "A letter for the Underriders? I think I know this signature...\n\nIt's that wormy landlord, Moz Barrelbottom!" }
WordHunterWoW_QuestEN[84381] = { title = "Renegotiations", description = "That settles it! I think we both know who's responsible for this mess. It's that bastard landlord, Moz Barrelbottom!\n\nSoon as the Underriders were dealt with, he sent his goon Jarvis on a rampage. Looks like if he can't scare us out, he's going to force us out!\n\n<Keara spits on the ground in disgust.>\n\nHe won't scare us so easily.\n\nYou're pretty tough, {name}. Moz's office is just across the street. Go show him he's messin' with the wrong goblins!", objectives = "Defeat Jarvis Bonebreaker and collect the Barrelbottom Deed from Moz Barrelbottom in his third floor office across the street.", progress = "We'll be fine here. You just go deal with Moz!", completion = "Hah! That will show the old skinflint who's in charge. And with this deed, he can't threaten us with nothin'!\n\nYou did good. I think you've earned that free room alright." }
WordHunterWoW_QuestEN[84392] = { title = "Hungry in Hollow", description = "Hey. You looking for a great meal?\n\nWilling to wade through the mud to get it?\n\nGo see Dolena. She'll sort you out. Don't bother trying to convince her to leave that hollow, though. Believe me--we've all tried. Why someone would leave the safety of the light for that...\n\nShe seems to do alright, though.", objectives = "Seek out Dolena in Growling Hollow", completion = "Ah, another one. You here on purpose?" }
WordHunterWoW_QuestEN[84393] = { title = "Da Stick of Revealing", description = "Awwight, it's time to try da Stick of Reveawing!\n\nFowwow me.", objectives = "Follow Maru, then use the Torch of Pyrreth on brazier outside the Ruins of Uldum.", progress = "A good sleuf knows how to use all da tools.", completion = "Sooo coooool!\n\n<Maru and Enzo exchange looks, eyebrow wiggles, and nods.>\n\nWe fink you should hold onto the tweasure-finding stick. You're a real good sleuf and maybe you can find more tweasures for us!" }
WordHunterWoW_QuestEN[84403] = { title = "A Small Bundle of Goods", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[84404] = { title = "A Small Bundle of Goods", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[84409] = { title = "For the Valorous", description = "", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude." }
WordHunterWoW_QuestEN[84419] = { title = "To da Ruins!", description = "You found my brovver's sleufing fingy!\n\n<Maru holds it up with reverence.>\n\nDa Stick of Reveawing! Dis fing can turn on da lights, melt stuff, and even unlock ANSHENT TWEASURE. And all you gotta do is hold it up!\n\nWe wuz gonna try it on dis fing outside the Wuins of Uldum. Wanna come?", objectives = "Meet Maru and Enzo outside the Ruins of Uldum.", completion = "Weady for adventure?" }
WordHunterWoW_QuestEN[84423] = { title = "Shaking the Dust Off", description = "Wow, you look really strong! Would you be able to help me?\n\nMy parents were killed by the mean kobyss. When I came here, I left my favorite, most well loved teddy ever behind. \n\nCould you go get it for me?", objectives = "Retrieve Alyza's Much Loved Teddy Bear from the Hungering Pool in Hallowfall.", completion = "Welcome back to the land of the living, <class>. \n\nThere is much for you to catch up on." }
WordHunterWoW_QuestEN[84424] = { title = "Forward, to Adventure!", description = "We are free, {class}. Free to do whatever it is we wish.\n\nThrough the portal lies the rest of your life.\n\nA member of the bronze dragonflight will help you on your journey.", objectives = "Use the portal in the War Creche to get to Chromie.", completion = "Time to catch you up, <name>!" }
WordHunterWoW_QuestEN[84426] = { title = "Waterlogged Celebration Crate", description = "<The crate is soaking wet, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", objectives = "Return the Waterlogged Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84429] = { title = "Construct Containment", description = "", objectives = "" }
WordHunterWoW_QuestEN[84430] = { title = "Crystal Crusade", description = "I swore my life to protect Beledar... and now a new star sings to us from the sea.\n\nI know not what this means for the Arathi, but I do know that letting these foul creatures of the deep snatch up pieces of it is likely to lead to ill. \n\nKill them with extreme prejudice and recover any pieces of the crystal in their possession.", objectives = "Recover 10 Crystal Fragments and 30 Crystal Chunks from the Naga forces.", progress = "Have you recovered the Crystal Fragments?", completion = "May Beledar's kin prosper now." }
WordHunterWoW_QuestEN[84432] = { title = "Longship Landing", description = "These Bloodwake vrykul have no regard for us or our research. Even when we tried to share our discoveries with them, we were attacked! \n\nThey do not care that we mean the isle no harm--they want us to leave.\n\nBut we cannot leave now. There is so much more to discover! Someone must show them that we're not going to go just yet and that they should leave us alone.\n\nWe need to show them we will fight back.", objectives = "Eliminate 15 Bloodwake Vrykul.", progress = "Did you convince them to leave us alone yet?", completion = "I am not one to promote violence as a solution, but sometimes force is the only option." }
WordHunterWoW_QuestEN[84435] = { title = "Nola's Last Wish", description = "Greetings, {name}! Could you check in with Lashk?\n\nHe seemed upset about something.", objectives = "Solve Lashk's mystery.", progress = "The stories Nola could tell...", completion = "It is comforting to hear that she will rest well now.\n\nI will be telling this story for many years, <name>. Thank you." }
WordHunterWoW_QuestEN[84438] = { title = "Easy Win", description = "", objectives = "Seems fortune favors the bold--and the skilled at cards. Our friend Millhouse wasn't exactly happy to part ways with this scroll, or all of the rest of his belongings for that matter.\n\nTake it, <race>. It's the least I can do for everything you did for the Dalaran survivors." }
WordHunterWoW_QuestEN[84439] = { title = "Kaja'Conclusions", description = "You've really helped me out here, {name}, but I need one more teeny tiny favor from you. \n\n<Jazz hands over an envelope stuffed to the brim with schematics and paper reports.>\n\nCould ya get this to my contract agent, Kory Hoxx? He'll get it to HQ. You'll probably catch him in the Incontinental Hotel, putting up more gig sheets.", objectives = "Deliver Jazz's Report to Kory Hoxx in the Incontinental Hotel.", progress = "Can't ya see I'm a little busy here? Recruitment's hard work, ya know!", completion = "Oh, Jazz has an update? Well why didn't ya say so!\n\n<Kory snatches the envelope, tearing it open and looking at the report.>\n\nHe needs HOW MANY people?!" }
WordHunterWoW_QuestEN[84442] = { title = "Invitation to the Spirit Festival", description = "Greetings, {name}. It's been too long since I've returned to Shen-zin Su. I miss him... and I miss everyone that calls him home as well.\n\nWould you like to attend the Spirit Festival? Li Li asked for you specifically.\n\nI seem to remember she fought with her father during one year's festival. However, he's the one who extended the invitation to her this time. Perhaps he just wants to see her return home. \n\nJi will be coming along too! Join us!", objectives = "Meet Aysa Cloudsinger in Stormwind near the hot air balloon.", completion = "You made it!\n\nAs for getting to the Wandering Isle... are you ready for a hot air balloon ride?" }
WordHunterWoW_QuestEN[84444] = { title = "Invitation to the Spirit Festival", description = "Hey, {name}.  It's been a while since I've been back home, to Shen-zin Su. Remember that old turtle? Still wandering the Great Sea...\n\nLi Li asked me to pass along an invitation to the Spirit Festival. It's funny, I remember Li Li and her father had a huge fight about it one year.\n\nBut guess who the original invite's from? Her father! I guess they get along better these days. Or maybe he just wants her to come home. Who knows?\n\nAysa's coming along too. Will you join us?", objectives = "Meet Ji Firepaw in Orgrimmar by the hot air balloon.", completion = "You made it!\n\nBet you were wondering how we'd get to the isle... well, are you ready for a hot air balloon ride?" }
WordHunterWoW_QuestEN[84446] = { title = "Renown of Khaz Algar", description = "There is still much we still need tae do to aid Khaz Algar.\n\nBut I dunnae know much about this land past the realms of earthen.\n\nI'll have to refer ye to Faerin Lothar tae see what Hallowfall may need.\n\nTalk to her an' see if she needs any help. Ye already are acquainted, aren't ye?", objectives = "Speak with Faerin Lothar in Dornogal.", completion = "Good to see you again, <name>. \n\nWe have a lot of work to do." }
WordHunterWoW_QuestEN[84451] = { title = "The Wanderers", description = "{name}! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub!\n\nI suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us.\n\n<Li Li smiles--half anxious, half something else.>\n\nLet's enjoy this together.", objectives = "Ride the hot air balloon to the Wandering Isle.", completion = "Oh, it's so good to see dad!\n\nBut... where are all the festivities? Why does he look so worried?" }
WordHunterWoW_QuestEN[84452] = { title = "The Wanderers", description = "{name}! I'm so happy you're here. My dad asked me to invite all my friends to the Spirit Festival. It feels a little strange that he cares about it this year. We haven't celebrated it since I was a cub!\n\nI suppose we should go, huh? See dad, see home? When's the last time you've been back, anyway? I finally have some free time. And... I'm really glad you're going with us.\n\n<Li Li smiles--half anxious, half something else.>\n\nLet's enjoy this together.", objectives = "Ride the hot air balloon to the Wandering Isle.", completion = "Oh, it's so good to see dad!\n\nBut... where are all the festivities? Why does he look so worried?" }
WordHunterWoW_QuestEN[84453] = { title = "To Dai-Lo Farmstead", description = "My brother Chon Po has been trying to rally everyone. He sent out handwritten invitations to each village. Can you believe that? He's a brewmaster--he should've sent brew!\n\nDai-Lo Farmstead was like a second home to us. Chon Po and I spent half our childhood there, helping with the harvests. It's where we made our very first drinks.\n\nLet's give the Dai-Lo villagers a big hit of nostalgia, and something new--as a teaser for what's to come at the festival.", objectives = "Journey to Dai-Lo Farmstead in the Wandering Isle.", completion = "Good news! Some were preparing to go to the festival, so we don't have to convince the whole village!\n\nBad news--there's a big problem in the fields. The virmen are back at it again." }
WordHunterWoW_QuestEN[84454] = { title = "Tide of Virmen", description = "I was hoping for a heartier welcome when we arrived. Unfortunately, many of the villagers are occupied in the farmland. The harvest is in full swing, and so are the virmen.\n\nWe've fought these pests all my life. I don't know how they keep coming!\n\nChon Po and I are busy setting up the drink tasting. Can you take care of the problems in the field?", objectives = "Take back The Rows by killing virmen, harvesting produce, and helping farmers.", progress = "The Rows sound a little busy!", completion = "No doubt the virmen will be back, but now we can celebrate.\n\nWe'll bring some of the fresh harvest to the festival." }
WordHunterWoW_QuestEN[84455] = { title = "Big Bertha", description = "I love Chen's idea to entice the villagers with a brew tasting. I'm surprised I didn't think of it first!\n\nMy friends were hoping to take a large portion of the harvest to the festival. But Big Bertha is missing! We need her if we ever hope to haul back all the food and drink in time.\n\nThe villagers say she suddenly broke from her cart and disappeared underground.\n\nI'm worried. She may be large, but she has a soft heart. Can you go find her?", objectives = "Find and save Big Bertha in The Rows.", completion = "If push came to shove, I'm sure Big Bertha would've trampled that virmen. But I'm glad you saved her the stress." }
WordHunterWoW_QuestEN[84456] = { title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody has shown up.\n\nThat's very strange. They're usually the ones most excited about the Spirit Festival. They'll use any excuse to make and set off their fireworks!\n\nSomething must have happened. Let's go see.", objectives = "Journey to Morning Breeze Village in the Wandering Isle.", completion = "Oh no! Their fireworks have gone missing. No wonder!" }
WordHunterWoW_QuestEN[84457] = { title = "To Morning Breeze", description = "Chon Po said he sent several invitations to the villagers of Morning Breeze, but nobody showed up.\n\nThat's odd. They're usually the ones most excited about the Spirit Festival. Any excuse to make and set off their fireworks!\n\nSomething must be up. Let's find out.", objectives = "Journey to Morning Breeze Village in The Wandering Isle.", completion = "Well that explains that--their fireworks are missing!" }
WordHunterWoW_QuestEN[84458] = { title = "Devil's in the Details", description = "Let's investigate the village for signs of mischief. I don't believe that the fireworks were simply misplaced. Shisai is a watchful pandaren and this is his big contribution to the festival.\n\nThe theft must have happened recently. Someone must have seen something.", objectives = "Search for 3 clues about the missing fireworks in Morning Breeze Village.", completion = "Well, the case is more cut and dry than I thought. Everything points toward the hozen!" }
WordHunterWoW_QuestEN[84459] = { title = "Scamps Ain't It!", description = "Shisai said the fireworks were in a barrel... \n\n<Ji paws at his face.> \n\nAnd... he likely put them in the wrong barrel. Amidst the festival's extensive preparation, it'd be a miracle if none of the goods were crossed.\n\nWell then, let's search the barrels! It won't take long.", objectives = "Search 8 Wooden Barrels in Morning Breeze Village.", progress = "There sure are a lot of barrels...", completion = "Hmm... no fireworks in these barrels. There are more barrels in town... but what are the chances?" }
WordHunterWoW_QuestEN[84460] = { title = "Red Hand or Herring?", description = "Every clue points at the hozen stealing the fireworks! It is as Ji said. They've done it before--they'll do it again.\n\nLet us confront them right now.", objectives = "Confront Huk Huk, the hozen chieftain, in Fe-Feng Village.", progress = "It can only be the hozen who have done it!", completion = "Oh! \n\n<Aysa blushes.>\n\nWell, this is certainly unexpected. I am pleasantly surprised." }
WordHunterWoW_QuestEN[84461] = { title = "It's Not a Spirit Festival Without Spirits", description = "<The crane bears a letter. It's from Li Li.>\n\nSomething's wrong at the Temple of Five Dawns. I need your help. Please come as soon as you can!", objectives = "Meet Li Li Stormstout in the Temple of Five Dawns.", completion = "I'm glad you came quickly, <name>! I can always rely on Mr. Crane to deliver messages as fast as the wind.\n\nBut speaking of the wind..." }
WordHunterWoW_QuestEN[84462] = { title = "Patterns in Static", description = "I can't find any of the spirits in the temple. How are we going to have a Spirit Festival with no spirits?\n\nToday is a celebration for all four of the elemental spirits, but perhaps they also think today is just another day. We need to find them and tell them otherwise!\n\nLook, is this the wind spirit's trail? Maybe it will lead us to Dafeng... who can lead us to the others.", objectives = "Collect 30 Remnants of Wind and use their power to find Dafeng in the Temple of Five Dawns.", progress = "<Dafeng floats, waiting for something.>", completion = "<Dafeng spins in a circle, delighted, but quickly comes to a halt. He seems to be looking for the other spirits. Perhaps he needs help?>" }
WordHunterWoW_QuestEN[84463] = { title = "Codependency", description = "Ah, {name}! Are you and Li Li back for the festival? My heart warms to see your return.\n\nNot all is well today, though. The spirits seem restless and have scattered. Dafeng and I have been looking for them everywhere.\n\nWell, I found Shu and Wuguo. Unfortunately, I found them... together. They got into a fight, and do you know what happens when you mix water and earth? A mud monster, that's what!\n\nWe must break them up. Fortunately, that's something I know plenty about.", objectives = "Free Shu and Wuguo by defeating the Mud Amalgam in Pei-Wu Forest.", progress = "Did you and Jojo find the rest of the spirits? Dafeng led me here... but I'm not sure why yet.", completion = "You and Jojo did it! Thank you.\n\nNow, Huo is the last missing spirit. Why did Dafeng lead me to a pool? Water and fire don't mix..." }
WordHunterWoW_QuestEN[84464] = { title = "Lost My Spark", description = "Dafeng led me here, but then he flew away. I think he senses Huo, the spirit of fire, nearby.\n\nWhy are all the spirits in such a state today? The festival is for them, after all. I was anxious about returning home, but didn't know why. The spirits have always reflected the truth about the isle and its pandaren. If they're agitated, something must be wrong... or something has to change.\n\n<Li Li sighs and shakes her head.>\n\nFor now, we need to find Huo, and quickly. This steam trail must be his.", objectives = "Follow the trail of steam to find Huo, the Ancient Spirit of Fire.", progress = "We need to find Huo and help him!", completion = "Huo's back to his old self!\n\nI feared the worst when I saw that Huo had come here. I hope he knows that we remembered him, and that we would never abandon him.\n\nThank you, <name>. We did it, for every spirit." }
WordHunterWoW_QuestEN[84465] = { title = "Of Water and Blood", description = "Mr. Crane told me about your success in the other villages. Now that we've found the spirits, we can begin the festivities.\n\nBut before we go, {name}... will you come with me to the Wood of Staves? I'd love your help gathering flowers while we're there. I hear the woods are still crawling with scamps.\n\nIt's to see my... family. I'd like to pay them a visit, before the festival. Just for a moment.\n\nIt's been too long.", objectives = "Gather 10 Blue Poppies and slay 10 Thornbranch Scamps in the Wood of Staves.", progress = "This place brings back so many memories.", completion = "Honestly, I missed dad more than I wanted to admit. It's been good to see him again." }
WordHunterWoW_QuestEN[84466] = { title = "Thousands of Years Ago...", description = "The world is changing as we speak. We've been through so much.\n\nBut it's like time skips this isle. Everything is exactly as I remembered... is that a good thing, {name}? Is it even possible?\n\nEven the ancients grow older. Shen-zin Su must be looking for something more, after all this time. Perhaps the spirits don't want this to just be another year.\n\nAnyway, we should head back to Wu-song Village before they start the festival without us. Let's not keep everyone waiting.", objectives = "Return to Wu-Song Village to begin the Spirit Festival.", completion = "<Li Li beams, unable to contain her excitement.> \n\nLorewalker Cho is here! So is Yu'lon!\n\nSo this means that Shen-zi Su actually returned to the waters of Pandaria? I can't believe it!" }
WordHunterWoW_QuestEN[84467] = { title = "This Was Home", description = "{name}!\n\nI cannot believe my eyes--Shen-zin Su, the Wandering Isle? Here?\n\nAnd his return to the shores of his birth coincided with the annual Spirit Festival? This cannot be a coincidence. You must have restored some sense of purpose and peace to him--and within everyone here as well.\n\nI have much to explore here. But first, we must celebrate this reunion! My dear friends!", objectives = "Celebrate the Spirit Festival in Wu-Song Village.", progress = "I never thought I would witness Shen-zin Su's return to Pandaria in my lifetime.", completion = "I barely have the words to express what this means to me, <name>--what it means to us all. Thank you." }
WordHunterWoW_QuestEN[84468] = { title = "Brew You One Better", description = "Ready for the brew tasting? We've caught the attention of a small crowd already.\n\nI've got something that will send their heads spinning--ingredients they've never even heard of before, and impeccable technique...\n\n<With a flourish, Chen places a ribbon of cucumber on a drink.>", objectives = "Distribute Chen and Chon's homebrews to the villagers.", progress = "<Chen quietly observes the villagers' reactions.>", completion = "<Chen is actually smiling, despite the villagers' tentative reactions.>\n\nNew tastes take time to appreciate. The citrus will rest in their minds--what fruit is it exactly? A sweet lemon? Or a sour melon? It is our nature to seek to understand the unfamiliar.\n\nThey'll be back for more--I know it. After all, the Spirit Festival is about celebrating new adventures!" }
WordHunterWoW_QuestEN[84469] = { title = "Battle Pet Bingo", description = "Well, hi there! The grand master pet tamers from Pandaria have posted a challenge to find certain battle pets on this fancy-lookin' bingo card. \n\nAll we have to do is find the pet that goes to the riddle and note it down on our bingo cards, but I'm having a hard time with the last two. It's quite easy to spot the normal pets, but these bingo cards require us to find special versions of the creatures.\n\nHmm... They didn't say anything in the rules about getting outside help. Care to help a friend out?", objectives = "Find the battle pets based on the riddles.", progress = "Have you any luck in finding the battle pets?", completion = "Hey, thanks a bunch friend!\n\nBINGO!" }
WordHunterWoW_QuestEN[84470] = { title = "Dirt-Caked Celebration Crate", description = "<Though unearthed and dusted off, this crate still smells of death. Regardless, Alyx would likely appreciate the supplies returned.>", objectives = "Return the Dirt-Caked Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84485] = { title = "Renowned with the Tazaveshi Brokers", description = "Well hey there!\n\nWe want to thank you for all your help. How about you meet me in Loamm, so we get you something nice?\n\nKeep up the good work!You will receive:", objectives = "Speak with Mimuup  in Loamm.Well hey there!\n\nWe want to thank you for all your help. How about you meet me in Loamm, so we get you something nice?\n\nKeep up the good work!You will receive:" }
WordHunterWoW_QuestEN[84489] = { title = "Shopping Squee!", description = "Now that you have an idea of some of the main attractions, let's talk shopping.\n\nThe main pavilion here contains just a few of places where you can look for amazing new purchases. Do a loop and talk to the shopkeeps to see what they have to offer.\n\nOnce you are done, come back and let me know if anything caught your fancy.\n\nTa-ta!", objectives = "Talk to the shopkeeps.", progress = "Don't be shy, you're allowed to browse. Go ahead and have a look at the wares for sale and then come back when you're done.", completion = "I hope you found something to your liking, or at the very least had fun browsing.\n\nYou know your way around, so now I turn you loose to go forth and enjoy yourself. This anniversary is for you, after all." }
WordHunterWoW_QuestEN[84490] = { title = "The Great Vault", description = "Many of Dornogal's systems have been dormant for millennia and are now back online. One that you might find useful, {race}, is the Great Vault.\n\nOnce, this cache of armor and weapons would have supported the earthen in their Oathsworn duty to protect Dornogal. Now it is extended to you with the expectation that you use what you find there to aid others along your quest.\n\nThe Vault is housed here in Dornogal within the Council's Treasury. The Councilward has granted you full access to its contents.", objectives = "Obtain a piece of loot from the Great Vault.", progress = "The vault is yours to peruse, <name>.", completion = "So you've found some beneficial equipment within the vault, have you?\n\nGood. There are many more pieces stored within. Take a look regularly. You never know what you might find." }
WordHunterWoW_QuestEN[84506] = { title = "Pet Pursuit", description = "Hello, adventurer!\n\nI spotted a group of battle pet tamers who were going on about a bingo game. Jepetto Joybuzz was among them and seemed to be in some distress over his progress.\n\nWhy don't you see if he could use some help?", objectives = "Find Jepetto Joybuzz near the pet playground.", completion = "Oh, are you looking to help me track down some rare critters?" }
WordHunterWoW_QuestEN[84519] = { title = "Ancient Curiosity: Combat", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip the Unbreakable Iron Idol to Brann Bronzebeard." }
WordHunterWoW_QuestEN[84520] = { title = "Ancient Curiosity: Utility", description = "<You hold the relic and discover a shimmering glow emanating from it. This looks important. The Explorers' League would be interested in this.>", objectives = "Use and equip Streamlined Relic to Brann Bronzebeard." }
WordHunterWoW_QuestEN[84521] = { title = "Thoughtful Pursuits", description = "Maru has been such a good junior sleuth that it's time to reward her with a Thinking Cap of her own!\n\nI can't just hand one over to her, though, so I've buried the parts she'll need to make one herself. I've hidden the coordinates for each part in riddles. Figure out the riddles to find the hiding places!\n\nWould you escort her to make sure she doesn't run into trouble? You can use my Thinking Cap to help. Also, I'll give you a special clue book that will reveal riddles as you progress.", objectives = "Escort Maru through Benatauk's  puzzle.", progress = "How's it coming along? Maru isn't giving you any trouble, is she?", completion = "You did it! And look at that big toothy grin on Maru's face. Thank you so much for helping." }
WordHunterWoW_QuestEN[84542] = { title = "A Radiant Echo", description = "<Within your hand, you hold a small Azerite sphere. Its light is steady and bright, but the sound it emits is plaintive and longing. It tugs at you, ever so slightly.>", objectives = "Bring the Radiant Echo to a Worldsoul Memory, then release it.", completion = "<As you release the Radiant Echo, visions of the past materialize before your eyes. The Worldsoul herself is sharing her memories with you.>" }
WordHunterWoW_QuestEN[84547] = { title = "Redemption Guaranteed", description = "<Even an empty Kaja'Cola can still has value. Perhaps Blinky Greasefingers might want it.>", objectives = "Deliver the Empty Kaja'Cola to Blinky Greasefingers at Flotsam Shoal.\n\nProvided item:", completion = "I don't recycle these. I just refill them with off-brand cola.\n\nNobody can tell the difference, I promise!" }
WordHunterWoW_QuestEN[84559] = { title = "Carved Crests", description = "", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude." }
WordHunterWoW_QuestEN[84563] = { title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", objectives = "Speak with Maru.", completion = "Yaay you're here to halp!" }
