WordHunterWoW_QuestEN[84583] = { title = "A Hozen On My Back", description = "Hello, {name}. I don't suppose I could trouble you again? A strange couple has been causing trouble near the edge of the petting area.\n\nPerhaps you could convince the hozen to stop shouting at our guests.", objectives = "Confront the boisterous hozen.", completion = "Riko's had it up to here with these horkin' wikkets!\n\nWhat the ook do you want?" }
WordHunterWoW_QuestEN[84588] = { title = "Operation Toy Rescue", description = "Nooo! A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you halp my friend Yennu find his stolen toy? You'll find him on the Dragon Isles.", objectives = "Find the missing toys.", progress = "Did you find da toys?", completion = "Wow you're an expert toy rescuer! Who do you fink stole da toys in the first place?\n\nWe should go through da clues you found and see if we can figure out the culprit! Come back tomorrow and we can go over da evidence." }
WordHunterWoW_QuestEN[84595] = { title = "The Case of the Fur-Getting Wikket", description = "Riko has had enough of these blikkety tik-digglers! All Kiryn wants is to be a furry-haver, and these mankers won't give any!\n\nKiryn says Riko needs to stop jabberings. Says taking their furries is \"stealing.\"\n\nYou a helpful wikket? Find Kiryn a furry friend! Better take notes so wikket don't get stuck.", objectives = "Find a companion pet for Riko and Kiryn.", progress = "If wikket can't find a furry, Riko will have to be a stickypaw.", completion = "You really horkin' did it! You da best, wikket!" }
WordHunterWoW_QuestEN[84616] = { title = "Celebrate Good Fun!", description = "Welcome to the Bronze Celebration! \n\nWe invite you to enjoy our myriad of events. You might choose to mirror your pet and run around our playground. \n\nYou could participate in one of our big events like Fashion Frenzy or Mount Mania. A different event begins every 15 minutes. \n\nOr you might fancy yourself a challenge. If so seek out Chromie as she cleans up her Codex to prepare for her tours. \n\nAny event will do, as long as you are having fun!", objectives = "Participate in activities around the celebration and tasks put forward by those visiting.", progress = "Are you enjoying our fine celebration?", completion = "It is fulfilling to see so many denizens of Azeroth and beyond visiting our celebration. It is in remembering all our pasts that we are able to come together and celebrate. \n\nWe hope that you will continue to enjoy our event. To assist you in your own adventures, take this boon of the bronze flight!" }
WordHunterWoW_QuestEN[84619] = { title = "Ooker Dooker Literature Club", description = "The hozen in the Bilge Rat crew are master scavengers. For years, they've been visiting this island, snatching up anything that might be of value.\n\nAmong their spoils are many research materials that could help unlock the history of this place.\n\nInfiltrate their camp, board their ships, and recover whatever books, scrolls, and documents you can find.", objectives = "Acquire various writing from the Bilge Rat ships and landing area.", progress = "Did you find anything worth reading?", completion = "What a fascinating collection of writings! I daresay I shall be up all night reading these." }
WordHunterWoW_QuestEN[84621] = { title = "Squire's Spurs", description = "You come to Campalot to pledge fealty? Become Knight of the Brown Table?\n\nNot have look of tenderfoot, but even bravest knight start as squire. Earn spurs. Learn humility.\n\nProve you have learned it in same way. See what can do to help around castle.\n\nMight be good example to other squires, too.", objectives = "Help out around Campalot.", progress = "Hmm, think missed spot.", completion = "Job good, Squire <name>. Remember lesson in humility." }
WordHunterWoW_QuestEN[84624] = { title = "Sandy Celebration Crate", description = "<This crate has certainly been on a journey! Alyx would appreciate the supplies returned.>", objectives = "Return the Sandy Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84625] = { title = "Surprisingly Pristine Celebration Crate", description = "<You found this crate of celebration supplies in the unmarked grave where you buried the bones in their place. Alyx would appreciate the supplies returned.>", objectives = "Return the Surprisingly Pristine Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84627] = { title = "Three Heads of the Deep", description = "The reach of these creatures is truly frightening!\n\nI have encountered them countless times in the Imperial waters. I know their strategies well, and I have a plan to deal with them.\n\nMy scouts have pinpointed the location of three of their leaders. Eliminate them, and we'll seize the advantage.", objectives = "Eliminate Warlord Thresh, Extractor Silsai, and Nereu of the Silent Wave", progress = "Have you eliminated their leaders?", completion = "Excellent work, <name>. I could use someone of your caliber aboard my ship--should you ever be looking for work." }
WordHunterWoW_QuestEN[84638] = { title = "Trouble in the Highlands", description = "Both Geya'rah and Danath have received word of unrest in the Arathi Highlands--civil unrest in Stromgarde, and raids on Mag'har and Stromic outposts.\n\nDanath and Geya'rah are returning to their homes, Stromgarde and Hammerfall, to defuse tensions.\n\nI asked to accompany them. I have long wanted to reconnect myself and my people to the Arathi. I also want to learn more about the Horde.\n\nGeya'rah was willing, but... Danath took some convincing.\n\nThough, I may have implied you were joining me...", objectives = "Travel to the Arathi Highlands via the portal in Dornogal.", completion = "I had been sent word of bandits roaming the Highlands but... I did not know it was this bad.\n\nIt's just as well we happened into this attack.\n\nIf we want to get to the bottom of this, we might as well start here.\n\nThough... I do wish Faerin were not here to see this." }
WordHunterWoW_QuestEN[84639] = { title = "Torches and Tar", description = "We've been attacked before. But this time... \n\n<Walker shudders.>\n\nThis was different.\n\nThey didn't want livestock, grain, or money. They took torches and some barrels of tar we use to fix our roofs.\n\nI don't know what they're going to do with it, but... I can guess. They're going to burn something down.\n\nYou need to stop them before they do another homestead harm!", objectives = "Retrieve 10 Stolen Torches from Defias bandits and 10 Barrels of Tar from Newstead Farm.", progress = "I hope whatever they're planning doesn't involve my neighbors. Or Stromgarde!", completion = "Thank you, <name>.\n\nHopefully this \"snuffs out\" what they were planning." }
WordHunterWoW_QuestEN[84640] = { title = "Emblematic of Things to Come", description = "<This Defias bandit was carrying a badge with an unfamiliar emblem.\n\nThe emblem looks like a rising sun with long rays emanating from it. The sun and rays are colored red.\n\nPerhaps Danath can identify it.>", objectives = "Bring the Unfamiliar Emblem to Danath Trollbane at Newstead Farm.\n\nProvided item:", completion = "I don't recognize this emblem. And a Defias had it on their person?\n\nHm. Curious.\n\n<Danath turns it over in his battle-scarred hand, frowning.>\n\nI wonder what it means?" }
WordHunterWoW_QuestEN[84641] = { title = "Ill Tidings", description = "A Defias attack. The theft of tar and torches. A group called the Red Dawn recruiting here in the heart of the Highlands...\n\nStromgarde was right to send a missive asking for my return. What is going on here?\n\nI placed Colonel Nials in charge after Marran's foolishness led to her imprisonment. I must head to Stromgarde and speak with Nials immediately.", objectives = "Meet Danath Trollbane at the gates of Stromgarde Keep.", completion = "This is much worse than I thought. With the attacks disrupting supply lines, the people are angry, hungry, and looking for someone to blame. The easy choice is blaming our neighbors at Hammerfall.\n\nWe cannot let this unrest continue. I must speak to Nials and my advisors.\n\nI see Faerin has volunteered the both of you to help the people of Stromgarde. I do not like putting either of you to work on what is a diplomatic mission, but helping Brewston while I speak to Nials would put my mind at ease." }
WordHunterWoW_QuestEN[84643] = { title = "Curfew Kerfuffle", description = "I'm glad for your help. Between deployments to Khaz Algar, responding to threats in the Highlands, and desertion, we simply don't have enough soldiers to enforce order.\n\nMarran's supporters are causing trouble throughout the city. They're stealing supplies, harassing people--you name it. We've enacted a curfew, but Marran's supporters are openly defying it.\n\nAs my deputies, go around and tell the troublemakers to go home. If they get rowdy, you have my permission to teach them a lesson.", objectives = "Deal with 15 Marran Supporters in Stromgarde.", progress = "I understand that curfews are unpopular, but we really need one right now.", completion = "It's despicable really. They try to intimidate loyal citizens and make them leave just because they aren't human. They also shout down anyone that doesn't agree with them.\n\nMany around here just try to avoid them, but it seems like they hang out where it's hard to do that." }
WordHunterWoW_QuestEN[84645] = { title = "Deputy Delivery", description = "Trade in Stromgarde has broken down. We're short on goods and workers because of the attacks.\n\nNials was too busy, so I took it upon myself to write official requests for aid.\n\nMost are simple and straightforward--writs for supplies and such for the Stromic army.\n\nThe desist writ for Joseph is different. He is loudly blaming everyone not human for our woes. Someone needs to officially tell him to shut his yap before he starts a riot.\n\nAs my deputies, would you enforce my requests for aid?", objectives = "Deliver Brewston's request writs to people in Stromgarde.", progress = "I know some won't be happy with what we're requesting of them, but it's what's best for Stromgarde and its people.", completion = "You have my thanks and the thanks of Stromgarde.\n\nI'm sorry you got an earful from Joseph--at least he left peacefully!\n\nDespite how it may seem, the city is still loyal to Lord Trollbane. Mostly.\n\nLady Marran's followers are just louder. And angrier." }
WordHunterWoW_QuestEN[84649] = { title = "Marran Trollbane", description = "I am Colonel Veronica Nials, and I am in command of Stromgarde in Lord Trollbane's absence.\n\nI'm sure while aiding our people you've heard the name \"Marran\" in Stromgarde. Lady Marran Trollbane is Danath's niece. She was briefly regent while Lord Danath Trollbane campaigned for troops for Khaz Algar. \n\nHer actions during his absence led him to imprison her when he returned.\n\nThat said, Lord Trollbane felt Faerin should speak to her. Perhaps to get... perspective. I can take you to her if you wish.", objectives = "Observe the meeting between Faerin Lothar and Marran Trollbane in the barracks of Stromgarde Keep.", completion = "Marran may be in prison now, but her supporters continue to spread her rhetoric across the Highlands.\n\nWhatever she may say, I do not believe that she is the leader of this \"Red Dawn\" that you both are speaking of.\n\nI see who comes and goes. She receives no outside visitors." }
WordHunterWoW_QuestEN[84650] = { title = "Finding Refuge at Refuge Pointe", description = "If you want to find Lord Trollbane and tell him your theory about Lady Marran, the missive called him to Hammerfall, far to the east of here.\n\nHe may have stopped at Refuge Pointe on the way--it's a Stromic encampment about halfway to the orc town. Because of the frequent bandit attacks in the area, I believe he meant to stop and check in with our people there.\n\nYou might catch up with him there.", objectives = "Look for Danath at Refuge Pointe in the Arathi Highlands.", progress = "It's good to see humans and orcs banding together to help one another.\n\nIf only the Arathi here could have seen what I did at Khaz Algar.", completion = "Another bandit attack? And they carry the same emblem as the bandits at Newstead?\n\nIf this is connected to the Red Dawn and Marran..." }
WordHunterWoW_QuestEN[84651] = { title = "A Familiar Face", description = "Early on, these attacks on our settlements seemed to be pockets of bandits competing for resources.\n\nNow they are better coordinated. As if they are working together as a group. \n\nThat's bad news for everyone.\n\nBut rivals don't come together without a strong leader. And without them, they will fall.\n\nIf you're willing, find the leader of this attack on Refuge Pointe and eliminate them.", objectives = "Defeat the leader of the attack on Refuge Pointe.", progress = "Go. I will protect these people until your return.", completion = "He escaped?\n\n<Karga spits on the ground.>" }
WordHunterWoW_QuestEN[84652] = { title = "Supply Run", description = "Stromgarde's troops are in Khaz Algar and it cannot protect its outlying settlements. \n\nHammerfall does what it can to help, but we too fight in Khaz Algar.\n\nWe've taken many injured Stromic refugees to Hammerfall, but feeding them all has strained our resources.\n\nBut there may be a way to help more people.\n\nVikki told me Refuge Pointe is a supply depot for nearby settlements. If we can get our hands on some supplies, we can care for more refugees in Hammerfall.", objectives = "Collect 4 Supply Crates from Refuge Pointe.", completion = "Good, <name>. \n\nI hope Stromgarde does not mind us \"borrowing\" these supplies for their refugees.\n\nHeh." }
WordHunterWoW_QuestEN[84653] = { title = "DEPRECATED", description = "<You find another one of the strange rings. This time from a Scarlet Crusade member.>\n\n<You should talk to Faerin about it. This is getting suspicious.>You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Scarlet Ring to Faerin in the Arathi Highlands." }
WordHunterWoW_QuestEN[84656] = { title = "Onward to Hammerfall", description = "First an attack on Newstead Farm by Defias, now an attack on Refuge Pointe by these Scarlet Crusaders. \n\nDifferent groups of bandits, but both speak of this \"Red Dawn\" and carry the same emblem. \n\nAlso, Joseph is directly involved.\n\nThis all seems connected... and it leads back to Marran.\n\nDanath needs to know what's going on. If he's not here, he should already be at Hammerfall. \n\nWe should head there as soon as possible.", objectives = "Meet Faerin Lothar at Hammerfall in the Arathi Highlands.", completion = "If Danath is not here... Where is he?" }
WordHunterWoW_QuestEN[84657] = { title = "Return to Stromgarde", description = "Eitrigg was right. The Red Dawn are trying to start a conflict between the Horde and the Alliance.\n\nWe need to get back to Stromgarde and tell Colonel Nials that Danath has been kidnapped. She will surely commit all her resources to a search!\n\nCome, {name}. There's no time to waste!", objectives = "Return to Stromgarde and enlist Colonel Nials's aid in finding Danath.", completion = "<Brewston leans in close to you and speaks just above a whisper.>\n\nI'm glad I found you. I need all the allies I can get.\n\nYou're very lucky they left you alive." }
WordHunterWoW_QuestEN[84658] = { title = "Finding Family", description = "Where's my mama? My papa?\n\nEllie?\n\n<Maggie looks around with tears in her eyes.>\n\nI was followin' Mr. Gresham and Clarabelle when we saw the bandits. He grabbed me up and we ran here.\n\nI don't know where Mama and Papa and Ellie are.\n\nCan you find them for us? Clarabelle is starting to get worried...\n\n<Maggie sniffles.>", objectives = "Discover the fates of Marshall Wiltshire, Sharon Wiltshire, and Ellie at Newstead Farm.", progress = "Ellie must be so scared!", completion = "You found them! You found them! Thank you so much!\n\n<Maggie hugs Ellie tightly.>" }
WordHunterWoW_QuestEN[84659] = { title = "The Search for Faerin", description = "I saw Faerin being taken away, but couldn't follow without them seeing me. She's probably being held in another building.\n\nGo find her. Hopefully, she's still alive...\n\nAnd see if you can find any more information on the Red Dawn. There's no way we should have been overwhelmed so quickly. Colonel Nials and Lady Trollbane must have installed their cronies everywhere.\n\nThe more information we have, the more we can use against them when we fight back.", objectives = "Search the structures in Stromgarde for Faerin and information on the Red Dawn.", progress = "Have you found Faerin?", completion = "I'm glad Faerin is all right. \n\nAnd this information you've found...\n\n<Brewston's shoulders slump.>\n\nWhen people are desperate, they'll believe in any promise of a better life no matter whom it's from." }
WordHunterWoW_QuestEN[84664] = { title = "Making the Underworld Go Round", description = "Hey there, 'Overcrawler.' You're lookin' more than a little out of your element there. You get run over by an airship or something?\n\nWhatever. Doesn't matter. Take it from one outsider to another, if you're going to survive down here you're gonna need to learn the rules of the road. Gold's all well and good where you came from, but down here you're gonna need Kej, and lots of it.\n\nNow here. Consider this a token of good will from Lady Pedipalps up there. Go get yourself something nice.", objectives = "Spend Kej at one of the vendors in the Weaver's Lair.", progress = "What, you allergic to retail therapy or something? Get out there and live a little!", completion = "Get a good look around? This place is pretty spooky, even for a savvy gal like me. But get enough Kej together and you'll be able to buy all sorts of stuff, both here and in the City of Threads.\n\n<Linny looks you up and down.>\n\nThen again, you're probably still gonna get eaten, so maybe look into fine nerubian gravestones." }
WordHunterWoW_QuestEN[84667] = { title = "The G.O.L.E.M. of Progress", description = "The citizens of Undermine cry out for help! They need protection! They need joy! They need to get by!\n\nAs an inventor, I've spent my life building somethin' that'll solve our people's problems, and it's just about ready for a test run. I'm calling it my Goblin Optimal Livability Enhancement Machine, or G.O.L.E.M. for short!\n\nFind some problems and take it out for a spin- and take my son with you! Pitz doesn't have an inventor's bone in his body, but certainly he can yak it up with the neighbors.", objectives = "Tour the Vatworks with the G.O.L.E.M. and solve problems for Gart Pocketz, \"Cranky\" Nan, and the children of Undermine.", progress = "Pops is really over the moon about this G.O.L.E.M. thing. I hope it works out for him.", completion = "Well, it sure was great while it worked!" }
WordHunterWoW_QuestEN[84671] = { title = "Tracking Quest Wk", description = "", objectives = "" }
WordHunterWoW_QuestEN[84672] = { title = "Garbage Day", description = "My old man's got all these crazy ideas about helping the world... I dunno. It's all a bit over my head, but I guess that's why I was never the inventor he wanted me to be.\n\nStill, I've got some thoughts on how to solve problems around here. Like those dang rodents getting litter all over the streets!\n\nIt might not revitalize the spirit of the community or whatever, but I bet people would be happier if we cleaned up the streets.", objectives = "Collect 12 pieces of litter and use the G.O.L.E.M.'s incinerator function to dispose of them.", progress = "Toxic fumes? Nah, that's just what Undermine smells like!", completion = "The place is looking cleaner already! Maybe there's something to this G.O.L.E.M. thing." }
WordHunterWoW_QuestEN[84673] = { title = "World's Okayest Inventor", description = "I'm... not the inventor my old man is. Or much of an inventor at all, really. My masterwork is over by the wall there, but to be honest, there's a lot of work that still needs to be done to get it to do... anything.\n\nBut this! This could be my big chance to prove to Pops that I've got what it takes to make him proud!\n\nAll we need to do is actually, uh, figure out how to repair this thing. How hard could it be?", objectives = "Help Pitz repair the G.O.L.E.M.", progress = "Is it... working?", completion = "This isn't good. This isn't working at all." }
WordHunterWoW_QuestEN[84674] = { title = "The G.O.L.E.M. Goes Berserk!", description = "The G.O.L.E.M.'s gone berserk! Haywire! Bonkers!\n\nI gotta go chase it down--who knows what kinda trouble an invention that powerful could cause! Plus, imagine how mad my old man would be if we lost it!\n\nI hate to ask you to clean up my messes, but someone's gotta hang back and get everything in order again. Could you do that?", objectives = "Calm the chaos caused by the G.O.L.E.M.", progress = "Pitz! Has anyone seen Pitz?", completion = "All this chaos... what has the G.O.L.E.M. wrought?!" }
WordHunterWoW_QuestEN[84675] = { title = "Showdown in the Attic", description = "I've been so blind! Everything's falling apart!\n\nThe neighborhood is worse off than ever, and the G.O.L.E.M.'s to blame! And my boy, my dear Pitz...\n\nHe ran into this building to try and stop the contraption. I was so hard on him, and now I might never see him again...\n\nYou gotta find him. And stop that thing once and for all.", objectives = "Rescue Pitz and destroy the G.O.L.E.M.", progress = "My hubris... that's the first thing they tell you in inventor school! Why didn't I listen!", completion = "Y'know... he may not be much of an inventor, but I'm proud of that boy." }
WordHunterWoW_QuestEN[84680] = { title = "Rock 'n Stone Revival", description = "The attacking vrykul harness salt and brine elementals, turning them against their foes.\n\nTo counter their assault, we can harness them as well.\n\nUse this Rock Reviver to unleash the elementals residing within nearby stones, transforming them into powerful allies. With their help, we can defeat this vrykul threat.", objectives = "8 Restless Pebbles or Stones revived, 8 Bloodbrine horrors and the Bloodbrine Monstrosity defeated.", progress = "Have you stopped the vrykul and their elemental thralls?", completion = "You've done well harnessing the elementals, <name>. I eagerly await further displays of your abilities." }
WordHunterWoW_QuestEN[84682] = { title = "Of Pacts and Patrons", description = "The Severed Threads is ready for you and your allies. You will be a lit torch to Ansurek's webs.\n\nThe General, the Vizier, and, myself, the Weaver, each have differing methods of combating our foes... and different benefits of aiding our accomplices. You may prefer to prioritize one, or perhaps to dabble with all three instead.\n\nMeet with our representatives, and inform yourself on our varying practices. Then you may forge your first Pact.\n\nDon't worry, little morsel, no choice is ever permanent.", objectives = "Speak with the representatives of the Severed Threads, then forge your first Pact.", progress = "Have you considered your options?", completion = "May your chosen patron favor you, as you have them." }
WordHunterWoW_QuestEN[84683] = { title = "Into the Gutter", description = "What're you doing here? Sabotagin'?\n\nI can understand that. Things are way out of hand. But if we explode this pipe here, it'll get even worse. Black Blood everywhere. Maybe together we could come up with somethin' real to do.\n\nMeet me in Gutterville. We'll talk more, away from these awful slimes!", objectives = "Meet Pamsy in Gutterville.", completion = "Keep yer voice down! I've never seen so many spies in Gutterville..." }
WordHunterWoW_QuestEN[84684] = { title = "Ratts' Race", description = "I saw a vulpera acting very suspicious. She seemed... on edge. I think I saw a knife at her side and a look of dark magic in her eyes.\n\nShe noticed me staring and immediately fled. Is she a wanted criminal?\n\nShe... dropped this. Here.", objectives = "Track down Ratts.", progress = "<Ratts seems to have dropped this gem in her haste.>", completion = "<What could be the purpose of this gem that Ratts left behind?>" }
WordHunterWoW_QuestEN[84687] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "" }
WordHunterWoW_QuestEN[84688] = { title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "" }
WordHunterWoW_QuestEN[84693] = { title = "Weaver's Lair Profession Table", description = "Present this token to Ak'itaz in the Weaver's Lair to have your own personal profession table constructed.", objectives = "Speak with Ak'itaz in the Weaver's Lair.\n\nProvided item:", completion = "What have you here? Ah! I make table for you. What do you like to build? \n\nDo you work with meat, metal or magic?" }
WordHunterWoW_QuestEN[84700] = { title = "Pacts Below", description = "This weave-rat carries a note upon its body. It's addressed to you, from the Widow Arak'nai.\n\n\"Dearest morsel,\n \nMyself and the other members of our Severed Threads triumvirate request your presence. Azj-Kahet itself is on the precipice of an evolution, but we'll need your... unique methods if we're to see it through.\n\nAnd, as always, the rewards to you and your cause will be quite magnificent.\"", objectives = "Go to the Widow Arak'nai in the Weaver's Lair.", completion = "Thank you for making the trip back down to my humble lair.\n\n<A deep chuckle rumbles out from Widow Arak'nai.>\n\nWe have got grand plans in store for you. Certainly, certainly." }
WordHunterWoW_QuestEN[84701] = { title = "The Speaker", description = "So there is someone else who has experienced something close to what I experienced. Yet it is not the same.\n\nI must speak with him.", objectives = "Speak to Magni in Dornogal.", completion = "Have ye come tae say goodbye?" }
WordHunterWoW_QuestEN[84704] = { title = "A Different Point of View", description = "Danath is not here. \n\nFaerin says he journeyed to Hammerfall because we requested a meeting. I sent no such message to him nor anyone else. \n\nI will dispatch outriders immediately to search for him. \n\nWhile we wait for their return... You and Karga's quick thinking may have saved our human refugees. We had just run out of food to give them.\n\nDistribute the crates directly to them. I'm sure they will be grateful for the food inside.", objectives = "Place 4 Supply Crates next to Arathi Refugees taking shelter in Hammerfall.", completion = "I never realized how much my people have in common with the orcs. We are both far from home, we are both self-sufficient, we are both peoples born into war...\n\nAnd most of all, their sense of duty and honor rivals ours.\n\nI feel... even more at home here than in Stromgarde." }
WordHunterWoW_QuestEN[84705] = { title = "Withering the Witherbark", description = "The Witherbark have always been an annoyance since I have been here. But now?\n\nSomething has stoked their ire. They are attacking human settlements. Perhaps the Red Dawn is again to blame.\n\nEitrigg has ordered us to try to help the humans they attack. We have stepped up our patrols and welcomed refugees. \n\nBut we need someone to go to their village and bloody the Witherbark's noses. They're overconfident. They think they can get away with attacking our outriders!\n\nMake them think twice about that.", objectives = "Slay 15 Witherbark trolls at Witherbark Village.", completion = "Feh.\n\nThat will surely cow them. I'd be surprised if I saw any of them stray from their village any time soon." }
WordHunterWoW_QuestEN[84706] = { title = "Crime Family", description = "This Syndicate human came to us hoping to trade information for a rescue mission. The Syndicate is a recent thorn in our side, so I had half a mind to cut him down where he stood. \n\nBut he claims to have vital information, and with this news of Danath's disappearance... it might be worth the risk to do as he asks.\n\nHe has three brothers being held captive inside Witherbark Village. Go in, find them, and if they're alive, extract them.", objectives = "Save Crestor, Holt, and Perry from the Witherbark trolls in Witherbark Village.", completion = "Barclay is lucky you reached his brothers in time." }
WordHunterWoW_QuestEN[84707] = { title = "To See a Troll", description = "There's no word from the outriders yet, but Eitrigg has not told Geya'rah of Danath's disappearance. \n\nI have told him we would go and give her the news.\n\nShe's at Go'Shek Farm dealing with a Witherbark troll attack. Eitrigg says they've become increasingly aggressive recently. \n\nI can't help but think of the history there--of the Troll Wars and Arathi battles. But I admit I see them differently now after learning more about the Horde.\n\nLet's go. We can look for Danath while we're out there.", objectives = "Meet Overlord Geya'rah at Go'Shek Farm.", completion = "Faerin has informed me of Danath's disappearance. While that is... troubling... We can't return to Hammerfall just yet." }
WordHunterWoW_QuestEN[84708] = { title = "The Syndicate Strikes Back", description = "This human is claiming the Syndicate scum are going to attack Hammerfall! Another day I would not be concerned. But with the outriders dealing with the Witherbark and searching for Danath, Hammerfall is undefended!\n\nLet's go {name}. We must defend our home!", objectives = "Meet Overlord Geya'rah at Hammerfall.", completion = "I should have been here. I could have done something.\n\n<White-hot fury and rage emanate from Geya'rah's tense posture and tightly-closed fists.>" }
WordHunterWoW_QuestEN[84709] = { title = "Hammerfall Down", description = "<Eitrigg growls in frustration.>\n\nI was such a fool!\n\nI should not have sent away those outriders. Without them, the Syndicate have overrun Hammerfall.\n\nAnd were it not for my fool heart... The \"refugees\" turned out to be Syndicate spies, curse their greasy hides...\n\nBut now you're here. Now, we can force the Syndicate out. Eliminate their soldiers and save any trapped civilians. \n\nThose spies have had enough of my open hand. Now they'll suffer my fists!", objectives = "Eliminate Syndicate soldiers and save trapped civilians in Hammerfall.", progress = "The Syndicate...\n\nI haven't seen them in this number in many years.", completion = "There are still Syndicate stragglers about, but Hammerfall once again belongs to the Horde!" }
WordHunterWoW_QuestEN[84710] = { title = "Once Bitten Twice Shy", description = "I caught a glimpse of who was leading the attack.\n\nIt looks like Joseph the Enlightened may be less full of hot air than we thought he was.\n\nIs he now part of the Syndicate? I thought he was part of the \"Crusade.\" I suppose it doesn't matter. If we want to stop the attack, we'll have to take him out.", objectives = "Defeat Joseph the Enlightened in Hammerfall.", progress = "I fully expect him to run away again like the coward he is.", completion = "Joseph escaped again, and this time his warning was much more foreboding. He has darkness in his mind... and his soul. \n\nI am... confused how he can profess to follow the Light." }
WordHunterWoW_QuestEN[84711] = { title = "Danath's Disappearance", description = "My outriders discovered a destroyed caravan on the road. \n\nAround it were the bodies of Stromic soldiers.\n\nIt could be Danath's escort. Or it could be another hapless group.\n\nEither way, we must investigate. Let us hope Danath is not among the dead.", objectives = "Meet Overlord Geya'rah at the Arathi Highlands crossroads.", completion = "This wasn't a battle. It was an ambush and a massacre." }
WordHunterWoW_QuestEN[84712] = { title = "False Flag", description = "This was not done by simple bandits. This spot was chosen specifically for an ambush. And these troops were taken down quickly and efficiently.\n\nIf Danath was heading to Hammerfall, this road is the most direct route. That makes it predictable.\n\n<Geya'rah grimaces.>\n\nWe must search for Danath among the dead and find out what happened here. Leave no stone left unturned.", objectives = "Investigate the area for clues as to Danath's disappearance.", completion = "It is decided then. \n\nIf we are to prevent war, we must alert the Alliance to the situation and rescue Danath as quickly as possible." }
WordHunterWoW_QuestEN[84713] = { title = "Fallen Fortress", description = "If Danath's kidnappers want to keep him from prying eyes, Ar'gorok is the perfect place. \n\nIt's been abandoned for years, but its buildings still stand. All the \"Red Dawn\" could be there and no one would be the wiser.\n\nWe must find Danath quickly, {name}. Hammerfall is vulnerable and tensions are high. A missing leader is just the excuse Marran needs to start a war.", objectives = "Meet Eitrigg at Ar'gorok.", completion = "I believe we've found where the Red Dawn were hiding." }
WordHunterWoW_QuestEN[84714] = { title = "From Ironforge With Love", description = "This \"Red Dawn\" is occupying the fortress of Ar'gorok. Bandits of all types and bands have taken refuge here under their banner.\n\nAnd I'm sure they've brought their spoils with them.\n\nIt may help calm tensions if we recover the goods they've stolen and return them to their rightful owners in the Arathi Highlands.\n\nSee if they are carrying anything with them.", objectives = "Collect 20 Stolen Ironforge Supplies from Red Dawn troops within Ar'gorok.", progress = "Who knows what we will find.\n\nWhat they've stolen could have come from here in the Arathi Highlands, or as far as the Horde or Alliance capitals.", completion = "More supplies? Good.\n\nHm. Looks like these were on their way from Ironforge to Stromgarde.\n\nFrom what Faerin has told me, the Stromic will be very pleased that we found them." }
WordHunterWoW_QuestEN[84715] = { title = "The Search for Danath", description = "Using Ar'gorok as a base was clever. Very clever.\n\nIt looks like the bulk of their forces are here. If Danath is alive, I'm certain they would keep him here.\n\nSearch the buildings for him. And look for any information on this Red Dawn that you can. Anything might be helpful in taking them down. \n\nLet's hope Danath is alive. If he isn't, a long and bloody conflict is ahead of us.", objectives = "Search the structures in Ar'gorok for Danath and information on the Red Dawn.", progress = "Danath is here but we need a key to open the door!", completion = "You found a key? \n\nJust what we need." }
WordHunterWoW_QuestEN[84716] = { title = "Returning to Stromgarde", description = "While feigning sleep, I heard the guards brag about the Red Dawn's plans for Stromgarde.\n\nMy kidnapping was just the start.\n\nColonel Nials--after all these years! She will be the one to turn the key and free Marran, my niece, to do as she wishes and start a coup!\n\nMarran will lead Stromgarde's army and the Red Dawn to Hammerfall to secure the Highlands for \"Strom.\"\n\n<Danath's face is red with fury, but his eyes water with tears.>\n\nWe must gather our allies... and confront these traitors!", objectives = "Meet your allies at Stromgarde Keep.", completion = "Marran has made her move. The coup has started.\n\nFaerin and Brewston have rallied the Stromgarde loyalists, but there are many Marran supporters.\n\nThis will be a bloody civil war." }
WordHunterWoW_QuestEN[84717] = { title = "Rise of the Red Dawn", description = "Danath and Eitrigg ran ahead to confront Marran. They hope if they stop her, they can end the coup--and the bloodshed.\n\nBut after seeing Joseph the Enlightened's handiwork first hand... \n\nDespite how unorthodox he may be, he's still a danger. And I hate to say it, but I would relish the chance to finally take that underhanded cretin down.\n\nHe's blocking our path up ahead at city hall. Let's take him down and then help Danath and Eitrigg end this war.", objectives = "Defeat Joseph the Enlightened and help Danath and Eitrigg.", completion = "Marran was given mercy.\n\nI'm still not sure she deserved it.\n\nBut there is little she can do now without her name and title. After failing twice, the Stromic will not follow her. And without the power her name and title wielded, she's useless to the bandits.\n\nMercy or not, I thank the Light that the conflict has been ended.\n\nYou have my thanks as well, <name>." }
WordHunterWoW_QuestEN[84719] = { title = "The Expedition Awaits", description = "Greetings, {name}! Are you here to answer the Siren Isle's call to adventure?\n\nRecently, a goblin salvage team discovered an isle with a strange \"singing crystal\" at its center.\n\nLike the goblins, the Arathi of Hallowfall have taken a keen interest in this crystal--as have we. We've been preparing an expedition to the isle!\n\nMost of the expedition has gone ahead, but the goblins last vessel is set to leave momentarily.\n\nIf you hurry, you can catch them before they leave and join us!", objectives = "Meet Skaggit by the East Gate of Dornogal.", completion = "Ah, so you're the one Dawn convinced to join us, eh? \n\nWell, hurry up! They've been adamant about getting us a proper Stormrider-ranger-whatever escort out of the city, but it's takin' too long!\n\nThe Arathi and other earthen are already on the Isle and Ricket is probably wonderin' where the heck we are!\n\nC'mon! I can give you the deets on the way!" }
WordHunterWoW_QuestEN[84720] = { title = "To the Siren Isle!", description = "The Siren Isle is a myst'ry. A potentially profitable one.\n\nMy crew thought they hit it big when they found a deserted island with some strange, singin' crystal...\n\nTurns out, everyone in Dornogal is interested in unclaimed \"strange singin' crystals.\" Both the Arathi and earthen scrambled quick an' were off before we could even charter a zeppelin!\n\nFortunately for us, Ricket and crew have gone ahead to set up.\n\nWe're the last to depart, an' I'm itchin' to go. What're we waitin' on?", objectives = "Speak with Skaggit to journey to the Siren Isle.", completion = "We made it safe and sound!\n\nRicket says the whole camp's still buzzin' about the crystal.\n\nSeems like everyone's got different ideas on how to go about figurin' out what to do with it.\n\nThey didn't like Ricket and I's way but, you might be better at diplomacy.\n\nYou wanna get involved?" }
WordHunterWoW_QuestEN[84721] = { title = "To Scan a Crystal", description = "In order to understand the \"singing crystal\" at the heart of the island, we will need some special machinery.\n\nWe have forged a device to scan its exposed facets, but the crystal's energies are far too complex to read. It has a highly unusual energy signature.\n\nThe goblins and Arathi seem keen to contribute, so let us proceed with their help.\n\nTake my toolbox and retrieve the prototype and the components the Arathi and goblins have prepared.", objectives = "Assist Bargus by collecting the earthen prototype, the Arathi's focus and the goblin's power source.", progress = "Normally, our technology is quite capable when it comes to crystals and the energies found within them. \n\nBut the energies found here are anomalous and don't synchronize with our technology...", completion = "Skepticism... disengaged. \n\nIt would seem the radiant remnants from Hallowfall harmonize perfectly with the energies found here, giving us a proper signature to latch onto.\n\nThe goblins' batteries are... more than we need, but they appear to be doing the job effectively.\n\nWe're almost ready for the field test!" }
WordHunterWoW_QuestEN[84722] = { title = "Facet-nating Signals", description = "Intriguing! \n\nThese radiant remnants from the Arathi seemed to have given our device the necessary focus it needed. All that remains is to attune it properly to its size.\n\nIn order to attune to the signal, we'll need to set up some pylons around the site.\n\nThere is testing to initiate, {name}. Follow me if you would like to assist me.", objectives = "Meet Bargus by the Crystal and help him set up the pylons.", progress = "Once the pylons are operational, I should be able to triangulate the signal.", completion = "Fascinating!\n\nThe pylons' attunement indicates this crystal is far larger than this facet would suggest. \n\nAccording to the complexity of the signature, it appears to stretch for miles beneath our feet and--wait, what is this?\n\nA second signature appears to be originating from over the hill? Curious indeed..." }
WordHunterWoW_QuestEN[84723] = { title = "Buried Secrets", description = "These ruins are... quite old. Well, old by most outlanders' standards.\n\nWhich begs the question: was finding this chamber the unfriendly outlanders' directive, or was it finding the tablet?\n\nOne clue is that my readings suggest energy is flowing through the tablet as a conduit rather than originating from it.\n\nShall we take a closer look?\n\nPerhaps investigation will yield some answers--and the source of the energy readings.", objectives = "Investigate the ruins and find the source of the signal.", completion = "By the forge... this is...\n\n<Bargus stares wide-eyed in wonder at the gleaming crystal, struggling to find words. After a moment, he nods.>\n\nThis is most certainly the source of the second signature, though the energies here appear to have fused with the original.\n\nIt's almost like it wanted us to find this place..." }
WordHunterWoW_QuestEN[84724] = { title = "The Radiant Vault", description = "This vault... this crystal...\n\nWho made this place? Who lived here? And who is this \"Cyrce\" we keep seeing mentioned on the tablets?\n\nWhen we set off to learn about the crystal, I did not anticipate discovering the remnants of an ancient civilization far beneath the earth.\n\n<Bargus ruffles his wiry moustache before glancing at you.>\n\nThis bears closer examination, don't you think?", objectives = "Investigate the Crystal Shrine.", progress = "It would seem we've made quite the discovery...", completion = "More queries and very few answers.\n\nFortunately, the device was able to gather some data from the energy readings. \n\nIt will take time to process, but we will soon have a better understanding of this \"Siren Crystal.\"\n\nIn the meantime, let's take a closer look at that ring and citrine shard you found. Angorla here will be able to help." }
WordHunterWoW_QuestEN[84725] = { title = "The Circlet Calls", description = "<Angorla peers at you from over her spectacles with excitement.>\n\nCan you hear it, {name}?\n\nThis small, humble citrine is calling out to the circlet... just as the Siren Crystal called out to you and to all of us.\n\nI am uncertain what will happen when you reunify them... but there's only one way to find out.\n\nPlace the circlet upon your finger and socket the citrine into the setting.", objectives = "Equip Cyrce's Circlet and socket the Windsinger's Runed Citrine into the Singing Wind Socket.\n\nThen, remove the Windsinger's Runed Citrine from the socket.", progress = "Have you placed the citrine into the circlet, <name>?", completion = "I can feel it from here... radiating. Thrumming with a long-dormant power.\n\nWho carved these small little citrines? Why do they appear to fit perfectly into the Circlet yet... they were found separated?\n\nOh, how I wish I had seen what you and Bargus had found within the Vault..." }
WordHunterWoW_QuestEN[84726] = { title = "Uncovered Mysteries", description = "<Angorla takes your hand in hers and examines the crystal-embedded circlet closely.>\n\nCan you feel the energy humming through it, {name}? The circlet feels... awake. \n\nPerhaps more secrets lie around the isle, waiting for you to uncover them.\n\nDawn encouraged us to explore and learn about this isle, but I've got my work cut out for me here.\n\nWhy don't you see what other secrets you can find?", objectives = "Uncover hidden secrets around the Siren Isle.", progress = "What have you found? Another treasure, perhaps?", completion = "Curious. Even as fragments, the pieces hum with energy. I wonder if I...\n\n<Angorla presses the fragments together like a puzzle, squeezing them in her palm. After a moment, she opens her hand and reveals a neatly-fused shard.>\n\nIt may be less intricately-carved or ornate as the citrine you found in the vault, but there is power here, even in a small stone like this." }
WordHunterWoW_QuestEN[84727] = { title = "The Second Signal", description = "An unexpected development.\n\nThe energy signature appears to have a secondary source--and it is just north of here.\n\nCuriosity activated.\n\nJudging from the estimated size of the crystal, I theorize it might be a secondary exposed facet.\n\nFurther investigation is required. Follow me.", objectives = "Follow Bargus north.", completion = "It would seem we are not alone on this island after all, <name>.\n\n\n\nTo initiate violence before diplomatic engagement... An illogical provocation that yielded unfortunate consequences." }
WordHunterWoW_QuestEN[84728] = { title = "Reforged Anew", description = "The cracked citrine you found seems to be a perfect fit for one of the sockets found in the ring, yet...\n\n<As Angorla sockets the shard into the ring, the citrine wiggles loose and pops out.>\n\nThe ring appears to be rejecting the piece. If we can repair the citrine and stabilize the energy within the shard, perhaps the ring will accept it?\n\nSince you've been so helpful with Bargus, care to lend another hand?", objectives = "Help Angorla repair the Citrine.", progress = "A fractured citrine is hardly an obstacle!", completion = "<Angorla holds the glowing citrine in her hand before holding it out to you.>\n\nThat seemed to do the trick... I've never felt such energy radiate from such a small crystal before. \n\nThe runes engraved on it are quite ancient and very powerful." }
WordHunterWoW_QuestEN[84730] = { title = "An Armored Charge", description = "The inorganic material of this island is peculiar. The effects of salt water and years of storm erosion have enriched the minerals of this place.\n\nAnd enriched minerals are exactly the type of material an Ordinant seeks to infuse into new armaments.\n\nBring me a considerable amount of storm-flecked debris from the isle's myriad of creatures. I would like to see if they are suitable for my craft.", objectives = "Collect 50 storm-flecked debris.\n\nDebris can be looted from creatures across the Siren Isle.", progress = "Have you found any storm-flecked debris? It should be somewhat plentiful here if you're willing to look.", completion = "<Bargus crushes a chunk of debris in his hand and spreads it on his anvil to examine.>\n\nFascinating... this detritus contains slivers of crystalline material. I wonder if it is eroded fragments of the Siren Crystal...\n\nI may have another task for you, <name>.\n\nBut first, help yourself to the armaments I've forged." }
WordHunterWoW_QuestEN[84731] = { title = "Storm Breadcrumb", description = "", objectives = "" }
WordHunterWoW_QuestEN[84735] = { title = "Truth of the Dark Irons", description = "Few know the truth of the Dark Iron clan. Even fewer have seen it for themselves.\n\nThe Timewalkers have agreed to take us back. They will send us to the time when our clan lost its emperor. And in doing so, I hope I can show you everything that came from that defeat. The good. The bad...\n\nWill you see the truth for yourself?", objectives = "Defeat Emperor Dagran Thaurissan in the Return to Blackrock Depths raid.", progress = "I will guide you along your path. Though the end of it... I don't know if I can bear to witness that again, champion.", completion = "The Dark Iron clan was lost to Ragnaros. I dreamed of freeing them from his thrall. If only I could have done so before my husband was...\n\nHere. Take these tokens from our hosts. And thank you for seeing the truth with your own eyes." }
WordHunterWoW_QuestEN[84740] = { title = "Bridge to Nowhere", description = "Are you heading to the dunes? I'm looking for my sister, Shahata. I don't know if she's alive, but I have to find her.\n\nThe only place I can think to start the search is our village. K'aresh is nothing like I remember. I need landmarks--anything I can recognize to navigate by.\n\nTake this echo surveyor. It will reveal traces of the past--hopefully enough for me to orient us.", objectives = "Use the Echo Surveyor to help Om'fennad find his way.", completion = "Thank you, <name>. I think I have my bearings now. You see how much life used to be here? It's hard to imagine Shahata surviving here for so long... No. We'll find her. We have to." }
WordHunterWoW_QuestEN[84741] = { title = "Signs in the Sands", description = "Things are starting to feel familiar. I think I know the way back to my village.\n\nI should tell you... I'm not just looking for my sister. Our mother died when I was studying in the cities. Shahata buried her under her favorite tree, but I wasn't there. I swore I would come home to conduct the funeral rites, but I didn't make it in time.\n\nI have left my oath unfulfilled for far too long. I owe it to mother to at least try now. Come--let's search the village.", objectives = "Follow Om'fennad to his village.", progress = "This can't be it! There must be something left.", completion = "I don't know what I expected. She's right. I did break my oath, and now the village is gone.... She's still here, though. \n\nIf she has anything that belonged to our mother, then there's still a chance the surveyor can trace it to the grave." }
WordHunterWoW_QuestEN[84755] = { title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", objectives = "Speak with Maru.", completion = "Nooo! My toy is gone!" }
WordHunterWoW_QuestEN[84756] = { title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out da culprit before they take more toys!", objectives = "Discover the toy thief.", progress = "Did you find my toy?", completion = "Yay! You found ALL the toys! How did dat big doggo collect so many?\n\nI'll have to go see if anymore of my toys are in da pile...\n\nThanks for all the halp." }
WordHunterWoW_QuestEN[84759] = { title = "Ill-met in Starlight", description = "I used to practice what I would say when I saw my brother again. Then I stopped believing I would...\n\nHe's been away all this time, and now he comes to ask for heirlooms? I dug our mother's grave beside her favorite tree. Alone. He should have come back then, I don't have time to help him ease his conscience now.\n\nIf you two are so set on talking, at least have the sense not to do it in the open. Come to my camp--we'll speak there.", objectives = "Meet Shahata at her camp.", completion = "I hadn't expected to see Fennad again. He's a bit late to help with mother's funeral rites. The tree is gone along with the grave, and now he comes to ask for favors?" }
WordHunterWoW_QuestEN[84760] = { title = "A Friendly Warning", description = "Before the Devouring, the Sufaadi were priests. There were customs of courtesy and charity. Those were erased with the rest of K'aresh. If the Wastelanders think I won't retaliate, they'll never stop targeting me.\n\nI think you understand the value of a show of force. Kill their leaders--let it be a warning for the others.", objectives = "Slay Soulbinder Sabeel and Duelist Xaheen.", progress = "Hard to believe they were once priests.", completion = "Hopefully that will be enough to scare them off--at least for a while." }
WordHunterWoW_QuestEN[84761] = { title = "Toil and Trespass", description = "Fennad picked a poor time to ask for my help. I'm leaving as soon as I recover my supplies from the Sufaadi. \n\nI was passing through when they attacked, and they could have killed me if Ruya hadn't carried me off. I followed them back to Sufaad, but there are too many for me to deal with. \n\nIf you help me recover my supplies, I'll see what I can do to help Fennad.", objectives = "Recover Shahata's stolen supplies.", progress = "Hopefully they haven't used everything up.", completion = "Is this all you found? They didn't waste any time using up my supplies. Still, it's something." }
WordHunterWoW_QuestEN[84762] = { title = "We Are Our Words", description = "I had a necklace that our mother beaded. The Sufaadi took it when they robbed me. Things from old K'aresh are rare. If the Sufaadi haven't traded it, it'll be with their other valuables.\n\nI was planning to leave it behind. Sentimentality isn't worth risking your life, but you kept your word--which is more than I can say for my brother. Help me recover the necklace and it's yours.", objectives = "Help Shahata recover her mother's necklace.", progress = "What happened? Where's Fennad?", completion = "It's all gone. Months of supplies up in flames. If Fennad isn't dead already, he will be soon. The Sufaadi won't be forgiving, especially after what we've done." }
WordHunterWoW_QuestEN[84765] = { title = "Of Bonds and Boughs", description = "All that time in Tazavesh, all I could think about was coming home. Now it's only brought more grief. Even if the surveyor wasn't damaged, I still have nothing to trace back to our mother's grave.\n\n<Om'fennad glances around the cave.>\n\nSee these markings? This was a shrine to the Exchange. I guess it's a fitting place to finally say goodbye. Would you be willing to help one last time? Nothing dangerous--just light some incense.", objectives = "Help Om'fennad and Shahata honor their mother.", completion = "After all this time, I thought it would feel different when we honored the oath. \n\nMaybe now's the time to stop thinking on the past. Thank you." }
WordHunterWoW_QuestEN[84767] = { title = "Charred Celebration Crate", description = "<The crate is charred from fire, but the insides might be salvageable. Alyx would appreciate the supplies returned.>", objectives = "Return the Charred Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84773] = { title = "Crystalized Celebration Crate", description = "<The crate is crystallized and can't be pried open easily. Alyx would appreciate the supplies returned.>", objectives = "Return the Crystallized Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84774] = { title = "Lorewalking", description = "", objectives = "" }
WordHunterWoW_QuestEN[84776] = { title = "A Call to Delves", description = "There are many treasures to be found in the delves around our land.\n\nPerhaps some could be of use to you.", objectives = "Complete 5 Delves in Khaz Algar.", progress = "Beware of whatever lurks in these delves.", completion = "You've survived! Fine work." }
WordHunterWoW_QuestEN[84779] = { title = "Lorewalking: The Blade's Gambit", description = "Though now only a blade of little power, Xal'atath was not idle. In the aftermath of the Legion invasion, tensions between the Horde and the Alliance erupted into the Fourth War. \n\nXal'atath took advantage of the many forces at play in the war in a gambit to restore her power...", objectives = "Listen to Lorewalker Cho to learn the story of Xal'alath during the Fourth War.", completion = "I believe the information my fellow Lorewalkers and I have found is completely new. I am unsure of its importance, but perhaps you can decide." }
WordHunterWoW_QuestEN[84781] = { title = "Master of Secrets", description = "", objectives = "A fellow secret hunter I see! I was told to give you this. Good luck!" }
WordHunterWoW_QuestEN[84782] = { title = "Lorewalking: The Blade's Past", description = "Many years ago, a stone tablet from Stormsong Valley made its way into my library. \n\nIt took years to break the cipher and translate the fragments of runes etched into it. \n\nI will tell you what we have pieced together. A tale of yet more treachery...", objectives = "Listen to Cho to learn the story of Xal'alath in Ny'alotha.", completion = "You are chosen, pitiful though you are. Be grateful." }
WordHunterWoW_QuestEN[84784] = { title = "Lorewalking: The Blade's Nemeses", description = "Lord N'Zoth calls now upon his brethren to aid in Xal'atath's defeat. You have been chosen to make the way for them to arrive.\n\nYou know what to do.", objectives = "Activate the 3 Ritual Obelisks to summon Yogg-Saron, C'Thun, and Y'Shaarj.", progress = "Do not waste Lord N'Zoth's time.", completion = "I have no doubt Lord N'Zoth could defeat this Xal'atath without the aid of his brethren, if only she had not infiltrated us so." }
WordHunterWoW_QuestEN[84787] = { title = "The Drain", description = "", objectives = "" }
WordHunterWoW_QuestEN[84788] = { title = "Hotrocket Hot Dogs", description = "", objectives = "" }
WordHunterWoW_QuestEN[84789] = { title = "Lorewalking: The Blade's Downfall", description = "They are ready. \n\nThe Lords hold Xal'atath within the keep. You are the pebble to trigger the avalanche of their power. To end Xal'atath. \n\nGo. Join them.", objectives = "Confront Xal'atath.", completion = "What did Xal'atath's last words to N'Zoth mean? Did she foresee their future collaboration?\n\nWas it her plan from the start?" }
WordHunterWoW_QuestEN[84791] = { title = "Hotrocket Burgers", description = "", objectives = "" }
WordHunterWoW_QuestEN[84820] = { title = "By Oath and Blood", description = "After the Devouring, I didn't think I'd see Fennad again. At first, it was easier to stay angry at him for leaving than to grieve. Then it was easier to forget, to only focus on surviving the next day. Seeing him again brought everything back.\n\nOath-breaker... He had forsaken his oath to come home, but family is the first oath we're born to. What would it make me if I abandoned him now?\n\nHe's my brother--by oath and by blood. I won't leave him to the Sufaadi.", objectives = "Rescue Om'fennad.", completion = "I almost didn't expect her to come for me, especially not like that. Even so, the surveyor's damaged and Shahata's supplies went up in flames. Maybe I shouldn't have come home." }
WordHunterWoW_QuestEN[84821] = { title = "Biological Quintainment", description = "Have earned spurs, now time use them!\n\nSlimes run off with joust dummies, but that just make for moving target. Better practice!\n\nMount noble mole steed by gate, get eye with lance, ride down slime.\n\nImportant skill for any knight, yes.", objectives = "Lance target dummy carrying slimes from mole-back.", progress = "Watch out for big ones. Kick you good!", completion = "Ha! Lance just like boil, could hear pop from here.\n\nYou make good knight yet." }
WordHunterWoW_QuestEN[84822] = { title = "To Iskaara", description = "Let's get these kids back to Iskaara, eh?\n\nI'll meet you there.", objectives = "Meet Hemet Nesingwary in Iskaara.", completion = "Ah, that's better. Got them all home and settled. My thanks!" }
WordHunterWoW_QuestEN[84826] = { title = "Eco-Dome: Rhovan", description = "I will not make excuses for what we did. I will carry the responsibility of it for the rest of my existence. Alleria will come to understand why it was necessary. When she sees the power of the All-Devouring, she will understand.\n\nWe will need at least two more Reshii Ribbons to bring enough of a force to bear against Dimensius. My friend Om'bera is a holder of a ribbon. She works in Eco-Dome: Rhovan on the next island. Let us gather her to our cause.", objectives = "Meet Locus-Walker at Eco-Dome: Rhovan.", completion = "The dome is shattered and Om'bera may be in danger! I can see the scavengers from the wastelands of K'aresh within it now. \n\nOm'bera may yet live. We must find her, and her Reshii Ribbon." }
WordHunterWoW_QuestEN[84827] = { title = "The Shattered Dome", description = "Eco-Dome: Rhovan was shattered by a falling chunk of void glass, destroying the structure and scattering its caretakers. They have returned to recover whatever equipment, flora, or fauna can be salvaged before the wastes claim them. \n\nSearch the ruins to find any clues of Overseer Om'bera's fate. We must have her Reshii Ribbon! Om'resh and I will search the impact crater.", objectives = "Search Eco-Dome: Rhovan for Om'bera.", progress = "Could Om'bera still be somewhere within the wreckage?", completion = "The Wastelanders killed Om'bera and took her Reshii Ribbon. These fallen oracles have harried all members of the Ravel since the Devouring War. This is a grim day." }
WordHunterWoW_QuestEN[84831] = { title = "The Rhovan Infestation", description = "When the meteor struck, Om'bera and I tried to salvage what we could. Without the dome's shield, we were soon beset upon by scavengers of the Great Dark Beyond. We fled and were separated.\n\nSuch creatures are not of K'aresh, and hostile to the stable biomes we sought to achieve. We need to clear these invasive creatures to find our equipment, and Om'bera.", objectives = "Kill 10 invasive creatures in Eco-Dome: Rhovan.", progress = "This was once a thriving eco-dome of the Trust. Our research worked toward the restoration of K'aresh.", completion = "Thank you. Those creatures would soon overwhelm us if left unchecked.\n\nIt's amazing they can survive without the protective barrier of the dome, without becoming energy as the K'areshi did. I wonder if such resilient traits could be transferred to the few native species in our domes?" }
WordHunterWoW_QuestEN[84834] = { title = "Tempest Clefts", description = "The Wastelanders were once the oracles of the Worldsoul of K'aresh. They were so proud and strident about their oaths. Now they scavenge the ruins like animals. Even rats have their uses. \n\nGather void cleft essences for me. I have an idea of how we might sway the fallen oracles to our cause.", objectives = "Bring 6 Void Cleft Essences to Xal'atath in the Tempest Fields.", progress = "Many denizens of the Void are voracious consumers of energy. They greedily flock to pockets of coalesced energy like moths to a flame.", completion = "Well done, my champion. We shall use this to draw out our prey." }
WordHunterWoW_QuestEN[84835] = { title = "The Drowned Lair", description = "", objectives = "" }
WordHunterWoW_QuestEN[84836] = { title = "Shuddering Hollow", description = "", objectives = "" }
WordHunterWoW_QuestEN[84838] = { title = "Enemies of Enemies", description = "The Wastelanders have made camp in the ruins of old K'aresh. A sanctuary from the ravenous beasts of the Void that stalk the wastes of K'aresh. A bulwark against outsiders.\n\nIf a hostile entity were to enter their camp, you could defeat it--then they would respect you. Take the void energy you gathered into the ruined tower north of here. Be ready!", objectives = "Place the coalesced void energy in the Castigar.", progress = "You are not welcome here, stranger.", completion = "Dimensius destroyed K'aresh. Here in the wastes of Merciless K'aresh, we mete out punishment for all who failed him. You say your oaths align with ours? Let us talk." }
WordHunterWoW_QuestEN[84848] = { title = "Before the Void", description = "You've impressed these Wastelanders with your violent prowess, my champion. Well done. Now let me do my work.\n\nI know what these former oracles want. They dream of hearing the Song of K'aresh once more. I must make them believe it is possible, then pull on that string of desire. Soon we will have our army, and another Reshii Ribbon.\n\nFirst, let's return the Tabiqa ritual dagger.", objectives = "Convince Soul-Scribe to join forces.", completion = "We would gladly war against the Shadowguard. But I cannot give up this Reshii Ribbon to someone I don't trust.\n\nPromises of revenge are easy. Trust is hard won among the Wastelanders." }
WordHunterWoW_QuestEN[84850] = { title = "Serpent's Wrath", description = "", objectives = "" }
WordHunterWoW_QuestEN[84851] = { title = "Tides of Greed", description = "", objectives = "" }
WordHunterWoW_QuestEN[84852] = { title = "Legacy of the Vrykul", description = "", objectives = "" }
WordHunterWoW_QuestEN[84855] = { title = "Dead Silence", description = "Dimensius's power is so great that even shattered, his aura radiates a power debilitating to mortal life. It is why the K'areshi were changed to beings of energy--it was the only way we could survive his presence.\n\nI had hoped my scouts could find a path that was safe for you and your compatriots to enter the manaforge. Raz'ida, Lo'shah, and Yanhal should have met us by now. Find them for me. Their information is vital to our defense against the All-Devouring.", objectives = "Find the scouts at Overlook Zo'Shuul.", completion = "Raz'ida was a Shadowguard agent? I've trusted her for thousands of years. How did they break her loyalty? \n\nIf she could be turned, then any of the Trust's agents could as well. It is vital that we get the information about their base, and we can only rely upon the four of us to do so." }
WordHunterWoW_QuestEN[84856] = { title = "Where the Void Gathers", description = "With Locus-Walker's Reshii Ribbon, I can transmute your flesh to energy. It won't hurt much.\n\nYou will have the ability to travel within Dimensius's aura without being destroyed. There you can search for a path into the manaforge. You will travel in Untethered Space as a creature of energy, ignored by the Shadowguard. Their void beasts however... stay well away or be devoured. \n\nTalk to me when you are ready. Time is of the essence.", objectives = "Search Shadow Point in Untethered Space with Xal'atath's help.", progress = "We will need more than one Reshii Ribbon if we want to reach Dimensius with a force capable of stopping his emergence.", completion = "Through this, you have learned what I already knew. \n\nDimensius is a terrible threat. We must work together, <name>, if we are to survive." }
WordHunterWoW_QuestEN[84857] = { title = "Eco-Dome: Primus", description = "Xal'atath is correct. We need more than my one Reshii Ribbon to get a force to Dimensius. \n\nThere is an eco-dome south of here. The founder of the Trust is there, overseeing its operation. She acquired the domes from the Consortium. She claims they will be the key to restoring K'aresh. I am skeptical anything will be safe now that Dimensius stirs. \n\nShe was a member of the Ravel and possesses a Reshii Ribbon. Surely she would lend it to us.", objectives = "Meet Locus-Walker at Eco-Dome: Primus.", completion = "The Shadowguard attacked the eco-dome. They must covet the vast stores of energy needed to shield the delicate biomes from the Void of K'aresh." }
WordHunterWoW_QuestEN[84858] = { title = "System Restart", description = "My Reshii Ribbon is all that is keeping this dome and its systems from collapsing.\n\nThis eco-dome took too much of my fortune to build just for the Shadowguard to destroy it. They have sabotaged many of our control consoles, risking a complete ecological collapse.\n\nFind Engineer Om'loof and help him restart our environmental support system while I monitor the rest of the facility.", objectives = "Help Engineer Om'loof in Eco-Dome: Primus.", progress = "This eco-dome will fail if the environmental support system stops. We must stabilize it!", completion = "Environmental support may be back up and running, but don't get complacent. That was merely the first of the many problems plaguing this eco-dome." }
WordHunterWoW_QuestEN[84859] = { title = "Damage Report 101", description = "Just like Engineer Om'loof, I have hired more well-regarded, highly trained, expensive management consultants from cartel Om. Two of them have not reported in. Are they dead, or just distracted again? \n\nFind botanist Om'nittar and shield technician Om'door. Get their damage reports. I need to know if the attack caused any lasting damage to my dome.", objectives = "Find botanist Om'nittar and shield technician Om'door and bring their reports to Ve'nari.", progress = "I hire the best. I am sure Om'nittar and Om'door have the information I need.", completion = "Are they alive? Good. Next time they forget to check in, they won't be.\n\n<Ve'nari skims through the reports.>\n\nIt looks like there was minimal damage, if any at all, to most of the facility. The Shadowguard saboteurs were focused on rerouting our energy reserves to the outer conduits. They have ignored the environmental and secondary systems." }
WordHunterWoW_QuestEN[84860] = { title = "Eco-Stabilizing", description = "The Shadowguard attack caused chaos and disarray in this dome. Several control consoles have powered down, and my consultants are stretched thin reviving their assigned biomes and systems.\n\nThis is where you come in, {name}. It's an easy, but critical job. Find the disabled consoles and make sure they restart.", objectives = "Activate the disabled control consoles in Eco-Dome: Primus.", progress = "Are all the consoles operational? No? Go switch them on!", completion = "Good work, <name>.\n\nThe interior of the dome is stabilized. All the eco-dome systems are functioning. My investment in the eco-domes will continue to pay dividends. Unless the Shadowguard attack again." }
WordHunterWoW_QuestEN[84861] = { title = "This Is Our Dome!", description = "We may have driven the saboteurs out of the dome and repaired its systems, but that doesn't mean the Shadowguard is done with my domes. They're still hiding at the perimeter, trying to find a way to harvest the vast amounts of expensive energy needed to power the eco-dome.\n\nI need you to fight them off. Then maybe this attack will truly end.", objectives = "Kill 7 Shadowguard around Eco-Dome: Primus.", progress = "Did you get them all? Or are there still Shadowguard hiding around the perimeter, damaging my dome?", completion = "Good. That will buy us enough time to secure this dome." }
WordHunterWoW_QuestEN[84862] = { title = "Void Alliance", description = "We can't have you patrolling the perimeter of this dome, like the city watch fighting attackers in perpetuity. We need a permanent solution so we can continue with our noble quest.\n\nTake these crystals. They've been attuned to the eco-dome's defense magics. Just place them near strategic parts of the perimeter to strengthen the magical defenses.\n\nWhat? This time it's no trick. If this dome explodes, I'll never get to destroy Dimensius.", objectives = "Place 4 Xal'atath defenses around Eco-Dome: Primus.", progress = "Have you placed the crystals I gave you? Ve'nari won't give up her ribbon until her dome is secure.", completion = "That should secure this dome. But will Ve'nari make us float through any more hoops?" }
WordHunterWoW_QuestEN[84863] = { title = "Counter Measures", description = "I cannot relinquish my Reshii Ribbon just yet, {name}. Not while the Shadowguard assaults my eco-dome from their camp in Serrated Peaks. Take the fight to them! If you decimate their forces, they will stop this assault. \n\nBring Locus-Walker's apprentice, Alleria. She looks like she knows how to handle herself in a fight. She also keeps staring daggers at the Harbinger, and I don't have time to play peacemaker between those two.", objectives = "Kill 12 Shadowguard forces in Serrated Peaks.", progress = "The Shadowguard are still attacking. Did you decimate their numbers yet?", completion = "Good job, <name>. That should satisfy Ve'nari." }
WordHunterWoW_QuestEN[84864] = { title = "Her Dark Side", description = "An ethereal army runs on its energy siphons. Interrupt the flow of energy by destroying their siphon tower, and the army will pull back. It's one of their weaknesses as minions. Normally I wouldn't share the secrets of their defeat, but they betrayed me and will forever live with the consequences.\n\nThe siphon has a control console that can be overloaded to collapse the system. It will be shielded by a void barrier. Alleria can remove it for you.", objectives = "Destroy the Ethereal Siphon in Serrated Peaks.", progress = "Now the Shadowguard will have to retreat.", completion = "I feel like there is something Locus-Walker and Ve'nari are keeping from me. Some secret during the Devouring War that they don't want me to know. Xal'atath is pulling on this doubt to manipulate me. \n\nLet's defeat the Shadowguard, then we can uncover the truth." }
WordHunterWoW_QuestEN[84865] = { title = "Divide and Conquer", description = "Of all the assets on the field of battle, the troops are the most expendable. I've sent enough to their destruction to know this as a fact. If we are to safeguard this dome for Ve'nari and get her Reshii Ribbon, we should destroy their cannons.\n\nThose cannons are easily worth the lives of all of their soldiers. Destroy them and their commanders will sound the retreat. Most field commanders would never admit this as it's bad for morale, but you seem like the type that can handle uncomfortable truths.", objectives = "Destroy 3 Shadowguard Cannons in Serrated Peaks.", progress = "Taking out these cannons will force the Shadowguard's retreat. I would not listen to Xal'atath's ideas on ethics of command, though.", completion = "Without their cannons, the Shadowguard's attacks on the eco-dome are doomed to failure. Ve'nari won't have need of her Reshii Ribbon. \n\nI'm more and more unsettled by this plan of ours, though--the secrets... this Alliance with Xal'atath... I fear Locus-Walker made a mistake thousands of years ago, and we cannot escape that ancient mistake." }
WordHunterWoW_QuestEN[84866] = { title = "To Purchase Safety", description = "I need to focus on the mission. Regardless of my doubts about our companions, the Shadowguard are a scourge. We should slay their Shadow-Captain so they cannot easily return to Eco-Dome: Primus. Ve'nari would lend her Reshii Ribbon to our cause, and we would discover if my trust in Locus-Walker was well placed.\n\nI will not let my doubts stay my bow on the battlefield, {name}. You can trust me to hunt these followers of Dimensius.", objectives = "Kill Shadow-Captain Lakheesh.", completion = "With that necessary violence taken care of, the three of us can talk. You are correct, Alleria. Great secrets have been kept from you. Secrets that were not mine to reveal but should have been revealed to you years ago." }
WordHunterWoW_QuestEN[84867] = { title = "Stalking Stalkers", description = "I've planted the seed, yet Soul-Scribe still hesitates. Her daughter Narathe is more receptive. She might be able to give us the nudge that's needed to win the Wastelanders over. Daughters are useful.\n\nGo with Narathe. Win over their tribe. I will stay here and continue to work on Soul-Scribe's will.", objectives = "Find a way to sway the Wastelanders.", progress = "I will do what my oaths dictate, but I am not convinced that your plan is the way to go.", completion = "Word has filtered up through my camp about what you have done for us. My daughter has always been too trusting, but your efforts do not go unnoticed." }
WordHunterWoW_QuestEN[84868] = { title = "A Whiff of Help", description = "You seem quite equipped for solving secrets now! As much as I expect Maru would want to come with you, she's far too young.\n\nFortunately, we Tuskarr have an incense that lets our souls communicate across long distances.\n\nI keep a stock of it on me if you need. As a friend of Maru, I will only charge you for the cost of materials.", objectives = "Purchase and use a Spiritual Incense from Benatauk.", progress = "Have you tried the incense?", completion = "Now you see the power of our spiritual connections.\n\nHere, take a few with you." }
WordHunterWoW_QuestEN[84869] = { title = "Hunting on Glass", description = "Violent scavengers of the Void have been drawn to Dimensius's aura to feast upon the scraps he will leave behind. This presents a problem for our Wastelander friends. Scavenging is their job.\n\nThey could handle these beasts--I would not be seeking to ally with them if they couldn't. But why not give them a gift, and show them you are their equal--no, their superior in combat?", objectives = "Kill 4 Void Terrors and 8 Unreal Observers.", progress = "Dimensius's power grows and the Wastelanders are feeling the pinch. Let us ease the pressure for them a bit.", completion = "These Wastelanders respect strength and violence. I think we're going to get along quite well." }
WordHunterWoW_QuestEN[84876] = { title = "The Oasis", description = "Soul-Scribe would fight for us, even die for our cause. Yet she still denies us her Reshii Ribbon. She sees it as a tool of the Ravel, and her oaths are getting in the way of our mission.\n\nIf she could feel the presence of the Worldsoul K'aresh once again, she would give anything to protect him--even the ribbon. The Oasis is the Trust's eco-dome that has a stable biome. The perfect place to commune with a Worldsoul, if one still exists.", objectives = "Meet Xal'atath at the Oasis eco-dome.", progress = "Our research here is essential to the future of K'aresh. That we have stabilized this area means that we can replicate this feat in other domes--perhaps even heal the shattered remains of K'aresh.", completion = "This is most irregular. Ve'nari may have asked that we extend all courtesy to the Harbinger and her champion. But these Wastelander barbarians? \n\nI hope Ve'nari knows what she's doing." }
WordHunterWoW_QuestEN[84879] = { title = "Restoring Hope", description = "This dome is a reasonable facsimile of K'aresh. We will find no better place for Soul-Scribe to hear the Worldsoul's song. \n\nAnd yet, as Dimensius grows in power, even the Oasis succumbs to the Void. I can feel the rifts tearing open. Their energies will disrupt this delicate ritual. Unfortunately they'll need to be closed so Soul-Scribe can be convinced.", objectives = "Cleanse the eco-dome of invasive elements.", progress = "The Void creeps further and further into K'aresh every day. Dimensius's power grows ever stronger.", completion = "We have a lot riding on this Tabiqa ritual going exactly to plan. Having to kill her to get her ribbon would be inconvenient." }
WordHunterWoW_QuestEN[84882] = { title = "Deck Dismay", description = "Gather up the cards that got scattered around the area and I will be forever grateful!", objectives = "Collect the missing cards.", progress = "How's it going? Have you found all my missing cards?", completion = "You've found them all? Thank you so much! I'm forever in your debt!" }
WordHunterWoW_QuestEN[84883] = { title = "K'aresh That Was", description = "The Tabiqa has not been attempted for thousands of years. It was clear that the Devouring War destroyed K'aresh.\n\nAnd yet, looking at this dome... they have recreated so much that I thought lost forever--fresh water, clean air, even the zaranit flowers I thought extinct. Does the Harbinger speak the truth?\n\nNo. I didn't break my oath and abandon the Worldsoul. K'aresh is gone.", objectives = "Gather materials for the ritual.", progress = "Did you find the components for the Tabiqa ritual? Do they even still exist?", completion = "To hold these blossoms in my hands again... I never thought I would see the day." }
WordHunterWoW_QuestEN[84885] = { title = "Working for G.E.T.A.", description = "Attention: Protect the Citizens of Undermine AND get paid!\n\nProfit-seeking bounty hunters encouraged to check in at the local G.E.T.A. office for more information.", objectives = "Inquire at the local G.E.T.A. office in the Vatworks", progress = "Do you need something, <name>? I don't have time for idle chit-chat.", completion = "Both G.E.T.A. and the citizens of Undermine are willing to pay for your services and your discretion." }
WordHunterWoW_QuestEN[84891] = { title = "G.E.T.A. The Radioactive Rat", description = "We got a report here of some big, radioactive rat that was chased into a nearby sewer. Not only is it highly aggressive, it's terrible for the environment.\n\nHey, don't look at me like that. Us Underminers care about that stuff even if the big cartels don't.\n\nI put the location of the sewer entrance on your map. Hopefully, one of these lunks will get off their butts and join you there.", objectives = "Defeat the Radioactive Rat", progress = "Once you're finished, come back here, and I'll make sure you're adequately compensated.", completion = "I haven't seen a rat that big since... actually, I don't think I've seen a rat that big before. Well done." }
WordHunterWoW_QuestEN[84892] = { title = "G.E.T.A. The Crocodilian", description = "Did you know that crocodiles can grow indefinitely?\n\nWell, the owner of this crocodile didn't. And when it got too big, it was released. Normally these crocodiles make their way out of the Undermine. But this one decided it liked the taste of goblins and stayed.\n\nIf you're up for it, the people of Undermine could use someone brave to face it. Are you game?", objectives = "Defeat the Crocodilian", progress = "Who's afraid of a big ol' croc, you say?", completion = "It's done then. The people of Undermine won't realize what you did, but I do. Thanks from all of us." }
WordHunterWoW_QuestEN[84893] = { title = "G.E.T.A. The Captain", description = "This is a unique one. \n\nSome cave skippers got into the Undermine sewers and are starting to populate, causing all sorts of problems. It looks like an especially big one is organizing them somehow.\n\nWe've taken to calling him \"the Captain.\"\n\nMake sure his reign of finned, eye-bulging terror ends today.", objectives = "Defeat the Captain", progress = "Be careful, <name>. From what we can tell, The Captain doesn't work alone.", completion = "I've never thought of cave skippers as overly dangerous or organized. Looks like there's a lot about them we don't know." }
WordHunterWoW_QuestEN[84894] = { title = "G.E.T.A. 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[84896] = { title = "The Next Dimension", description = "By the Songs of K'aresh, I will join you to face the Shadowguard and Dimensius in battle. Let those that would prey on Untamed K'aresh fear his followers!\n\nMy scouts have tracked your comrades setting a foothold in Shadowguard territory. They will need our assistance. \n\nK'aresh lives! Our cause is just! Our oaths are unbroken!", objectives = "Meet with Soul-Scribe in Shan'dorah on K'aresh.", completion = "I did not know there were this many void-touched from your world. How do they shield their souls from its madness?" }
WordHunterWoW_QuestEN[84897] = { title = "The Calm Before We Storm", description = "Narathe is right. We are fortunate that void elves have experience battling the Shadowguard. The wastes of K'aresh are merciless, and the battle to come will be as well. I hope they are prepared for a brutal fight. These will not be the scattered scouts they are used to fighting on Telogrus.\n\nYou should ensure they are ready for the battle to come.", objectives = "Check in with Alleria and the void elves at Shan'dorah on K'aresh.", progress = "We have spent a long time preparing for this moment. I will not let it slip.", completion = "These elves are more resilient than I thought. Perhaps our people have both been tempered by adversity?" }
WordHunterWoW_QuestEN[84898] = { title = "The Sands of K'aresh", description = "My people have fought across every inch of the ruins of our world. We gave our oath to King Salhadaar and he rewarded us by sending the Shadowguard to hunt us down.\n\nSalhadaar is long dead, but we knew the Shadowguard would return. In the long years that followed, we secreted caches of weapons so we would always be able to raise a blade in defiance.", objectives = "Collect 3 Weapons Caches from the nearby sands of the Shatter Gorge on K'aresh.", progress = "Have you gathered all of the weapons caches in the sand?", completion = "These will do. They are still as sharp as ever. I will arm my people and your allies. For K'aresh, <name>." }
WordHunterWoW_QuestEN[84899] = { title = "Shadowguard Diffusion", description = "With or without Xal'atath, the Shadowguard have long been a thorn in my side. It would be wise to take out as many as we can on this rock. I still do not trust her, but we must focus on the enemy we can defeat right now.\n\nDo not relent, {name}. If you see any Shadowguard, cut them down. A battle against them today saves us a battle against them tomorrow.", objectives = "Defeat Shadowguard in the sands of the Shatter Gorge surrounding Shan'dorah on K'aresh.", progress = "We still have many to defeat before we can progress.", completion = "Well done, <name>. If the Shadowguard bled, I am certain the sands would be soaked.\n\nMany more lay before us on the path to victory. There will be time for celebrations yet." }
WordHunterWoW_QuestEN[84900] = { title = "Like a Knife Through Aether", description = "Very good, my champion. You are a swift and sharp blade of destruction.\n\nWe will put all that power to use now. We will slaughter the Shadowguard that seek to raise Dimensius, and the machines created to feed his insatiable hunger. \n\nThe Shadowguard must have a Reshii Ribbon among their spoils. As we destroy their garrisons, look for this final ribbon. It is our way forward to kill a Void Lord.", objectives = "Stop the Shadowguard ethereals at Shadow Point: Darkmend in K'aresh.", progress = "A few more of these and we might even have a chance. Do not relent, <name>. You are capable of this and so much more.", completion = "Two more to go. Two more places for the ribbon to be hidden." }
WordHunterWoW_QuestEN[84901] = { title = "[DNT] CH04Q05p", description = "Priest unique quest, do the same objective but mind control an enemy who will help you kill them first.", objectives = "" }
WordHunterWoW_QuestEN[84902] = { title = "Adverse Instantiation", description = "Turning into beings of energy was a choice we made when we had no other option. In the time since then, we have become reliant on consuming energy to survive. \n\nThe Shadowguard are feeding that power to Dimensius. His hunger is infinite, and he will drain the energy from K'aresh to fuel his re-emergence. We must destroy this machinery that feeds him, {name}.", objectives = "Disable 6 Shadowguard Power Pylons in Shadow Point on K'aresh.", progress = "Are they all dealt with?", completion = "My people's technomancy could be put to great and beneficial use, yet time and time again we use it for great evil. As Dimensius's power grows, we are all diminished." }
WordHunterWoW_QuestEN[84903] = { title = "Until the Sands Bleed Void", description = "I have fought Shadowguard on Eredath, Telogrus, and now on K'aresh. They are a thorn that should be plucked from the cosmos.\n\nThat they should follow the very monster that threatened their world proves they are a scourge. Though, perhaps I am no better, fighting alongside Xal'atath. \n\nI will grapple with that contradiction later. For now, I intend for us to put an end to them, {name}.", objectives = "Kill Shadowguard in Shadow Point on K'aresh.", progress = "Spare no remorse for their kind. They would do far worse.", completion = "Is this the fate of the ren'dorei? Given long enough, will we too serve the very forces we fight today? I had always looked to Locus-Walker as an example we can emulate, but it appears the ren'dorei must find their own path." }
WordHunterWoW_QuestEN[84904] = { title = "And We Will Answer", description = "This is unthinkable. Heretical!\n\nThe Shadowguard have captured my warriors and are converting them into new troops for Dimensius--forcing an oath to serve the All-Devouring as the Void fills their being.\n\nFree them, {name}. We cannot let this last any longer. I will send Narathe to aid you in this fight. She knows how to untether the souls of oath-breakers.", objectives = "Rescue Captured Wastelanders in Shadow Point on K'aresh.", progress = "Once an ethereal embraces the shadow, they are lost forever.", completion = "How many were lost, do you think?\n\nI have a duty to my people. Let us finish this so none are forced to serve the All-Devouring again." }
WordHunterWoW_QuestEN[84905] = { title = "To Walk Among Shadow", description = "We must continue disabling or destroying these buildings. I am loathe to destroy the technology of my people, but when used for such dire purpose, there is no choice!\n\nFrom here on out, hold nothing back. Let us raze the works of the Shadowguard.", objectives = "Help Locus-Walker disable Shadow Point: Torment at Shadow Point on K'aresh.", completion = "There is only more darkness ahead of us. Be prepared for anything." }
WordHunterWoW_QuestEN[84906] = { title = "Nexus Regicide", description = "Now is the time, {name}.\n\nWe must not hesitate. They will send their strongest to defend this last manaforge. We will find Nexus-Prince Azir there and we will end him before we take this battle to Dimensius. Xal'atath or no Xal'atath, we have what we need to do this. Just one final kill. \n\nLet us not dally. Make haste.", objectives = "Defeat the leader of the Shadowguard in Shadow Point: Apotheosis on K'aresh.", completion = "Hmmph.\n\nI grow tired of this lesson, <name>. Always when we get close to someone they betray us. They falter. They turn. They die. Always we put them in danger and we fail to protect them.\n\nLet no one else stand in our path. You and me, <name>. We will finish this." }
WordHunterWoW_QuestEN[84908] = { title = "Stormrider's Honors", description = "<A golden missive finds its way to you.>\n\nChampion, though you are no Stormrider, you may yet be worthy of the Stormrider's armor.\n\nFind Stormrider Bruelda if you wish to claim this honor.", objectives = "Speak with Stormrider Bruelda in Dornogal.", completion = "What is it?" }
WordHunterWoW_QuestEN[84909] = { title = "Ghostly Celebration Crate", description = "<The crate emits a ghostly glow, and you can't help but feel the presence of mysterious spirits. Alyx would appreciate the supplies returned.>", objectives = "Return the Ghostly Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more, please bring them to me." }
WordHunterWoW_QuestEN[84910] = { title = "The Tabiqa", description = "My followers long for the days when they were oracles. They yearn to hear the Song of K'aresh. I am a realist. The evil of the Ravel, of Dimensius--they have destroyed the beauty that was our Worldsoul.\n\nBut you have gathered the items for the Tabiqa. So I will attempt it. When I hear the void of K'aresh's absence, there will be consequences.", objectives = "Help Soul-Scribe with the ritual.", progress = "It has been too long since we were this close to K'aresh. It is but an echo of what once was, but the memories that it brings back...", completion = "And the pieces fall together. Perhaps we have enough strength to take on the Shadowguard, my champion.\n\nLet me tip the scales further. With the power of these Reshii Ribbons,  I will infuse these Reshii Wraps with enough to empower you to explore Untethered Space... and gather strength for the fight ahead.\n\nYou're welcome." }
WordHunterWoW_QuestEN[84912] = { title = "The Show Must Go On", description = "Thank you for coming! We've had a bit of a mishap with the script and various stage props.\n\nThey've all gone missing! It seems as though a prankster has decided to make a mockery of our productions and scattered several needed items throughout the area.\n\nAt least the prankster was somewhat considerate and left us some clues as to where we can find the missing items. Do you think you can solve the riddles?\n\nAnd please, do not carry any open flames or shine any bright lights while in our theater.", objectives = "Help Dapperdew at the Amphitheater in Ardenweald.", progress = "Use the play list to find the missing items in the area.", completion = "The theater thanks you for your valiant efforts this day!" }
WordHunterWoW_QuestEN[84914] = { title = "Valorstones", description = "", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nNo, this candle not made from earwax. Made from beeswax! Smells so nice! You like nice smells, yes? If not, might want to step away from me, ha ha ha. Sorry." }
WordHunterWoW_QuestEN[84915] = { title = "Clearing the Dunes", description = "The deserts here were never safe, but there was still beauty--birdsong, herds of animals, and the desert would bloom from horizon to horizon after a storm.\n\nNow it's a wasteland. I barely took two steps off the docks before being chased by some monster. I need to get out there. If you could cull the worst of those creatures, I'd feel much safer.", objectives = "Slay 8 dune creatures.", progress = "Is it safe yet?", completion = "It seems only the most vicious creatures survive outside of the eco-domes. When we find my sister, I'll bring her back to Tazavesh where it's safe." }
WordHunterWoW_QuestEN[84923] = { title = "A Bird's Tale", description = "I've heard that Reshad has a new story to tell involving his bird companion, Percy. Speak with him if you would like to discover the tale.", objectives = "Find Reshad near the stage.", completion = "Hello there. Are you interested in Percy's tale?" }
WordHunterWoW_QuestEN[84924] = { title = "A Bird's Tail", description = "I've told many tales in my days, but my companion Percy has a tale of his own to tell. Would you care to learn about it?\n\nI will give you a clue on where to start. From there, you must find the clues that Percy has left behind to discover his story.\n\nYou can have this feather that Percy left behind as well. Look closely and you may find more clues. Perhaps a bird of your own may help you on your journey.", objectives = "Learn about Percy's adventures by finding his feathers.", progress = "Have you discovered Percy's tale?", completion = "Ah, you have returned. Let me see the clues you found...\n\nMy, what a busy bird. Percy arrived at Frostfire Ridge from a ship, where you found one of his feathers.\n\nNext, he traveled through Nagrand to Shattrath City, where it appears he may have faced some conflict!\n\nAnd finally he arrived at the Spires of Arak, where he met up with me. What an adventure for our friend!" }
WordHunterWoW_QuestEN[84925] = { title = "Rallying All Rapscallions!", description = "Come one, come all, straight to Dornogal!\n\nIn addition to the usual selection of powerful equipment offered at the Contender's Gate, aspiring combatants and proven gladiators can purchase heraldry tokens which can be used to craft equipment certified for use in arenas and battlegrounds!\n\nPresent this brochure to Hotharn to receive a few of these, on us!\n\n- Aisha", objectives = "Deliver the advertisement to Hotharn at the Contender's Gate in Dornogal.", completion = "Ah, I was beginning to wonder when the eager fighters were going to show up. \n\nHere you go, as promised. Use these when submitting Crafting Orders or when crafting your own equipment. The result will be just as powerful as what Lalandi sells over there, but these are great when you're looking for something customized to your liking. If you need more, you know where to find me.\n\nQuestions? Take them to the Forgegrounds." }
WordHunterWoW_QuestEN[84929] = { title = "Lifeguard On Duty", description = "", objectives = "" }
WordHunterWoW_QuestEN[84932] = { title = "A Legacy of Destruction", description = "Adventurer! A dragon whelpling recently showed up in the pet playground and has been causing all sorts of chaos.\n\nCould you go talk to him and see if you can sort out the issue?", objectives = "Find the dragon whelpling at the pet playground.", completion = "Raawwwr! I will burn EVERYTHING!" }
WordHunterWoW_QuestEN[84933] = { title = "From Ashes to Wisdom", description = "I will become the great and powerful Deathwing! Cower before my strength!\n\nYou there! Do you wish to join me, the next Deathwing, on an epic adventure?", objectives = "Show Voidfire the destruction of Deathwing.", progress = "I want to get followers to do my bidding! Like a cult!", completion = "Ok, I guess burning things, flooding things, and forming cults isn't as fun as it sounds... Everything that Deathwing affected is just desolate and not as fun afterwards.\n\nI'll be more like Nozdormu! He's cool and has time travel stuff!" }
WordHunterWoW_QuestEN[84934] = { title = "A Dark Descent", description = "I realize what I'm proposing is just this side of mad. The realm of death isn't the sort of place we're supposed to be able to just visit.\n\nBut these visions that are plaguing my family... Mother's led to the destruction of Dalaran. What if Silvermoon is next? I can't afford to risk any complacency. And if there's anyone, living or otherwise, who might be able to speak to Silvermoon's defense...\n\nWell. Here goes nothing. See you on the other side?", objectives = "Venture forth into the Maw." }
WordHunterWoW_QuestEN[84935] = { title = "Excising the Incursion", description = "The Devouring Host must have somehow followed us here.\n\nI don't know what they could want with a place like this, but I can't imagine the Void is suddenly infused with benevolent purpose. We can't allow this incursion to get out of hand.\n\nSlay as many of them as you can manage. Enough to thin their numbers, at least.", objectives = "Slay aberrations of the Devouring Host in the Planes of Torment.", completion = "We've made a dent, but at the rate they're pushing forward, they'll overrun the whole Maw." }
WordHunterWoW_QuestEN[84936] = { title = "To Cleanse Shadow's Stain", description = "These monstrosities certainly wasted no time once they arrived. They are snatching up souls left and right and drowning them in void magics.\n\nTake my holy symbol. It should be potent enough to drive away the shadows that cling to any lingering souls.", objectives = "Use the Redeemer's Sigil to cleanse voidwarped souls in the Planes of Torment.", progress = "Are the souls here just convenient targets? Or are they what drew the Host here to begin with?", completion = "I could see the reactions from the cleansing from here. I had no idea my methods would be so ill-suited to saving the souls of this place." }
WordHunterWoW_QuestEN[84937] = { title = "Distant Echoes", description = "Can you hear it? There's a strange sound echoing in the distance. Given where we are, I would assume it's a trick. Or worse, a trap. But it feels...\n\nI don't know how to describe it, but I feel calmer for hearing it. Like I'm in control.\n\nThis is going to sound mad, but I think--I think we should follow it. I don't know where it could be coming from, but my instincts are telling me to trust it. We should follow its trail.", objectives = "Find the source of the strange melody.", progress = "<Sylvanas eyes you up and down. She says nothing.>", completion = "Honestly, I should have known this was your doing. You have a remarkable talent for disturbing the peace. I almost have to respect it.\n\nI did not, however, expect to see my nephew. Not in a place like this.\n\nNo matter. So long as you are here, you can help clean up the mess you've made." }
WordHunterWoW_QuestEN[84938] = { title = "Chaos Control", description = "These are no mere embodiments of Void. They move with precision and purpose. They have taken up a defensive position within the Tremaculum. No doubt they intend to expand their presence and shore up their defenses, now that they have a foothold.\n\nAll the better. It means they will all be gathered in one place.\n\nBreak their ranks. Show no mercy.", objectives = "Stem the tide of the Devouring Host within the Tremaculum.", progress = "I don't have to tell you how dangerous it would be to let outside forces meddle in the Maw for overlong. We need to excise them sooner rather than later.", completion = "You're as sharp as ever. And here I was worried years of peace might dull your wits.\n\nCome. We're not finished yet." }
WordHunterWoW_QuestEN[84939] = { title = "Mad Space", description = "It doesn't matter how many of these void monstrosities we kill. We have to deal with the source, or they'll just keep coming.\n\nTraveling across the rift is not an easy feat in the best of times. If we can find the places where they've been able to tear through and close them, then we should be able to cut off their reinforcements.\n\nLead the way. I'll be at your back the entire time.", objectives = "Collapse 5 Unstable Void Rifts.", progress = "This place is swarming with servants of the Void. Stay on your guard.", completion = "In a way, this is an important lesson. A true paladin can't just fight darkness when it deigns to manifest. They have to seek the source." }
WordHunterWoW_QuestEN[84940] = { title = "Friendly Competition", description = "See, Ricket offered to dig it up, but the Arathi expedition lady didn't seem too keen on that.\n\nGave 'er an earful. Could hear it from the airship. Yeesh.\n\nBargus, the earthen \"ordinant\"--whatever that means-- proposed scanning the crystal to help us \"understand it better.\"\n\nI don't need to understand it. All I need's my cut. But I'm fine layin' low and doin' what they want. \n\nGo talk to Bargus at the earthen camp. See how they're comin' along an' if we can help.", objectives = "Seek out Bargus in the camp.", completion = "<Bargus looks up from his anvil.>\n\nAnother new arrival. \n\nHere to lend a hand to our efforts?" }
WordHunterWoW_QuestEN[84941] = { title = "Cave Barging", description = "Unless it is a convergence of coincidence, whoever these large outlanders are, they appear to also be interested in the crystal's signal--and the location of its origin.\n\nWe earthen do not often take stock in coincidences.\n\nEngage your defense protocols, {name}. \n\nThese outlanders are not hospitable like your people.", objectives = "Find the source of the energy signature.", completion = "<Bargus looks around the crumbled ruins in the cave.>\n\nThe crystals on that tablet...\n\nIf those small crystals are the source of the new energy signature, then why do they give off a stronger reading than the larger facet on the surface?\n\nThere is something else here we are missing..." }
WordHunterWoW_QuestEN[84942] = { title = "The Final Hazard", description = "With their lesser rifts closed, the Devouring Host will be hard-pressed to muster any reinforcements. But if we don't deal with their leader, then they'll just open more.\n\nAbove, in the parapets... There's no mistaking it. I can feel a force of Void drawing everything toward it, even all the way from down here. That's where we'll find our mark, without a doubt.", objectives = "Slay the Living Gateway atop the Tremaculum.", progress = "All that's left to do is deal with their commander.\n\nI just really wish he'd picked a slightly lower vantage.", completion = "The bulk of the lingering threat is bound in the Tremaculum. With their commander slain and their portals shut, the natural denizens of the Maw should see to the remainder soon enough.\n\nNow begone. I have work to do." }
WordHunterWoW_QuestEN[84943] = { title = "The Long Vigil", description = "If you and Arator desire something of me, it will have to wait. There are souls here that require my attention, assuming your bumbling hasn't driven them off.\n\nI've managed to track four souls that fell into the Maw without proper judgment. Correct your mistakes and help me to retrieve them, and perhaps I will find time for a chat.", objectives = "Find and calm four lost souls in the Planes of Torment.", progress = "I take my penance seriously, Maw Walker.\n\nUnlike you, apparently. Find the souls or get out of my sight.", completion = "I see that look in your eyes. Did you think this would be a simple matter? Not all are willing or ready to be retrieved.\n\nIt matters not. They persist, and they choose. Sometimes, that is enough to ease the pain." }
WordHunterWoW_QuestEN[84944] = { title = "Preludes and Preparations", description = "As you are no doubt aware, ferrying souls beyond the bounds of the Maw is no easy task. This is not a place from whence souls are meant to ascend.\n\nOur resources are limited, but I have devised a way to ensure the relative safety of the souls I retrieve--though I will require materials. Fetch for me the reeds that grow in the silt of the Gorgoa River, soulthread from the cloaks of the wandering specters, the hide of a soul-eater... Ah. And mawrat teeth.\n\nWe mustn't forget the mawrat teeth.", objectives = "Collect Gorgoa Reeds, Soulthreads, a Pristine Soul-Eater Hide, and 50 Mawrat Teeth.", progress = "Have you gathered the reagents?", completion = "It's strange. I don't know how to put it, but seeing Sylvanas like this... In a way, it's how I always imagined her.\n\nI know this is meant to be penance. And it's certainly not easy. But she seems at peace, like this." }
WordHunterWoW_QuestEN[84945] = { title = "Repent of the Highborne", description = "The reagents are gathered, and the lingering souls have been put at ease for the moment.\n\nWe do not have long. Stand back, while I send them to where they are meant to dwell.", objectives = "Observe the Ritual of Sending.", progress = "<Sylvanas stands silently.>", completion = "It is done.\n\nThere will be more tomorrow, and tomorrow. Until only I remain." }
WordHunterWoW_QuestEN[84946] = { title = "Returning to Life", description = "When I decided to come here, I have to admit that I wasn't sure what I would find. There's no disputing the terrible things that Sylvanas has done, and it's a burden that she will have to bear for the rest of her days.\n\nBut seeing her, like this...\n\nCome. We've been here too long as it is. The weight of this place is starting to get to me.", objectives = "Return to K'aresh.", progress = "Let's make haste. We don't belong here.", completion = "<Arator lets out a large sigh of relief.>\n\nIt's like I can finally breathe again. I can scarcely believe that you're able to traverse that place for extended periods of time. And here I thought Uncle Khadgar was exaggerating, in all his grand tales of your adventures." }
WordHunterWoW_QuestEN[84947] = { title = "Determination", description = "Hold a moment.\n\nArator will be fine for a few moments longer. Let him travel alone for a moment.\n\nI wish to speak to you. Privately.", objectives = "Speak with Sylvanas.", progress = "It would be unwise to linger here.", completion = "Needless to say, you and I have not always seen eye to eye. All the same, I owe you thanks. Arator is a naive fool, but he is family.\n\nNow go. See to it that he returns home safely." }
WordHunterWoW_QuestEN[84948] = { title = "Contract Work", description = "", objectives = "" }
WordHunterWoW_QuestEN[84949] = { title = "The Eleventh Hour", description = "It's high time we got back to Azeroth. I think we've done all we can do when it comes to mustering the Windrunners for whatever is to come.", objectives = "Return to Vereesa in Dornogal.", progress = "We should get going. I've done enough dimension-traveling for one day, I think.", completion = "Thank you for accompanying me on this adventure, <name>. It got a bit out of hand, but I think it was worth making all the same.\n\nI hope that the warnings we dispensed were enough. Now that Xal'atath has her army and the power of a Void Lord, I can only imagine what terrors she is planning to enact." }
WordHunterWoW_QuestEN[84955] = { title = "Contraband Banned", description = "", objectives = "" }
WordHunterWoW_QuestEN[84956] = { title = "A Shadowy Invitation", description = "{name},\n\nI've received word from my mentor, Locus-Walker. He warns of a Shadowguard plot that requires our aid. I wonder if he has finally tracked down Xal'atath.\n\nCome to the Foundation Hall in Dornogal. We must speak immediately.", objectives = "Meet Locus-Walker at the Foundation Hall in Dornogal.", completion = "The Shadowguard will stop at nothing to revive the Void Lord, Dimensius. And we should be concerned--my home was sundered by the monster. It is no mystery on how things will end if it is not stopped.\n\nHowever, I have been working on a plan... a contingency really, and it is now time to put it into motion." }
WordHunterWoW_QuestEN[84957] = { title = "Return to the Veiled Market", description = "I have been retained by the K'aresh Trust--a coalition of both broker and ethereal cartels who seek to reclaim K'aresh. The Trust is in desperate need of one of your skills, {name}.\n\nThe Shadowguard assaults our city and threatens the work of the eco-dome project.\n\nPlease accompany me.", objectives = "Accompany Locus-Walker and Alleria to Tazavesh.", completion = "Welcome to Tazavesh, both of you.\n\nWe have much to discuss. Your assistance is crucial, as always." }
WordHunterWoW_QuestEN[84958] = { title = "Beasts Unbound", description = "I am Ta'ka, supplier of rare creatures destined to repopulate my homeland.\n\nAt least, I was until some of them escaped their translocation cages! This cannot stand!\n\nThese creatures are vital. If you could assist me with capturing them, I'd be quite appreciative.\n\nEngage them in combat and subdue them. The capture device I've provided will automatically translocate them back to my care once they are on the verge of defeat.", objectives = "Defeat escaped creatures in Tazavesh to return them to Ta'ka.", progress = "Have you finished capturing the escaped beasts?", completion = "You've returned them! Excellent work. \n\nHere is your reward, as promised." }
WordHunterWoW_QuestEN[84959] = { title = "Lost Lines of Defense", description = "This is not a good day! Not at all. My whole shipment of barrier projectors was ransacked! Most of them are gone, and it seems whatever the culprits didn't take, they destroyed.\n\nThese barrier projectors are essential for securing the wild places on K'aresh, and even the city of Tazavesh. Our efforts are in jeopardy!\n\nPlease, if you can find any of my shipments it would help us get our efforts back on track.", objectives = "Collect 8 Stolen Barrier Projectors for Ba'ver.", progress = "Have you located my barrier projectors?", completion = "Excellent! With these projectors, we can once again secure our homeland. \n\nAnyway, you have my thanks for your assistance." }
WordHunterWoW_QuestEN[84960] = { title = "The Darkness Among Us", description = "Alleria, {name}... Have you sensed it? The Void lingers in all of this. Whoever is pulling the strings is cloaked in shadow, hiding from us.\n\nCome, let's seek them out and drag them into the light before they strike.", objectives = "Investigate the Void Presence and locate the culprits behind the many troubles in Tazavesh.", progress = "We need to find the hidden Shadowguard, <name>.", completion = "The Shadowguard! Of course those void-addled fools are behind this. I should have known." }
WordHunterWoW_QuestEN[84961] = { title = "Barriers to Entry", description = "Those barrier projectors we recovered? We need them now. Place them at key points to reinforce the city shield and block more portals from forming.\n\nMove swiftly, {name}. This may be our only chance to stop the Shadowguard from flooding in.", objectives = "Place 8 Barrier Projectors around Tazavesh.", progress = "Did you place the barrier projectors? We need to slow down the invasion. Quickly!", completion = "Well done. The shield around the city looks stronger already. \n\nThat should buy us some time against the Shadowguard." }
WordHunterWoW_QuestEN[84962] = { title = "Exigent Extermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[84963] = { title = "Sealing the Shadows", description = "No, no, no! The Shadowguard are ransacking the city and our defenses are crumbling! We even invested in new security golems after the city was last breached, but we haven't had time to activate them.\n\nWait... I have an idea. The Shadowguard--some of them must have looted entropic cores that we can use to activate the golems. \n\nPlease, you must take them down and retrieve those cores. We need to get those golems online to protect our investments! Uh, I mean, our city!", objectives = "Collect 5 Saturated Entropic Cores from Shadowguard within Tazavesh.", progress = "Got those cores that Om'en wanted?", completion = "These look like they're in good condition! Okay, let's go ahead and move on to the next phase of this plan." }
WordHunterWoW_QuestEN[84964] = { title = "Heroes Among Shadow", description = "{name}! These people may not be my own, but we cannot stand by while the Shadowguard cut them down. You and I, we can make a difference! \n\nWe need to get out there, rescue the civilians, and bring them to safety. The city may be in chaos, but we can still be the shield they need.", objectives = "Rescue 8 Tazavesh Civilians.", progress = "The people are still out there, <name>!", completion = "Good. We made a difference here!" }
WordHunterWoW_QuestEN[84965] = { title = "Core Contributions", description = "The entropic cores we collected will be crucial in our defense.\n\nUse the entropic cores to activate the market guardians scattered around the city. Once reactivated, these golems will join our fight and help us push back the invaders.\n\nTime is of the essence, {name}. The fate of Tazavesh rests in your hands.", objectives = "Activate 5 Market Guardians scattered around Tazavesh.", progress = "Any of the guardians we activate should help stabilize the situation.", completion = "Excellent! That'll go a long way toward securing the city." }
WordHunterWoW_QuestEN[84966] = { title = "Break the Assault", description = "", objectives = "" }
WordHunterWoW_QuestEN[84967] = { title = "The Shadowguard Shattered", description = "The commander of the Shadowguard, Shadowlord Al'zar, has assaulted this shelter of the Trust. I am preoccupied with assisting these injured brokers. I dare not leave, or their soul's energy will pour out.\n\nI must depend on you, {name}. Venture forth and eliminate Shadowlord Al'zar. His demise will cripple the Shadowguard's assault on Tazavesh. \n\nThe fate of the city rests on your shoulders.", objectives = "Kill Shadowlord Al'zar in Tazavesh.", progress = "Go. We will come as soon as we can.", completion = "Without their leader, the Shadowguard's assault on Tazavesh is crippled! For that, you have my gratitude.\n\n<He pauses for a weighty moment.>\n\nHowever, do not let this victory lull you into a false sense of security. There are darker forces at play--far more dangerous than the Shadowguard. \n\nTo resist them, we will need every advantage we can get... even those we would normally not consider." }
WordHunterWoW_QuestEN[84971] = { title = "For Love of Grog", description = "", objectives = "" }
WordHunterWoW_QuestEN[84972] = { title = "Chipping the Void", description = "Greetings. I am Driruj. I think you could help with a project of mine. \n\nThe nearby expanse of purple-hued crystal is ripe with potential. The void-infused glass could have many uses, from being a spell reagent to being melted down for crafts. I can't get near it myself, but someone like you will have no trouble at all!\n\nBring me back some samples of the void glass so I can assess their worth to future buyers.", objectives = "Collect 6 Void Glass Samples from the Clefts of Unreality.", progress = "I am preparing to move off world before what's left of K'aresh crumbles away. There are many potential uses, and therefore potential markets, for this newly created void glass. \n\nPotential equals profit, and profit means I can make a new life on a less volatile world.", completion = "Well? Let me see what you procured." }
WordHunterWoW_QuestEN[84973] = { title = "Of Motes and Husks", description = "Regrettably, the void glass was too unstable. However, I have another idea. I believe I can stabilize the glass, but only at the moment of its creation. First, I need motes from the wyrms outside the eco-dome to power my device.\n\nWhile you're out there, hunt down some of those krolusks as well. Their husks can be ground down to make a pleasing beverage for which the folk in Shattrath will pay the highest of prices.", objectives = "Collect 4 Dune Wyrm essences and 6 Krolusk shells.", progress = "Anything can be turned into profit, if you have the right market. It's all about knowing your buyers and finding that which they most desire. \n\nI still think the void glass will be the most lucrative for me, but it needs to be able to hold together more solidly.", completion = "Ah, you return with motes and husks for me?" }
WordHunterWoW_QuestEN[84974] = { title = "Shards of Hope", description = "I still believe void-infused glass is my ticket out of here.\n\nThe problem lies in the creation process itself. The motes you brought me can help stabilize the glass with the help of void energy. Lucky for us, there are numerous void surges on the edges of the glass crevasse.\n\nI have charged a device with the motes. All you need to do is channel void energy through it! Stand where a surge is about to happen and then collect the glass that's formed. Easy! Oh, it might tingle a bit...", objectives = "Collect 20 Void Shards.", progress = "There are many potential uses, and therefore potential markets, for newly created void glass. If we can get this right, I should be set up comfortably in a new home by week's end!\n\nIf you hold the device while standing in the void surges, the energy from the motes should help create more stable fragments.", completion = "Well? Let me see what you procured." }
WordHunterWoW_QuestEN[84985] = { title = "Not Ready on Set", description = "Oh {name}, I am glad to see you again.\n\nMy superiors have informed me that I'm responsible not only for the guests here, but for everyone putting on celebrations!\n\nNow I'm hearing that Dapperdew in Ardenweald is trying to put on a new play and running into problems.\n\nWould you mind checking in on the situation? I can hardly manage this celebration, let alone whatever is happening in the Shadowlands.", objectives = "Find Dapperdew in Ardenweald.", completion = "Welcome! Are you here to help with the stage preparations?" }
WordHunterWoW_QuestEN[84993] = { title = "Devourer Attack: The Oasis", description = "", objectives = "" }
WordHunterWoW_QuestEN[84994] = { title = "Evidence of Effect", description = "", objectives = "" }
WordHunterWoW_QuestEN[84995] = { title = "Pictures! Pictures of Undermine!", description = "", objectives = "" }
WordHunterWoW_QuestEN[84996] = { title = "Vereesa's Tale", description = "We came here so Vereesa could get closer to the source of her visions. Unfortunately, it has only made them stronger, not clearer.\n\nBut this is her story. She should be the one to tell it.", objectives = "Hear Vereesa Windrunner's tale.", completion = "This seems a fitting place to honor my late husband, Rhonin.\n\nWe should get on with the ceremony." }
WordHunterWoW_QuestEN[84997] = { title = "What Might Come", description = "Thank you for coming with us, {name}. I'm long overdue in saying goodbye to my dear Rhonin.", objectives = "Witness Vereesa's ceremony.", completion = "Ugh... <Vereesa doubles over.>\n\nForces of the Void... attacking. Why here... now?" }
WordHunterWoW_QuestEN[84998] = { title = "Bringer of the Void", description = "Go with... Arator. Slay... their leader.", objectives = "Slay Voidbringer Aqu'lir.", completion = "The pain is easing a bit, but I still need a moment." }
WordHunterWoW_QuestEN[85001] = { title = "Blessings Be Upon You", description = "These innocents were simply trying to clean up the ruins, but the cultists are slaughtering them. We must come to their aid!\n\nChampion, I am certain that you and I can do this if we work together.", objectives = "Help Arator to rescue 8 Dalaran Custodians from the clutches of the Twilight's Blade.", progress = "These poor souls are imperiled through no fault of their own!", completion = "I'm unsure why these cultists are coming after my family, but they won't succeed!" }
WordHunterWoW_QuestEN[85002] = { title = "Off to Tazavesh", description = "It's imperative we seek my mother's counsel. But before we can do that, we'll have to find her.\n\nLast I heard, she was out hunting in the Great Dark Beyond on a world known as K'aresh.\n\nLucky for us, I thought ahead and asked Khadgar for a portal scroll to go directly there. I'll meet you on the other side.", objectives = "Regroup with Arator in Tazavesh, the Veiled Market, on K'aresh.", completion = "Thank you for coming with me, <name>. I know I have much to learn. I'm just trying to live up to the family name.\n\nNow all we have to do is find my mother on this shattered world." }
WordHunterWoW_QuestEN[85003] = { title = "Restoring Operational Efficiency", description = "Locus-Walker was brought into the Trust to handle such a violent crisis of the Void. He says you are some kind of hero or champion. Good. We are in need of such a thing.\n\nTazavesh is under threat from the Void. The Shadowguard! They threaten the work of the Trust and my reputation as an administrator.", objectives = "Help the brokers of Tazavesh by assisting with their issues.", completion = "All the problems are solved. At least, all the problems that were on my ledger that I was responsible for." }
WordHunterWoW_QuestEN[85005] = { title = "A Radiant Call", description = "I have an urgent missive for {name} from Mylton Wyldbraun, second in command of the Flame's Radiance!\n\nHallowfall requires what strength we can muster and the Flame's Radiance seeks volunteers to join the fight against the remaining Sureki forces.\n\nPlease report to Wyldbraun without delay.", objectives = "Meet Mylton Wyldbraun at the Flame's Radiance camp in Hallowfall.", completion = "I see you received my message <name>, wonderful! We can always use more capable soldiers among the ranks of the Flame's Radiance." }
WordHunterWoW_QuestEN[85006] = { title = "Those We Have Lost", description = "Ah, traveler! This was one of the first locations to show a response to our attempts to rejuvenate the land. We're actively studying why it happened at this location in particular.\n\nI have another experiment I wish to run, but I need some extra sources of power. The souls that litter the dunes are unfortunately lost, but we may let them serve one last time by using their energy.", objectives = "Collect Flickering Essence.", progress = "How did the collecting go?", completion = "Ah, yes. This should be enough to cover what we need for my next step." }
WordHunterWoW_QuestEN[85007] = { title = "Extended Reach", description = "I'm very curious on why the influence of this restoration stopped where it did, as are my fellow colleagues. We set up some devices at the edge of the dunes to track the fluctuation in various energy types.\n\nThey have probably sat out there long enough for an initial reading. Could you go gather that info for me?", objectives = "Gather readings from the Broker Pylons.", progress = "Hopefully the devices were easy to find?", completion = "Hmm... Nothing here seems out of the ordinary..." }
WordHunterWoW_QuestEN[85008] = { title = "Machinations of Memory", description = "Well, the readings aren't anything to be concerned about...\n\nSo we'll move on to the next step of my experiment. This console here is the central piece of our system to rejuvenate the area. I'm hoping that if we hook it up to a significant charge, it may stabilize the area even more. Could you help me set up the energy containers as I adjust the machine?", objectives = "Interact with the console.", progress = "Yes?", completion = "Fascinating! It worked!\n\nWe'll need to run some immediate tests." }
WordHunterWoW_QuestEN[85009] = { title = "Those We Have Yet to Save", description = "The fauna here seem to be the same in shape as what would have been found nearby when K'aresh was still intact, but they are acting rather oddly for their species.\n\nI wonder if we could give them one last push and fully bring them into being. Take the last of the energy. I have a device that should let you channel it into them.", objectives = "Recharge 6 Flickering Ephemera.", progress = "Have you finished our experiment?", completion = "They... dissipated? No, no, no. That can't be!\n\nSurely something in my calculations is wrong! We probably just disrupted them instead of helping them!" }
WordHunterWoW_QuestEN[85011] = { title = "Where in K'aresh is Alleria Windrunner?", description = "While you were on your way, I took the liberty to ask around. These brokers seem friendly enough, but be warned... part of the city is still under attack by a group of ethereals known as the Shadowguard.\n\nI managed to get a lead on a few traders who might have crossed paths with my mother recently.\n\nWe should go before her trail runs cold.", objectives = "Discover the location of Alleria Windrunner by asking around Tazavesh, the Veiled Market.", progress = "<Umbric looks at you with curiosity.>", completion = "If Vereesa's vision is true, Silvermoon must be defended. The ren'dorei will answer the call. I'm sure of it.\n\nIn the meantime, let's get you to Alleria." }
WordHunterWoW_QuestEN[85013] = { title = "Darkfuse Precipitant", description = "", objectives = "" }
WordHunterWoW_QuestEN[85017] = { title = "Tracking Quest to Send Mailer [DNT]", description = "", objectives = "" }
WordHunterWoW_QuestEN[85018] = { title = "Packets of Promises", description = "I will not wait a moment longer. I have arranged for transport outside of the dome, and it will be arriving soon. \n\nWill you meet me outside? I have one last thing I would ask of you.", objectives = "Talk to Driruj.", progress = "Driruj is a fool! He's likely to burn through his wrappings with his hot-headedness. He'll be back.", completion = "Well? Is he ready to apologize and get back to work? \n\n<You hand him the satchel of seeds.>\n\nWhat's this, now?" }
WordHunterWoW_QuestEN[85019] = { title = "An Outcast's Request", description = "I felt it. Something happened in that dome. Something--no... someone...\n\nMy friend, I do not know your name or where you came from, but this is it! It has to be!\n\nThe ruined town of Sufaad to the southeast of here was where I resided as a Wastelander. Please go there and bring back my scepter, prayer book, and ceremonial bowl. There was no time to pack. I just ran, so the items could be anywhere within the town.", objectives = "Retrieve Outcast Hizfran's belongings from North Sufaad.", progress = "Once I have my belongings, I will be able to walk the path of the old ways. It is time to retake my true oath.", completion = "I knew it from the moment I saw you. The time is right for K'aresh to have his priests back." }
WordHunterWoW_QuestEN[85020] = { title = "The Blood of K'aresh", description = "In the old days, we used certain deep-mined salts in cleansing processes and rituals. As you can see around you, mining is no longer valid, as these fragile rocks are hanging on to each other.\n\nOn the day of the Devouring of K'aresh, a never-before-seen mineral surfaced. The Blood of K'aresh is a blue mineral with some deposits to the west of here. Even though K'aresh is dying, I should follow the old traditions to the end.\n\nPlease collect deposits from sand striders or veins and bring them to me.", objectives = "Collect 20 Blood of K'aresh deposits.", progress = "Although the Blood of K'aresh may not have existed prior to the Devouring like other minerals, it came from within our world and thus should still be usable for the process.", completion = "Yes. These will do. I will grind them to fine powder and use them to cleanse my items in my ritual of return." }
WordHunterWoW_QuestEN[85021] = { title = "Cleansing the Void", description = "Now that you have brought me all that I need, the ritual of return can begin.\n\nYou see, stranger, the items you recovered were stowed in my hovel for over a hundred thousand years. The Void that surrounds us leaves its mark on everything it touches.\n\nWhile grinding the mineral removed the impurities of the Void, I still need to cleanse myself and the items. Please help me with the ritual. I do not foresee any distractions or issues. We are very close now.", objectives = "Help Outcast Hizfran with the ritual of return.", progress = "Almost there, stranger... <name>. That is your name, is it not?", completion = "The ritual of return is over, but...\n\nDid you feel it?" }
WordHunterWoW_QuestEN[85022] = { title = "Priest of the Old Ways", description = "{name}, I suspect that a living manifestation of the Void came out of myself and the items. I cannot, with good conscience, take on the mantle of a priest of the old ways while these manifestations are out there.\n\nI have a final request for you.\n\nGo find these creatures and slay them. Then, I will be able to reassume the mantle of priest.", objectives = "Slay 3 void manifestations.", progress = "One step, <name>. One last step.", completion = "You have done it. Nothing I can give you is a good enough reward for what you have given me.\n\nFinally, my vision of you from all those years ago makes sense. You have saved me--my soul. \n\nThank you." }
WordHunterWoW_QuestEN[85024] = { title = "Toy Trouble", description = "Adventurer, Maru is once again in need of your aid.\n\nShe has an urgent matter that she would like to discuss with you.", objectives = "Speak with Maru.", completion = "Yaay you're here to halp!" }
WordHunterWoW_QuestEN[85025] = { title = "Operation Toy Rescue", description = "A sneaky thief has taken some of my friends' toys!\n\nYou're a good sleufer now, right? Can you help my friend Yennu find his stolen toy? You'll find him on da Dragon Isles.", objectives = "Find the missing toys.", completion = "Wow you're an expert toy rescuer! Who do you fink stole the toys in the first place?\n\nWe should go through da clues you found and see if we can figure out the culprit! Come back tomorrow and we can go over da evidence." }
WordHunterWoW_QuestEN[85026] = { title = "Where Legends are Made", description = "There's so much to catch you up on {name}! \n\nWhere do you want to start?", objectives = "Select a Timewalking Campaign from Chromie.", progress = "Oooh, that one is my favorite!", completion = "Come back to me if you want me to set you on a different path!" }
WordHunterWoW_QuestEN[85027] = { title = "Lorewalking: The Protectorate", description = "I have long been curious about the ethereals, who first came to Pandaria when the Mists parted. A mysterious group, they are reticent to speak of their history... but I am perhaps more persistent than most in my inquiries.\n\nSo! Who are these strangers? What do we know of their history? We must piece it together, it seems. \n\nBut our tale begins in Outland, where a hero joined a group of ethereals in Netherstorm to aid them with their cause.", objectives = "Follow Cho's guidance to learn about the ethereals.", completion = "With Salhadaar and Dimensius defeated, it seemed the largest problems facing the ethereals had at last been solved." }
WordHunterWoW_QuestEN[85028] = { title = "Lorewalking: The Brokers", description = "The ethereals are most fascinating indeed, but in my studies I have encountered another race of creatures who share many similarities with the ethereals. I feel we should speak of them as well--the brokers.\n\nThey share a nomadic nature, a desire to collect rare and unusual antiquities, and a penchant for trade.\n\nYet the brokers do not exist on Azeroth. Instead, they dwell in the Shadowlands... the land of death.", objectives = "Follow Cho's guidance to learn about the brokers.", completion = "I find it fascinating indeed how much these two races have in common, don't you?" }
WordHunterWoW_QuestEN[85029] = { title = "Lorewalking: Locus-Walker", description = "While the Protectorate of Outland may have stopped Dimensius and Salhadaar, the Ethereum remained. And as Salhadaar had wished, they chose to embrace the Void. \n\nNot just embrace it--become it. It twisted them into shadows of themselves, consumed with the pursuit of power.\n\nBut there was one ethereal, Locus-Walker, that sought to harness the Void for more altruistic purposes. His history is entwined with an elf from our world--Alleria Windrunner.", objectives = "Follow Cho's guidance to learn about void ethereals.", completion = "Locus-Walker's intentions do indeed seem to be good, though there are those who question both him and Alleria to this day." }
WordHunterWoW_QuestEN[85032] = { title = "What Is Left of Home", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", objectives = "Speak to citizens of Tazavesh and members of the Trust.", progress = "There will be a day when K'aresh is restored.", completion = "This is what we are fighting for, <name>. We can only save fragments of K'aresh, but we can prevent other worlds from sharing our dreadful fate." }
WordHunterWoW_QuestEN[85035] = { title = "Locus-Walker, Telogrus Ranger", description = "I apologize for interrupting your conversation, mortal. But it was your discussion that drew Ve'nari's attention. She hears much, after all--especially when her name is involved. \n\nI have been sent with an object for you to deliver to Locus-Walker. He is an ethereal that dwells within Telogrus Rift. I believe the \"void elves\" of your world also reside there.\n\nThere is no need to travel. I will provide a portal to where you must go. Will you assist her in this task?", objectives = "Deliver Ve'nari's device to Locus-Walker in Telogrus Rift.", progress = "Why have the Shadowguard come here, of all places?", completion = "A delivery for me? This is most curious. Very well, let me have it then... and you have my thanks for helping fend off the Shadowguard." }
WordHunterWoW_QuestEN[85036] = { title = "Veni Vidi Ve'nari", description = "A broker sent you with this device? And they were sent to you by Ve'nari?\n\nThis does not bode well.", objectives = "Witness the conversation with Locus-Walker.", progress = "I have much to think about, my friend--and much to add to my studies!", completion = "So Locus-Walker and Ve'nari knew each other? Are you certain, my friend? \n\nIt seems my research was not unfounded after all. \n\nI sought to expand your knowledge of the ethereals, but you have expanded mine instead! You have my thanks." }
WordHunterWoW_QuestEN[85037] = { title = "That's a Wrap", description = "The possibilities have begun to narrow. We are on the cusp of victory. Are you ready, my champion, to fulfill your oath against Dimensius?\n\n<Xal'atath chuckles.>\n\nVery well. I have some promises of my own to keep. Let us formalize our defense against Dimensius by the platform toward the manaforge.", objectives = "Speak to Xal'atath to assemble the Reshii Ribbons.", progress = "What is Xal'atath's game here? She had ample opportunity to trick us.", completion = "Stay vigilant my friend. Xal'atath's games have not yet unfolded. \n\nWe must be prepared for her inevitable betrayal." }
WordHunterWoW_QuestEN[85039] = { title = "Compromised Containment", description = "Somehow, an artifact in the Menagerie has broken open, unleashing a swarm of furious arcane creatures. They're wreaking havoc, and havoc is bad for the project. I need someone capable of getting this situation under control with no questions asked.\n\nIf you can get down there, clear your way through the creatures, and seal that artifact... I'll make it worth your while.", objectives = "Kill Arcane Creatures and seal the Unstable Artifact.", progress = "Have you completed your assignment?", completion = "You sealed the artifact? Excellent! The remaining creatures should dissipate in time. \n\nYou've handled the danger with remarkable skill. As promised, here are your rewards." }
WordHunterWoW_QuestEN[85042] = { title = "The Final Toy", description = "Maru discovered that one of her toys is now missing!\n\nCould this be related to the other missing toys that you previously helped her friends with?", objectives = "Speak with Maru.", completion = "Nooo! My toy is gone!" }
WordHunterWoW_QuestEN[85043] = { title = "The Toy Thief", description = "My toy! It's been stolen!\n\nWe have to figure out who da culprit is before they take more toys!", objectives = "Discover the toy thief.", progress = "Did you find my toy?", completion = "Yay! You found ALL the toys! How did dat big doggo collect so many?\n\nI'll have to go see if anymore of my toys are in da pile...\n\nThanks for all the halp." }
WordHunterWoW_QuestEN[85044] = { title = "DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[85047] = { title = "A Pirate Predicament", description = "I was recently made aware of a small group of Booty Bay Buccaneers who have landed and set up camp just outside the celebration area to the north.\n\nPirates aren't inherently a problem, per se, but they do introduce an element of chaotic unpredictability. I know you're busy, but would you mind checking on them to see if they need any assistance?", objectives = "Head to the Booty Bay Buccaneers camp.", completion = "Ahoy there! You look like a capable thinker. Got a sec to lend a hand?" }
WordHunterWoW_QuestEN[85051] = { title = "Beach Comber", description = "There's a peculiar mechanical gnome scouring the beach nearby for valuable scrap metals. I am concerned for his safety but also intrigued. I just wonder what he's trying to find!\n\nMaybe he would be willing to share anything he finds in exchange for your assistance...\n\nCould you aid him in recovering any valuable items?", objectives = "Assist Kerchunk in his search for 24 Salvageable Scrap", progress = "Have you found any Salvageable Scrap? I'm looking for all I can find.", completion = "A strange gnome he may be, but his desire to locate, salvage, and re-purpose old items is quite commendable." }
WordHunterWoW_QuestEN[85052] = { title = "A Lucrative Opportunity", description = "Most fortuitous greetings, offworlder!\n\nI have been stuck for an eon at this post checking manifests one after another. This is not real trade. Real trade is done on the streets of Tazavesh!\n\nIt just so happens that a contact of mine from your world was unloading waste cargo. I bought the whole supply. Expired storage contracts of some sort. However, I know better than to be trading without a permit.\n\nIt would bring good fortune to my endeavor to have your help with this. Can I count on you, {race}?", objectives = "Seek out Cartel Boss Xy'eolm in Tazavesh on K'aresh.", completion = "Xy'vez sent you? That little scoundrel can't even face me himself. Ha!" }
WordHunterWoW_QuestEN[85053] = { title = "Obtaining Permits", description = "There is a difference between securing a permit and securing permission to sell in Tazavesh.\n\nXy'vez is a licensed dealer. He can buy and sell as he pleases in accordance with the authorities. However, I am glad he knows his place. If you are on my streets, you need my permission.\n\nNot everyone knows this. Cartel Ba likes to test the waters. I'll award your permission if you teach them a lesson.", objectives = "Obtain permission for Vaultkeeper Xy'vez in Tazavesh.", progress = "Have you done what I asked?", completion = "Very well. Xy'vez is free to buy and sell whatever he pleases on my streets." }
WordHunterWoW_QuestEN[85054] = { title = "Articles of Acquisition", description = "Take this ledger to Xy'vez. Let him know I expect dinars upfront and on time. There are to be no discrepencies between my records and his, do you understand?\n\nYou may head to the market to inform him. Knowing traders like him, he'll have already found a spot to set up shop.\n\nThis venture has my blessing. Don't let it become unprofitable or we'll be seeing each other again, offworlder.", objectives = "Return to Vaultkeeper Xy'vez in the market of Tazavesh on K'aresh.", progress = "Do we have good news, offworlder?", completion = "The boss wants a high price, but it is a fair ask of a new venture. We will succeed quickly or we will fail quickly.\n\nLet's get to work." }
WordHunterWoW_QuestEN[85055] = { title = "Expired Goods", description = "Now then, on to business. I hear tale that your world is full of heroes on adventure. And where there's adventurers, there's need for storing their treasures. Always.\n\nThus, you have turned to our kin to keep them safely deposited between realms. Yet not one of you read the contract. We have since ceased such services and returned goods to their owners. \n\nYou and I, {name}, are selling opportunities to purchase what remains. Blind of course. Help me prepare.", objectives = "Help Vaultkeeper Xy'vez prepare the void storage vaults for sale in Tazavesh on K'aresh.", progress = "Always so much to prepare before a first sale.", completion = "Excellent! With that out of the way, we can begin sales." }
WordHunterWoW_QuestEN[85059] = { title = "A Piece of the Action", description = "Game on table look like fun. But Skaggit no want Jack to play. Maybe you can?\n\nSneak in and put a bet down. We see who wins!", objectives = "Contribute to an event on the Siren Isle Command Map.", progress = "Did you put down a bet?", completion = "Jack know you could pick winner!" }
WordHunterWoW_QuestEN[85060] = { title = "Pirate Foods and Superstitions", description = "Our trusty cook, Cooktholomew, was lost at sea. Quite tragic that was, but now all the more tragic for us here! We don't dare set sail again without the lucky feast ol' Cooktholomew would prepare for us before each voyage.\n\nWe've tried to make out his scribbles, but alas, we only managed to make the ink run.\n\nMe matey here swears he heard Cooktholomew say once he only brought copies out to sea. If that be true, the originals must be back in Booty Bay, somewhere near his bunk!", objectives = "Help the Booty Bay Buccaneers figure out how to recreate Cooktholomew's lucky feast.", progress = "Cooktholomew and I have spun many a yarn talking about words and language. He was a lot deeper than most folk around here gave him credit for.", completion = "<Scowling Rosa looks over the notes.>\n\nThis looks like a simple enough substitution cipher. It will take me about a day or so to work on it, so I'll hold onto it and send you word when I have something for you." }
WordHunterWoW_QuestEN[85071] = { title = "Skyrocketing Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings." }
WordHunterWoW_QuestEN[85075] = { title = "To Stormsong", description = "We have need of more species to help pollinate. I have studied your world, and I believe your bees in Stormsong Valley will be best. Not the fire ones though. Too dangerous. \n\nBring back some bees and we can see if they are suitable. Take this communicator in case I need to contact you.", objectives = "Travel to Stormsong Valley in Kul Tiras to get some bees for Ve'nari.", progress = "Where did you come from?", completion = "Random people appearing from thin air was not what I had on my list of expected interactions today.\n\nStill, you look capable. Perhaps you'd be interested in helping me out here?" }
WordHunterWoW_QuestEN[85076] = { title = "Don't Bee Crazy", description = "Something is agitating the bees, and I suspect it's these honey-crazed maulers!\n\nTake some down and see if it helps. \n\nEven if it doesn't, you're doing the world a favor. They are completely out of control!", objectives = "Slay 10 maulers in the Highland Flats and Mildenhall Meadery.", progress = "The poor bees...", completion = "Good job. I mean, it didn't help. The bees are still upset.\n\nBut you did make the world a safer place, so credit where credit is due!" }
WordHunterWoW_QuestEN[85077] = { title = "Sticky Fingers", description = "Stormsong has some of the biggest and best pollinators on Azeroth--when they aren't angry at least. If you are looking to take these, you'll need to try to calm them down.\n\nIt looks like their honey is being stolen. Try to take some honey back from those honey... blob... things?\n\nCan't hurt right? Sorry. I'm more of a plant person than a bee person. They just come with the territory!", objectives = "Collect 7 Honey Globules at the Mildenhall Meadery.", progress = "Did you get the honey?", completion = "<Alaenra looks at your very sticky fingers.>\n\nWell done! I... shan't shake your hand though. Just well done.\n\nUnfortunately, the bees are still very upset. Still, we might find a use for the honey later?" }
WordHunterWoW_QuestEN[85078] = { title = "Bee in the Bonnet", description = "While you were out, I scouted some of the smaller bee hives. They all look like they've suffered damage. \n\nWe should investigate them. Maybe that's the cause of their aggression?", objectives = "Investigate 4 Bee Hives.", progress = "What could have driven something to destroy so many hives?", completion = "Oh no--the poor queen bee! We have to save her!" }
WordHunterWoW_QuestEN[85079] = { title = "Such a Sleebee-head", description = "We need to deal with the hive guardians one way or another if we are going to investigate this place. \n\nI do hope we don't have to kill them.", objectives = "Tranquillize or slay 5 Hive Guardians.", progress = "We should keep as many bees alive as possible.", completion = "Bees are super pollinators. It's incredibly unfortunate they are so murderous right now. Normally, they are quite calm!" }
WordHunterWoW_QuestEN[85080] = { title = "An Un-Bee-lievable Solution", description = "If we can save the smaller bees, they can join the queen's colony. I just wish we had some way of capturing or transporting them. \n\nDo you have any ideas? Perhaps that friend of yours has something?\n\nIf you come across any of the larger bees... I worry they may be beyond saving. Do what you have to do.", objectives = "Collect the Anima Vacuum and use it to vacuum up 15 Honey Bees.", progress = "Have you rescued the bees?", completion = "That was an extremely unorthodox method of capturing bees. But it was a successful one!" }
WordHunterWoW_QuestEN[85081] = { title = "Beehemian Rhapsody", description = "We need a way to lure out the queen so we can take her away from here. \n\nOh! The honey you gathered earlier! Put that out to lure her, then catch her in this ventilated jar. \n\nYou said you were after bees? I think she'd be a great fit.", objectives = "Place the Honey Pot and use it to lure out and rescue the Queen Bee.", progress = "If we can get her to safety, and bring some of her hive, they can rebuild.", completion = "We saved her! \n\nLet's take her to... K'aresh was it? Always nice to see new parts of Azeroth." }
WordHunterWoW_QuestEN[85082] = { title = "To K'aresh", description = "We've secured the queen and apparently sent some bees to K'aresh. \n\nSo... How do we get there?", objectives = "Return to the Oasis on K'aresh.", completion = "Congratulations. You have secured the bees, after much delay. They are in the Atrium.\n\nOnce the queen bee is delivered, we may begin our research." }
WordHunterWoW_QuestEN[85083] = { title = "Photogra-Bee", description = "The bees seem to be doing very well in this new environment. They are even starting to pollinate the plants here.\n\nWe should document it. It's not science if you don't write it down. You'll find them mostly around the plants.", objectives = "Document 10 Honey Bees.", progress = "Have you documented the bees?", completion = "Have you thought of getting into science yourself? You're a dab hand at it." }
WordHunterWoW_QuestEN[85084] = { title = "Bee Strong", description = "It's taking the hive a while to get up and running, and they are low on honey. \n\nThankfully, you gathered plenty of honey back in Stormsong! Could you feed the queen?", objectives = "Feed the Queen Bee.", progress = "I think the bees will do well here.", completion = "Look at her. She's so happy not worrying about those horrible death bees." }
