WordHunterWoW_QuestEN[85500] = { title = "Hazardous Waste", description = "", objectives = "" }
WordHunterWoW_QuestEN[85502] = { title = "Festive Reflections", description = "Oh good, you're back. I have my hands full here and Detective Jones has been asking for your help on some new case.\n\nNot that it seems to matter. For all the good we do for the guests, I think this line--if you can still call it that--has only grown longer!\n\nI should get back to it, and you should talk to Detective Jones.", objectives = "Speak with Detective Jones.", completion = "Do you have a moment? We have a very special case ahead of us." }
WordHunterWoW_QuestEN[85503] = { title = "A Surprising Investigation", description = "Well, look who's back to solve more cases.\n\nIt seems that Chromie has been fiddling with time again and some imposters have popped up around the celebration area.\n\nAll you need to do is identify who doesn't belong and send them to Chromie. This should be a breeze for you.", objectives = "Solve the case given to you by Detective Jones.", progress = "How goes it?", completion = "This was quite a surprise! It's nice to get a chance to relax." }
WordHunterWoW_QuestEN[85512] = { title = "Rooting Out Counterfeits", description = "", objectives = "" }
WordHunterWoW_QuestEN[85513] = { title = "Underrider Grease", description = "", objectives = "" }
WordHunterWoW_QuestEN[85514] = { title = "If They're Not Using It...", description = "", objectives = "" }
WordHunterWoW_QuestEN[85515] = { title = "Free Samples!", description = "", objectives = "" }
WordHunterWoW_QuestEN[85518] = { title = "Scalper Scum", description = "", objectives = "" }
WordHunterWoW_QuestEN[85519] = { title = "Boom and Burst", description = "", objectives = "" }
WordHunterWoW_QuestEN[85523] = { title = "Mildewed Celebration Crate", description = "<The crate is covered in a growing mildew from the jungle climate. It looks like you found it before the goods inside were spoiled. Alyx would appreciate the supplies returned.>", objectives = "Return the Mildewed Celebration Crate to Alyx.", progress = "Oh, I am so busy. But what can I help you with?", completion = "Oh, you found a missing crate! That's great!\n\nWhat is that black stuff? Why don't you just set it down I will deal with it later. \n\nI really appreciate you returning these. If you find any more please bring them to me." }
WordHunterWoW_QuestEN[85524] = { title = "Disarming the Darkfuse", description = "", objectives = "" }
WordHunterWoW_QuestEN[85526] = { title = "Scum Bag", description = "", objectives = "" }
WordHunterWoW_QuestEN[85527] = { title = "Buccaneer Bonzai", description = "", objectives = "" }
WordHunterWoW_QuestEN[85528] = { title = "Recrewtment", description = "", objectives = "" }
WordHunterWoW_QuestEN[85529] = { title = "Past Glory", description = "Marran's\"Red Dawn\" has left the city and peace has returned to Stromgarde. \n\nAt least for now.\n\nFaerin left for the countryside. She said she wanted to check on Newstead and Refuge Point, but I think she wanted to get out of Stromgarde.\n\nShe came here with such enthusiasm. I should not have tempered it so harshly. I feel in the end it was I who needed to learn a lesson.\n\nWe should check in on her.", objectives = "Speak to Faerin at High Perch.", progress = "<Faerin looks lost in thought as she again gazes at Thoradin's Wall.>", completion = "Danath is right. Legends are just legends. We shouldn't try to live in them, blinded by pride.\n\nInstead, those legends should inspire us to make the world as we hope it should be.\n\nLight willing, we will remember the past but work for a better future. For all of us." }
WordHunterWoW_QuestEN[85531] = { title = "Earth-Encrusted Gem", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
WordHunterWoW_QuestEN[85532] = { title = "The Wealth of a Kingdom", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
