WordHunterWoW_QuestEN[85535] = { title = "Kej", description = "", objectives = "The work of the Severed Threads proceeds apace. As such, our patrons have decided to reward your continued dedication.\n\nNow take this and begone. You're drawing suspicious eyes." }
WordHunterWoW_QuestEN[85536] = { title = "Resonance Crystals", description = "", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude." }
WordHunterWoW_QuestEN[85537] = { title = "Crystals", description = "", objectives = "The Arathi truly appreciate all your help in this dangerous land. Please accept this symbol of our gratitude." }
WordHunterWoW_QuestEN[85538] = { title = "Shinies", description = "", objectives = "So helpful! Kobolds thank you. Earthen thank you. The Assembly thanks you! \n\nCandle for you! No better reward than that!\n\nNo, this candle not made from earwax. Made from beeswax! Smells so nice! You like nice smells, yes? If not, might want to step away from me, ha ha ha. Sorry." }
WordHunterWoW_QuestEN[85539] = { title = "Take Candle!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85540] = { title = "Take Big Candle!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85541] = { title = "Here's a Shiny!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85542] = { title = "Take Really Big Candle!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85543] = { title = "More Shinies!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85544] = { title = "Many Little Shinies!", description = "", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work." }
WordHunterWoW_QuestEN[85545] = { title = "Resonance Crystals", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[85546] = { title = "Resonance Crystals", description = "", objectives = "You are a valued asset to the Council, <name>. We request you accept this token of our gratitude, and henceforth be known as an Honorary Councilmember." }
WordHunterWoW_QuestEN[85553] = { title = "Side Gig: Feeling Crabby", description = "Food's a critical resource for any crew that dares to sail the sea. So is gunpowder.\n\nLet's kill two crabs with one stone and get our hands on some of those bombshells out on the Kaja'Coast.\n\nJust don't get yourself blown up while you do it, yeah?", objectives = "Collect 15 Powdery Crab Meat from bombshell crabs on the Kaja'Coast.", progress = "We'll need time to separate the powder from the crab, so get 'em here quick!", completion = "Look at that! Enough meat to feed a whole crew and then some.\n\nWe'll just need to be real careful about gettin' all that gunpowder off. Wouldn't want someone losin' a hand when they go to cook it." }
WordHunterWoW_QuestEN[85554] = { title = "Side Gig: It's Always Sunny Side Up", description = "Pterrordax eggs have been all the rage lately in the Undermine. And what good would the Blackwater name be if we couldn't import high-demand luxury goods?\n\nIf you're interested in makin' some gold, head over to the Kaja'Coast and collect some for us.\n\nOh, and make sure you don't take too many. Consumers these days love when we can label our goods \"ethical.\"", objectives = "Collect 8 Pterrordax Eggs on the Kaja'Coast.", completion = "These are gonna make bank at the high-end brunch joints, mark my words." }
WordHunterWoW_QuestEN[85560] = { title = "TEST", description = "", objectives = "" }
WordHunterWoW_QuestEN[85562] = { title = "Tougher Than We Thought", description = "Hah! I've never been feeling better! Now, we seize back what rightfully belongs to Blackwater, {name}.\n\nThey've turned our prized headquarters into a smuggler's cove for that foul sludge. There are too many crates of Black Blood to deal with right now, but they can't move their cargo without fresh bodies. Let's cut them down.", objectives = "Reclaim the Port Authority from Darkfuse forces.", progress = "There's blood to spill!", completion = "Gallywix should know better than to cross sabers with Blackwater after this." }
WordHunterWoW_QuestEN[85570] = { title = "The Tattered Journal", description = "<The journal almost falls apart in your hands as you leaf through it. \n\nWhat few pages that remain are filled with an erratic scrawling script.\n\nPerhaps Stellin Verasa would be interested in this journal back in camp.>", objectives = "Take the journal to Stellin Verasa back in the Siren Isle camp.\n\nProvided item:", completion = "Oh, hello <name>! What have you got there?" }
WordHunterWoW_QuestEN[85571] = { title = "Scattered To The Winds", description = "My goodness! This journal is missing many of its pages! \n\n<Stellin flips through the journal, careful to not let any loose pages fall out.>\n\nThis journal doesn't look very old... and it seems to be of human origin? Could this be the key to discovering what happened to the humans that came here? What a mystery!\n\nBut less of a mystery if we could find the missing pages... Would you keep an eye out for them while you're out in the field?", objectives = "Collect 5 Journal pages around the isle.", progress = "Have you found any more pages from the journal?", completion = "Wow, look at all these pages! \n\nExcellent work <name>! Now, for the hardest part..." }
WordHunterWoW_QuestEN[85572] = { title = "A Group Effort", description = "This is, um, quite the mess you've handed me. All these pages... what order do they go in?\n\nAha!\n\nThis journal seems to have belonged to a Kul Tiran that came here...\n\n<Stellin looks up, her eyes shining with excitement.>\n\n...and it might hold the key to learning about their time on the isle. \n\nBut the pages are hard to read... perhaps we should ask around to see if anyone can read them?\n\nHere, take a few pages. I'll keep trying to decipher the base journal while you go to camp and ask around.", objectives = "Ask Alta, Skitter, and Ricket if they can read the journal.", progress = "<Stellin adjusts her glasses with a grimace.>\n\nThis... seems like the author's signature. Had... is that a \"d\" or an \"l\"\n\nHad... do.. k--oh! Haddock? Or maybe that's an \"'e.\"", completion = "Oh! <name> I'm glad you're here. I've had a breakthrough with the journal, but first I want to know what you've found.\n\nDid you find anything interesting? Was anyone able to decipher the handwriting?" }
WordHunterWoW_QuestEN[85573] = { title = "Laid To Rest At Last", description = "<Stellin listens as you explain what you've learned and nods gravely.>\n\nThis poor fellow was part of a crew that sailed here aboard a ship called the Maiden's Whisper. They were almost wiped out by a storm, but then even the survivors disappeared!\n\nHe was the last one and... didn't make it either in the end. Perhaps we can put his memory to rest?\n\nI spotted a graveyard out behind the Kul Tiran's base... perhaps setting the journal there amongst his crew's graves will bring his memory some peace.", objectives = "Bring the Tattered Kul Tiran Journal to the graveyard behind the Kul Tiran base in the Abandoned Mines.", progress = "<name>, did you find the graveyard?", completion = "Good. I'm glad that's done... I hope he can rest in peace now with his friends and crew.\n\nI did manage to transcribe a copy of the journal if you're interested in reading it. I thought it might come in handy.\n\n<Stellin pauses, looking thoughtful.>\n\nI wonder though... what happened to the crew? Why did the author end up alone?\n\nIt seems this island still has many mysteries to unravel." }
WordHunterWoW_QuestEN[85574] = { title = "Hazy Celebration Crate", description = "<This crate phases in and out of existence with dark, necromantic energy. Regardless, Alyx would likely appreciate the supplies returned.>", objectives = "Return the Hazy Celebration Crate to Alyx.", progress = "Yes?", completion = "Oh, you found a missing crate! Wonderful!\n\nI really appreciate you returning these. If you find any more please bring them to me." }
WordHunterWoW_QuestEN[85589] = { title = "Ruffled Pages", description = "Many of the wyvern on this isle have crafted their nests from folios, scrolls, and documents they scavenge from the isle's ruins.\n\nBecause of this, their nests may hold the clues we need to understand the full history of this place.\n\nOur scouts have secured grappling holds for you to climb to their nests, but use any means you like to recover the paper the wyverns have used as nesting material. Our knowledge of the isle's history depends on it!", objectives = "Collect 15 Nesting Papers from the wyvern nests around the island.", progress = "I really want to see what's on the papers the wyvern have taken!", completion = "A little nibbled and chewed, but I can still make out the writing on these pages. Great work, <name>!" }
WordHunterWoW_QuestEN[85648] = { title = "Delver's Call: Earthcrawl Mines", description = "HELP WANTED\n\nTroubles continue within Earthcrawl Mines. Fine pay to whoever can handle it.", objectives = "Complete the Earthcrawl Mines delve on any difficulty.", progress = "Are you the one who grabbed the task for Earthcrawl Mines?", completion = "That's one less issue to deal with." }
WordHunterWoW_QuestEN[85649] = { title = "Delver's Call: The Waterworks", description = "NOTICE\n\nThe Waterworks have become unstable. Request aid in addressing issues.", objectives = "Complete the Waterworks delve on any difficulty.", completion = "Commendable work within the Waterworks." }
WordHunterWoW_QuestEN[85653] = { title = "Dipping a Toe", description = "That ring of yours has caused quite a stir, hasn't it? And the history behind it... vrykul? Someone named Cyrce?\n\nI know you and Bargus unlocked more of the ring's potential by scouting the isle but... perhaps you should turn your attention to the sea?\n\nTake your ring into the water and see what happens. Bring whatever you find back to me. I'm a bit of a novice, but I might be able to piece whatever you find back together.", objectives = "Look for more citrines in the waters surrounding Siren Isle.", progress = "Kobyss would give anyone thalassophobia. You're a brave soul looking for gems in that water.", completion = "<Apprentice Tanmar takes the three Singing Fragments and looks at them dubiously.>\n\nYou can tell there is power here. I... hope I can fuse them safely. Here goes nothing. Or everything. Heh.\n\n<Apprentice Tanmar takes out a vial of viscous, golden liquid and begins piecing them together. The liquid flashes with light, and the citrine is whole again. He hands you the repaired citrine.>\n\nImpressed? Don't be. It was fancy glue, to be honest. But hopefully this ring'll further our knowledge of the isle!" }
WordHunterWoW_QuestEN[85654] = { title = "Juicing Up and Storming Out", description = "Well, look. If it ain't {name}, the talk of the camp.\n\n<Didi grabs your hand and looks closely at your ring.> \n\nThat ring on ya finger sure is peculiar, ya sure ya don't want a different one? \n\n<Didi looks up at you and winks.> I'm just yankin' ya chain, let's see what we can do with it!\n\nYa get me enough of that magic metal lookin' stuff we've been finding, and I'll see about gettin' you suited up in the Pummeler over there. \n\nYour ring oughta give it the juice it needs to really wreak some havoc!", objectives = "Acquire enough Flame-Blessed Iron to test out the N.U.K.U.L.A.R Target Painter and TR-06 Pummeler.", progress = "Ya got around to finding some of that iron an' wreakin' some havoc out there?", completion = "Good to see there's still some people that love chaos as much as I do. <Didi wipes a small tear from her eye.>" }
WordHunterWoW_QuestEN[85655] = { title = "Unleashing Her Power", description = "This ring that you and Bargus found has taken you all over the isle learning its history and finding its treasures.\n\nThe ring has aided you in your exploration--and in battle. But, we have never truly pushed the ring to find its limitations.\n\nPerhaps some formal testing is in order. Perhaps we can unveil more of its potential if we invite a bit of danger.\n\nGo now and test the ring against any worthy opponents you can find. Come back to me with your observations.", objectives = "Equip Cyrce's Circlet and fight creatures on the Siren Isle to trigger its hidden ability while in combat.", progress = "Have you engaged in combat testing with the ring? What were your findings?", completion = "What fascinating results. Still, I feel there is much more to learn and process." }
WordHunterWoW_QuestEN[85656] = { title = "The Singing Bandit Catcher", description = "Seems you've gotten the hang of that ring, eh? Maybe you can put it to good use for me. \n\nOur supplies here--especially our gold and flame-blessed iron--have been disappearing!\n\n<Tanmar leans in to whisper.> \n\nNormally I wouldn't suggest this--the Arathi are a trustworthy lot--but the number of incidents is building. and I'm wondering if there's a thief among us.\n\nSee if you can find 'em. They being pretty brazen. I'm sure you can catch 'em in the act somewhere!", objectives = "Catch three thieves.", progress = "Keep your hand on your pockets. There are thieves everywhere, it seems like.", completion = "That's one hell of a tall tale. Knowing all of the oddities spilling out of this isle though, I can't say I'm surprised." }
WordHunterWoW_QuestEN[85657] = { title = "Cyrce Would Be So Proud", description = "It ain't no secret the winds here are terrible. \n\nBut! I don't think we've given that ring there a fair chance at fightin' 'em. I mean, that thing can let ya swim like a fish, make tornadoes outta nothin', and even shock the invisibility off of magical boxes! Surely it's got somethin' to say about a lil' nasty weather, right?\n\nTake my balloon up and see if you can keep it stable usin' that ring of yours. Maybe we can find the trick for stayin' in the sky!", objectives = "Fly in the Skypiercer to see if Cyrce's Circlet can protect you from the high winds.", progress = "If that ring could help us outta storms, that'd be amazin'!", completion = "Looks like the ring does work on high winds an' storms!\n\nYa wouldn't think about givin' a girl the ring as a loaner, would ya? I got some races I could win with that ring... we could be partners! Split our winnings 30/70. How about 40/60? Aw, you're killin' me. Fine, 50/50?\n\nStill no? All right, forgettaboutit. It was a nice dream while it lasted." }
WordHunterWoW_QuestEN[85664] = { title = "Delver's Call: Nightfall Sanctum", description = "CALL FOR AID!\n\nThe Order of Night may have a base set up in a location called Nightfall Sanctum.\n\nIt is imperative that we stop any of their operations as soon as possible.", objectives = "Complete the Nightfall Sanctum delve on any difficulty.", completion = "I heard word someone put a stop to the Order of Night's schemes. Good work." }
WordHunterWoW_QuestEN[85666] = { title = "Delver's Call: Spiral Weave", description = "HELP WANTED\n\nWord is the nerubians have big military operations within the Spiral Weave.\n\nHelp out the survivors of the Dalaran crash by putting a stop to them!", objectives = "Complete the Spiral Weave delve on any difficulty.", completion = "You did it! That should give our forces on the surface a bit of a reprieve." }
WordHunterWoW_QuestEN[85667] = { title = "Delver's Call: The Underkeep", description = "WEAVER'S ORDERS\n\nDark operations are happening within a place called the Underkeep.\n\nI wish for it to halt.", objectives = "Complete the Underkeep delve on any difficulty.", completion = "Excellent work for one such as yourself." }
WordHunterWoW_QuestEN[85678] = { title = "Repair Yourself", description = "Your gear isn't looking too great from your last excursion.\n\nSpeak to Quartermaster Richter to get it repaired.", objectives = "Speak with Quartermaster Richter, then select \"Repair All Items\" to repair your damaged gear.", progress = "Speak with Quartermaster Richter and have her repair your equipment.", completion = "Your gear is looking better already! \n\nYou'll want to keep your gear repaired to avoid any unfortunate surprises." }
WordHunterWoW_QuestEN[85679] = { title = "Repair Yourself", description = "Your gear is nearly destroyed from your last fight!\n\nSpeak with Provisioner Jin'hake to repair it right away.", objectives = "Speak with Provisioner Jin'hake, then select \"Repair All Items\" to repair your damaged gear.", progress = "Provisioner Jin'hake can repair your equipment.", completion = "You'll want to keep your gear repaired if you want to earn honor and glory amongst the Horde!" }
WordHunterWoW_QuestEN[85710] = { title = "Sizing Them Up", description = "We have been trying to do medical checkups on the slatebacks, but they are... aggressive in their disagreement.\n\nVe'nari has provided this shrinking device to help. Collect some for me.", objectives = "Shrink and collect 10 Slateback Roamers.", progress = "<Om'talad is busy trying to smooth out what look like teeth marks on his legs.>", completion = "Ah, this is a much more manageable size. Why, they almost look cute. \n\nThank you. I will perform the tests and release them afterwards." }
WordHunterWoW_QuestEN[85711] = { title = "Unsolicited Feedback", description = "Alice is back, and she's a much better cook than she ever was before she became a <whispers> rat.\n\nBut don't take my word for it. Here, hand out some food and hear it straight from the customers!", objectives = "Serve food to the hungry patrons.", progress = "Did you finish handing out the food yet? What did they think?", completion = "Amazing, isn't it? \n\nI don't think she wants to change back yet, at least until she refines her skills some more. But we have the redberry antidote for when she's ready. Thanks again." }
WordHunterWoW_QuestEN[85715] = { title = "Muse Wanted", description = "", objectives = "" }
WordHunterWoW_QuestEN[85716] = { title = "Rune-Seared Spear", description = "<An elaborate rune-covered spear. Angorla may have interest in studying this weapon.>", objectives = "Deliver the Rune-Seared Spear to Angorla at Flotsam Shoal.\n\nProvided item:", completion = "This is amazing! I can learn so much studying these runes up close." }
WordHunterWoW_QuestEN[85717] = { title = "Precarious Pet", description = "", objectives = "" }
WordHunterWoW_QuestEN[85718] = { title = "A Shining Stone", description = "", objectives = "Task completed. The Council rewards you for assisting with earthen reunification." }
WordHunterWoW_QuestEN[85721] = { title = "Killer Instinct", description = "The hunting training seems to be working with the Thorntail Matriarch, and we'd like to keep up with it. \n\nCan ye have her hunt a few more lapbugs at your direction?", objectives = "Teach the Thorntail Matriarch to hunt Lapbug Skitterers 10 times.", completion = "Death is a natural part of life. \n\nUnless you're a broker. Or an ethereal. Or, ye know, otherwise immortal." }
WordHunterWoW_QuestEN[85722] = { title = "Making a Deposit", description = "<After defeating the devourer invasion, you pulled this solid lump of anima from their leader's stomach. \n\nVe'nari may find this useful for powering the eco-domes.>", objectives = "Deliver the Crystallized Anima to Ve'nari in the Oasis.\n\nProvided item:", completion = "An impressive kill. An even more impressive trade.\n\nYou will be rewarded. I will not have myself in your debt." }
WordHunterWoW_QuestEN[85724] = { title = "Repel the Invaders", description = "A big lunk of a hobgoblin, Skeez, took over the docks around the time that Gallywix had me thrown in the brig. He moved his Darkfuse in, and a lot of my Blackwater lads went missing. Captain took that personal, and so do I. Skeez thinks Gallywix will keep him safe.\n\nLet's kill him.", objectives = "Kill Dockmaster Skeez.", progress = "Still in one piece, eh?", completion = "That's how we mete out justice, both at sea and in port. With the saber." }
WordHunterWoW_QuestEN[85730] = { title = "Salvaging What's Left", description = "The loss of an eco-dome is unimaginable. The death of Om'bera...\n\n<The broker's shoulders rise and fall in what looks like a sigh, though no breath is heard.>\n\nI cannot leave without retrieving the research crates! Her work must live on, even if she cannot. Om'bera's manifest says that there were at least five crates full of research and resources.", objectives = "Return 5 Stolen Research Crates to Om'resh.", progress = "I don't understand the Wastelanders. I thought they were once oracles of Untamed K'aresh. Nature worshipers. Why do they steal from our domes and prevent the Trust's mission?", completion = "Thank you for retrieving the crates. Om'bera's research will help us find a stable biome in time." }
WordHunterWoW_QuestEN[85731] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[85732] = { title = "Express Extermination", description = "", objectives = "" }
WordHunterWoW_QuestEN[85733] = { title = "Daiquiri Disaster", description = "", objectives = "" }
